    function posterEditSnapshot() {
      return {
        posterAnchorOverrides: cloneState(posterAnchorOverrides || {}),
        productImageAdjustments: cloneState(productImageAdjustments || {}),
        posterCopyOverrides: cloneState(posterCopyOverrides || {}),
        trustVisible,
        sourceCopy: {
          title: titleInput.value,
          subtitle: subtitleInput.value,
          cta: ctaInput.value
        }
      };
    }

    function samePosterEditSnapshot(left, right) {
      return JSON.stringify(left) === JSON.stringify(right);
    }

    function updatePosterUndoState() {
      if (posterUndoButton) posterUndoButton.disabled = !generated || !posterEditUndoStack.length;
    }

    function clearPosterEditHistory() {
      posterEditUndoStack = [];
      productWheelUndoActive = false;
      if (productWheelUndoTimer) window.clearTimeout(productWheelUndoTimer);
      productWheelUndoTimer = null;
      updatePosterUndoState();
    }

    function pushPosterEditHistory() {
      if (!generated || isRestoringPosterHistory) return;
      const snapshot = posterEditSnapshot();
      const previous = posterEditUndoStack[posterEditUndoStack.length - 1];
      if (previous && samePosterEditSnapshot(previous, snapshot)) return;
      posterEditUndoStack.push(snapshot);
      if (posterEditUndoStack.length > 60) posterEditUndoStack.shift();
      updatePosterUndoState();
    }

    function restorePosterCopyOverrides(snapshot = {}) {
      Object.keys(posterCopyOverrides).forEach(key => delete posterCopyOverrides[key]);
      Object.assign(posterCopyOverrides, cloneState(snapshot));
    }

    function undoPosterEdit() {
      if (!posterEditUndoStack.length) {
        showToast('暂无可返回的上一步');
        return;
      }
      const snapshot = posterEditUndoStack.pop();
      isRestoringPosterHistory = true;
      posterAnchorOverrides = cloneState(snapshot.posterAnchorOverrides || {});
      productImageAdjustments = cloneState(snapshot.productImageAdjustments || {});
      restorePosterCopyOverrides(snapshot.posterCopyOverrides || {});
      titleInput.value = snapshot.sourceCopy?.title || '';
      subtitleInput.value = snapshot.sourceCopy?.subtitle || '';
      ctaInput.value = snapshot.sourceCopy?.cta || '';
      trustVisible = false;
      updateCounters();
      setTrustVisible(trustVisible);
      applySizePreview(currentSizeIndex);
      applyLanguagePreview(currentLanguageIndex);
      updateUploadState();
      isRestoringPosterHistory = false;
      updatePosterUndoState();
      showToast('已返回上一步');
    }


    const generationRuleForSize = posterCore.generationRuleForSize;
    function layoutAnchorsForSize(size, base = templateAnchors) {
      return posterCore.layoutAnchorsForSize(size, base);
    }

    const posterEditableAnchorKeys = ['image', 'logo', 'title', 'subtitle', 'cta'];
    const posterTextScale = posterCore.posterTextScale;
    const textChildAnchors = posterCore.textChildAnchors;
    function basePosterAnchorsForSize(size, base = templateAnchors) {
      return posterCore.basePosterAnchorsForSize(size, base);
    }

    function posterOverrideKey(size = materialSizes[currentSizeIndex]) {
      return size?.id || `${size?.width || 0}x${size?.height || 0}`;
    }

    function posterLanguageOverrideKey(size = materialSizes[currentSizeIndex], languageIndex = currentLanguageIndex) {
      return `${posterOverrideKey(size)}::language::${Number.isInteger(languageIndex) ? languageIndex : 0}`;
    }

    function isLanguageScopedPosterAnchor(anchorKey) {
      return ['title', 'subtitle', 'cta'].includes(anchorKey);
    }

    function posterOverrideBucketKey(anchorKey, size = materialSizes[currentSizeIndex], languageIndex = currentLanguageIndex) {
      return isLanguageScopedPosterAnchor(anchorKey)
        ? posterLanguageOverrideKey(size, languageIndex)
        : posterOverrideKey(size);
    }

    function effectivePosterAnchorsForSize(size = materialSizes[currentSizeIndex], asset = currentPreviewAsset()) {
      const anchors = basePosterAnchorsForSize(size, templateAnchors);
      if (!isTemplateBaseSize(size)) {
        Object.entries(templateAnchors.sizeAnchors?.[templateSizeKey(size)] || {}).forEach(([key, anchor]) => {
          if (anchors[key]) anchors[key] = { ...anchors[key], ...anchor };
        });
      }
      Object.entries(asset?.rule?.anchors || {}).forEach(([key, anchor]) => {
        if (anchors[key]) anchors[key] = { ...anchors[key], ...anchor };
        else if (key === 'imageVisibleArea' || key === 'imageVisualArea') anchors[key] = { ...anchor };
      });
      const overrides = posterAnchorOverrides[posterOverrideKey(size)] || {};
      posterEditableAnchorKeys.forEach(key => {
        if (!isLanguageScopedPosterAnchor(key) && overrides[key]) anchors[key] = { ...anchors[key], ...overrides[key] };
      });
      const languageIndex = Number.isInteger(asset?.languageIndex) ? asset.languageIndex : currentLanguageIndex;
      const languageOverrides = posterAnchorOverrides[posterLanguageOverrideKey(size, languageIndex)] || {};
      posterEditableAnchorKeys.forEach(key => {
        if (isLanguageScopedPosterAnchor(key) && languageOverrides[key]) anchors[key] = { ...anchors[key], ...languageOverrides[key] };
      });
      anchors.text = textAnchorFromChildren(anchors);
      anchors.cta = normalizeCtaAnchorRatio(anchors.cta, size);
      return anchors;
    }

    function isLegacyDarkDefaultStyles(styles) {
      return styles?.backgroundMode === 'solid'
        && String(styles?.backgroundColor || '').toLowerCase() === '#101827'
        && String(styles?.gradientStart || '').toLowerCase() === '#101827'
        && String(styles?.gradientEnd || '').toLowerCase() === '#1f3472';
    }

    function isLegacyLightPresetStyles(styleId, styles) {
      if (!styles || styles.backgroundMode !== 'solid') return false;
      const backgroundColor = String(styles.backgroundColor || '').toLowerCase();
      const textColor = String(styles.textColor || '').toLowerCase();
      const defaultButton = String(styles.buttonColor || '').toLowerCase() === FIGMA_BUTTON_FILL_COLOR.toLowerCase();
      if (!defaultButton) return false;
      if (styleId === 'style-1') return backgroundColor === '#dcf9ff' && ['#081840', '#27376f'].includes(textColor);
      if (styleId === 'style-3') return backgroundColor === '#eef6fe' && ['#0b1944', '#27376f'].includes(textColor);
      return false;
    }

    function normalizeButtonColors(styles) {
      if (!styles || typeof styles !== 'object') return styles;
      const buttonColor = String(styles.buttonColor || '').toLowerCase();
      if (!buttonColor || LEGACY_BUTTON_FILL_COLORS.has(buttonColor)) {
        styles.buttonColor = FIGMA_BUTTON_FILL_COLOR;
      }
      const buttonTextColor = String(styles.buttonTextColor || '').toLowerCase();
      if (!buttonTextColor) {
        styles.buttonTextColor = FIGMA_BUTTON_TEXT_COLOR;
      }
      return styles;
    }

    function removeExactFrameLayoutOverrides(anchors) {
      const sizeAnchors = anchors?.sizeAnchors;
      if (!sizeAnchors || typeof sizeAnchors !== 'object') return anchors;
      Object.keys(sizeAnchors).forEach(sizeKey => {
        if (generationLayoutRules[sizeKey]?.exact) delete sizeAnchors[sizeKey];
      });
      if (!Object.keys(sizeAnchors).length) delete anchors.sizeAnchors;
      return anchors;
    }

    function normalizeTemplateState() {
      const defaultFrameworks = defaultTemplates();
      templates = defaultFrameworks.map(framework => ({
        ...framework,
        variant: 'light'
      }));
      const templateIds = new Set(templates.map(template => template.id));
      Object.keys(templateAnchorMaps).forEach(templateKey => {
        if (!templateIds.has(templateKey)) delete templateAnchorMaps[templateKey];
      });
      templates.forEach(template => {
        templateAnchorMaps[template.id] = removeExactFrameLayoutOverrides(
          completeAnchors(templateAnchorMaps[template.id] || defaultTemplateAnchors)
        );
      });
      if (!templateIds.has(selectedTemplate)) selectedTemplate = templates[0].id;

      if (!Array.isArray(stylePresets) || !stylePresets.length) stylePresets = defaultStylePresets();
      stylePresets = stylePresets
        .filter(style => style && /^style-\d+$/.test(String(style.id || '')))
        .map(style => ({
          id: String(style.id),
          name: String(style.name || '').trim() || `样式 ${styleIndex(style.id)}`
        }));
      if (!stylePresets.length) stylePresets = defaultStylePresets();
      defaultStylePresets().forEach(defaultStyle => {
        if (!stylePresets.some(style => style.id === defaultStyle.id)) stylePresets.push(defaultStyle);
      });
      const styleIds = new Set(stylePresets.map(style => style.id));
      Object.keys(styleMaps).forEach(styleKey => {
        if (!styleIds.has(styleKey)) delete styleMaps[styleKey];
      });
      stylePresets.forEach(style => {
        if (!styleMaps[style.id] || isLegacyDarkDefaultStyles(styleMaps[style.id]) || isLegacyLightPresetStyles(style.id, styleMaps[style.id])) {
          styleMaps[style.id] = cloneStyles(defaultStylesForId(style.id));
        }
        if (style.id === 'style-2') styleMaps[style.id].gradientAngle = 165;
        normalizeButtonColors(styleMaps[style.id]);
      });
      if (!styleIds.has(selectedStyle)) selectedStyle = stylePresets[0].id;
    }

    function scheduleTemplateStateSave() {
      if (templateStateSaveTimer) window.clearTimeout(templateStateSaveTimer);
      templateStateSaveTimer = window.setTimeout(() => {
        templateStateSaveTimer = null;
        saveTemplateState();
      }, 180);
    }

    async function saveTemplateState() {
      return frameStore.save();
    }

    async function restoreTemplateState() {
      return frameStore.restore();
    }

    function resetTemplateStateToDefaults() {
      templates = defaultTemplates();
      stylePresets = defaultStylePresets();
      templateAnchorMaps = defaultTemplateAnchorMaps();
      styleMaps = defaultStyleMaps();
      selectedTemplate = 'template-1';
      selectedStyle = 'style-1';
      templateAnchors = cloneAnchors(templateAnchorMaps[selectedTemplate]);
      draftTemplateAnchors = cloneAnchors(templateAnchors);
      templateStyles = cloneStyles(styleMaps[selectedStyle]);
      draftTemplateStyles = cloneStyles(templateStyles);
    }

    async function clearTemplateState() {
      return frameStore.clear();
    }

    function cloneDefaultCopy(index = 0) {
      return { ...(DEFAULT_LOCALIZED_COPY[index] || DEFAULT_LOCALIZED_COPY[0]) };
    }

    function normalizeCopyText(value) {
      return String(value || '').replace(/\s*\r?\n\s*/g, ' ').trim();
    }

    function normalizeCopy(copy, index = 0) {
      const fallback = cloneDefaultCopy(index);
      const legacyEnglishCopy = index === 0 && copy?.title === '标题文案' && copy?.subtitle === '副标题文案' && copy?.cta === '按钮文案';
      const legacyTradingCopy = LEGACY_TRADING_LOCALIZED_COPY[index]
        && copy?.title === LEGACY_TRADING_LOCALIZED_COPY[index].title
        && copy?.subtitle === LEGACY_TRADING_LOCALIZED_COPY[index].subtitle
        && copy?.cta === LEGACY_TRADING_LOCALIZED_COPY[index].cta;
      if (legacyEnglishCopy || legacyTradingCopy) return fallback;
      return {
        title: normalizeCopyText(copy?.title || fallback.title || ''),
        subtitle: normalizeCopyText(copy?.subtitle || fallback.subtitle || ''),
        cta: normalizeCopyText(copy?.cta || fallback.cta || '')
      };
    }


    const COPY_TRANSLATION_MAP = window.SpecPromoTranslations?.copyTranslationMap || {};
    const TRANSLATION_LANGUAGE_CODES = ['en', 'ja', 'zh-CN', 'zh-TW', 'vi', 'th', 'ko', 'id', 'ms'];

    function canonicalCopyKey(value) {
      return normalizeCopyText(value)
        .toLowerCase()
        .replace(/\s+([,.;:!?])/g, '$1')
        .replace(/([,.;:!?])(?=\S)/g, '$1 ')
        .replace(/[.。．]+$/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    }

    const NORMALIZED_COPY_TRANSLATION_MAP = Object.entries(COPY_TRANSLATION_MAP).reduce((lookup, [key, translations]) => {
      lookup[canonicalCopyKey(key)] = translations;
      return lookup;
    }, {});

    function copyTranslationsForKey(key) {
      return COPY_TRANSLATION_MAP[key] || NORMALIZED_COPY_TRANSLATION_MAP[canonicalCopyKey(key)];
    }

    function translatedCopyValue(value, languageIndex, fallbackValue = '') {
      const key = String(value || '').trim();
      const translations = copyTranslationsForKey(key);
      if (translations?.[languageIndex]) {
        return normalizeCopyText(languageIndex === 0 ? key : translations[languageIndex]);
      }
      return normalizeCopyText(key || fallbackValue);
    }

    async function translateCopyValueOnline(value, languageIndex, fallbackValue = '') {
      const key = normalizeCopyText(value);
      if (!key || languageIndex === 0) return key || normalizeCopyText(fallbackValue);
      const targetLanguage = TRANSLATION_LANGUAGE_CODES[languageIndex];
      if (!targetLanguage) return key || normalizeCopyText(fallbackValue);
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 4500);
      try {
        const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(targetLanguage)}&dt=t&q=${encodeURIComponent(key)}`;
        const response = await fetch(url, { signal: controller.signal });
        if (!response.ok) throw new Error(`translation ${response.status}`);
        const payload = await response.json();
        const translated = Array.isArray(payload?.[0])
          ? payload[0].map(part => part?.[0] || '').join('')
          : '';
        return normalizeCopyText(translated || key || fallbackValue);
      } catch (error) {
        console.warn('Auto translation unavailable, using source copy', error);
        return normalizeCopyText(key || fallbackValue);
      } finally {
        clearTimeout(timeout);
      }
    }

    async function translatedCopyValueAsync(value, languageIndex, fallbackValue = '') {
      const staticValue = translatedCopyValue(value, languageIndex, fallbackValue);
      const key = normalizeCopyText(value);
      const hasStaticTranslation = Boolean(copyTranslationsForKey(key)?.[languageIndex]);
      if (languageIndex === 0 || hasStaticTranslation || !key) return staticValue;
      return translateCopyValueOnline(key, languageIndex, staticValue);
    }

    function buildLocalizedCopyFromSource(sourceCopy) {
      return languages.map((_, index) => ({
        title: translatedCopyValue(sourceCopy.title, index, cloneDefaultCopy(index).title),
        subtitle: translatedCopyValue(sourceCopy.subtitle, index, cloneDefaultCopy(index).subtitle),
        cta: translatedCopyValue(sourceCopy.cta, index, cloneDefaultCopy(index).cta)
      }));
    }

    async function buildLocalizedCopyFromSourceAsync(sourceCopy) {
      return Promise.all(languages.map(async (_, index) => ({
        title: await translatedCopyValueAsync(sourceCopy.title, index, cloneDefaultCopy(index).title),
        subtitle: await translatedCopyValueAsync(sourceCopy.subtitle, index, cloneDefaultCopy(index).subtitle),
        cta: await translatedCopyValueAsync(sourceCopy.cta, index, cloneDefaultCopy(index).cta)
      })));
    }

    function syncLocalizedCopyFromInputs() {
      localizedCopy = buildLocalizedCopyFromSource(getSourceCopy());
      Object.keys(posterCopyOverrides).forEach(key => delete posterCopyOverrides[key]);
    }

    function isLegacySpanishLanguage(language) {
      return /西班牙语|西班牙|Español|Espanol|Spanish/i.test(`${language?.[0] || ''} ${language?.[1] || ''}`);
    }

    function migrateLegacySpanishLanguage() {
      const malayCopy = cloneDefaultCopy(8);
      languages = languages.map((language, index) => {
        if (!isLegacySpanishLanguage(language)) return language;
        localizedCopy[index] = malayCopy;
        return ['马来语', 'Melayu'];
      });
    }

    function mergeFigmaFrameSizes() {
      const figmaSizes = window.SpecPromoFrameLayouts?.getSizes?.() || [];
      if (!Array.isArray(figmaSizes) || !figmaSizes.length) return;
      figmaSizes.forEach(size => {
        const exists = materialSizes.some(item =>
          item.id === size.id || (item.width === size.width && item.height === size.height)
        );
        if (!exists) materialSizes.push(cloneState(size));
      });
    }

    function canonicalSizeId(id = '') {
      return id === 'ad_120x50' ? 'ad_120x600' : id;
    }

    function isLegacyMaterialSize(size = {}) {
      const id = String(size.id || '');
      const width = parsePositiveInt(size.width);
      const height = parsePositiveInt(size.height);
      return id === 'ad_120x50' || (width === 120 && height === 50);
    }

    function normalizeMaterialSizeEntry(size, index = 0) {
      const width = parsePositiveInt(size?.width);
      const height = parsePositiveInt(size?.height);
      if (!width || !height) return null;
      return {
        id: canonicalSizeId(String(size?.id || `custom_${width}x${height}_${index}`)),
        label: normalizeSizeLabel(width, height, size?.label),
        width,
        height
      };
    }

    function migrateMaterialSizes() {
      const figmaSizes = (window.SpecPromoFrameLayouts?.getSizes?.() || [])
        .map((size, index) => normalizeMaterialSizeEntry(size, index))
        .filter(Boolean);
      const figmaIds = new Set(figmaSizes.map(size => size.id));
      const figmaDimensions = new Set(figmaSizes.map(size => `${size.width}x${size.height}`));
      const nextSizes = [];
      const seenIds = new Set();
      const seenDimensions = new Set();

      function addSize(size) {
        if (!size || isLegacyMaterialSize(size)) return;
        const dimensionKey = `${size.width}x${size.height}`;
        if (seenIds.has(size.id) || seenDimensions.has(dimensionKey)) return;
        seenIds.add(size.id);
        seenDimensions.add(dimensionKey);
        nextSizes.push(cloneState(size));
      }

      figmaSizes.forEach(addSize);
      materialSizes.forEach((size, index) => {
        const normalized = normalizeMaterialSizeEntry(size, index);
        if (!normalized || isLegacyMaterialSize(normalized)) return;
        if (figmaIds.has(normalized.id) || figmaDimensions.has(`${normalized.width}x${normalized.height}`)) return;
        addSize(normalized);
      });

      if (nextSizes.length) materialSizes = nextSizes;
      else mergeFigmaFrameSizes();
    }

    function normalizeSizeLanguageState() {
      const activeSizeId = canonicalSizeId(materialSizes[currentSizeIndex]?.id);
      const activeFrameworkSizeId = canonicalSizeId(materialSizes[frameworkSizeIndex]?.id);
      materialSizes = (Array.isArray(materialSizes) ? materialSizes : [])
        .map(normalizeMaterialSizeEntry)
        .filter(Boolean);
      migrateMaterialSizes();
      if (!materialSizes.length) materialSizes = JSON.parse(JSON.stringify(DEFAULT_MATERIAL_SIZES));
      sortMaterialSizesByDesignOrder(materialSizes);
      if (activeSizeId) {
        currentSizeIndex = Math.max(0, materialSizes.findIndex(size => size.id === activeSizeId));
      }
      if (activeFrameworkSizeId) {
        frameworkSizeIndex = Math.max(0, materialSizes.findIndex(size => size.id === activeFrameworkSizeId));
      }

      languages = (Array.isArray(languages) ? languages : [])
        .map(language => {
          const cn = String(language?.[0] || '').trim();
          const en = String(language?.[1] || '').trim();
          return cn && en ? [cn, en] : null;
        })
        .filter(Boolean);
      if (!languages.length) languages = JSON.parse(JSON.stringify(DEFAULT_LANGUAGES));
      migrateLegacySpanishLanguage();

      localizedCopy = languages.map((_, index) => normalizeCopy(localizedCopy?.[index], index));
      currentSizeIndex = Math.min(currentSizeIndex, Math.max(0, materialSizes.length - 1));
      frameworkSizeIndex = Math.min(frameworkSizeIndex, Math.max(0, materialSizes.length - 1));
      currentLanguageIndex = Math.min(currentLanguageIndex, Math.max(0, languages.length - 1));
    }

    async function saveSizeLanguageState() {
      let snapshot = null;
      try {
        normalizeSizeLanguageState();
        snapshot = {
          version: 1,
          updatedAt: Date.now(),
          materialSizes: cloneState(materialSizes),
          languages: cloneState(languages),
          localizedCopy: cloneState(localizedCopy)
        };
        mirrorStateToLegacyStorage(SIZE_LANGUAGE_STORAGE_KEY, snapshot);
        let saved = false;
        try {
          await persistStateRecord(SIZE_LANGUAGE_STORAGE_KEY, snapshot);
          saved = true;
        } catch (localError) {
          console.warn('Local size/language database unavailable', localError);
        }
        try {
          await saveServerSizeLanguageState(snapshot);
          saved = true;
        } catch (serverError) {
          console.warn('Server size/language database unavailable, saved locally instead', serverError);
        }
        return saved;
      } catch (error) {
        console.warn('Size/language state failed to persist', error);
        if (snapshot) mirrorStateToLegacyStorage(SIZE_LANGUAGE_STORAGE_KEY, snapshot);
        return false;
      }
    }

    async function restoreSizeLanguageState() {
      try {
        let serverState = null;
        try {
          serverState = await loadServerSizeLanguageState();
        } catch (serverError) {
          console.warn('Server size/language database unavailable, restoring from local storage', serverError);
        }
        const dbState = await loadStateRecord(SIZE_LANGUAGE_STORAGE_KEY);
        const legacyState = loadLegacyJsonState(SIZE_LANGUAGE_STORAGE_KEY);
        let saved = newestAvailableState(serverState, dbState, legacyState);
        if (!saved) {
          normalizeSizeLanguageState();
          await saveSizeLanguageState();
          return;
        }
        if (!saved || saved.version !== 1) {
          normalizeSizeLanguageState();
          await saveSizeLanguageState();
          return;
        }
        if (Array.isArray(saved.materialSizes)) materialSizes = saved.materialSizes;
        if (Array.isArray(saved.languages)) languages = saved.languages;
        if (Array.isArray(saved.localizedCopy)) localizedCopy = saved.localizedCopy;
        normalizeSizeLanguageState();
        await saveSizeLanguageState();
      } catch (error) {
        console.warn('Size/language state failed to restore', error);
        materialSizes = JSON.parse(JSON.stringify(DEFAULT_MATERIAL_SIZES));
        languages = JSON.parse(JSON.stringify(DEFAULT_LANGUAGES));
        localizedCopy = JSON.parse(JSON.stringify(DEFAULT_LOCALIZED_COPY));
      }
    }

    function logoAssetTheme(variant = 'black') {
      return variant === 'white' ? 'dark' : 'light';
    }

    function logoVariantFromAssetTheme(theme = 'light') {
      return theme === 'dark' ? 'white' : 'black';
    }

    function logoSrcFor(brand = selectedLogoBrand, variant = selectedLogoVariant) {
      return `assets/logo-${brand}-${logoAssetTheme(variant)}.png`;
    }

    function logoAltFor(brand = selectedLogoBrand, variant = selectedLogoVariant) {
      const brandName = brand === 'trading' ? 'SPEC TRADING' : 'SPEC MARKETS';
      return `${brandName} ${variant === 'white' ? '亮版' : '暗版'}字标`;
    }

    function isJapaneseLanguage(languageIndex) {
      const [cn = '', en = ''] = languages[languageIndex] || [];
      return /日语|日本|日本語|Japanese/i.test(`${cn} ${en}`);
    }

    function logoBrandForLanguage(languageIndex = currentLanguageIndex) {
      return isJapaneseLanguage(languageIndex) ? 'trading' : 'market';
    }

    function applySelectedLogo(brand = selectedLogoBrand, variant = selectedLogoVariant) {
      selectedLogoBrand = brand;
      selectedLogoVariant = variant;
      selectedLogoTheme = logoAssetTheme(variant);
      selectedLogoSrc = logoSrcFor(selectedLogoBrand, selectedLogoVariant);
      creativeLogoImage.src = selectedLogoSrc;
      creativeLogoImage.alt = logoAltFor(selectedLogoBrand, selectedLogoVariant);
      creativeLogo.classList.remove('hidden');
    }

    function applyRuleLogo(languageIndex = currentLanguageIndex, styles = templateStyles) {
      applySelectedLogo(logoBrandForLanguage(languageIndex), styles?.logoVariant || selectedLogoVariant);
    }

    function templateName(templateKey = selectedTemplate) {
      return templateDisplayName(templateById(templateKey));
    }

    function styleName(styleKey = selectedStyle) {
      return styleDisplayName(styleById(styleKey));
    }

    function hasPendingAnchorChanges() {
      return JSON.stringify(draftTemplateAnchors) !== JSON.stringify(templateAnchors);
    }

    function templateBackgroundCss(styles = templateStyles) {
      if (styles.backgroundMode === 'gradient') {
        const angle = clamp(Number(styles.gradientAngle) || 0, 0, 360);
        return `linear-gradient(${angle}deg, ${styles.gradientStart}, ${styles.gradientEnd})`;
      }
      return styles.backgroundColor;
    }

    function frameworkPreviewStyles() {
      return styleMaps['style-1'] || defaultTemplateStyles;
    }

    function updateTemplateMappingStatus() {
      const pending = hasPendingAnchorChanges();
      if (templateMappingStatus) {
        templateMappingStatus.textContent = `当前编辑：${templateName()} · ${pending ? '有未提交框架变更' : '已映射到促销材料'}`;
      }
      if (commitAnchorsButton) commitAnchorsButton.disabled = !pending;
      if (deleteStyleButton) deleteStyleButton.disabled = stylePresets.length <= 1;
    }

    function fitPosterTextBoxes() {
      posterRenderer.fitPosterTextBoxes();
    }

    function schedulePosterTextFit() {
      requestAnimationFrame(() => {
        fitPosterTextBoxes();
        renderPosterEditOverlay();
      });
    }

    function syncImagePlaceholderArea(anchors) {
      const visualAnchor = posterRenderer.imageVisualAnchor(anchors);
      if (!visualAnchor) return;
      materialCard.style.setProperty('--image-placeholder-x', formatPct(visualAnchor.x));
      materialCard.style.setProperty('--image-placeholder-y', formatPct(visualAnchor.y));
      materialCard.style.setProperty('--image-placeholder-w', formatPct(visualAnchor.w));
      materialCard.style.setProperty('--image-placeholder-h', formatPct(visualAnchor.h));
    }

    function applyPosterLayoutForSize(sizeIndex = currentSizeIndex) {
      const size = materialSizes[sizeIndex] || materialSizes[0];
      const anchors = effectivePosterAnchorsForSize(size);
      posterRenderer.applyLayoutVariables(anchors, size);
      syncImagePlaceholderArea(anchors);
      renderPosterEditOverlay(anchors);
      schedulePosterTextFit();
    }

    function applyTemplateAnchors() {
      applyPosterLayoutForSize(currentSizeIndex);
      applyTemplateStyles();
      renderAnchorEditor();
    }

    function applyTemplateStyles() {
      applyRuleVisualStyles();
    }

    function frameLayoutStylesForAsset(asset = currentPreviewAsset()) {
      const size = materialSizes[asset?.sizeIndex ?? currentSizeIndex] || materialSizes[currentSizeIndex] || materialSizes[0];
      return generationLayoutRules[size?.id]?.styles || {};
    }

    function effectivePosterStyles(asset = currentPreviewAsset()) {
      return normalizeButtonColors({
        ...frameLayoutStylesForAsset(asset),
        ...templateStyles,
        ...(asset?.rule?.styles || {})
      });
    }

    function applyRuleVisualStyles(asset = currentPreviewAsset()) {
      const styles = effectivePosterStyles(asset);
      const posterBg = templateBackgroundCss(styles);
      const backgroundArea = styles.backgroundArea || {};
      const hasBackgroundArea = ['x', 'y', 'w', 'h'].every(key => Number.isFinite(Number(backgroundArea[key])));
      materialCard.style.setProperty('--poster-bg', posterBg);
      uploadPreview.style.setProperty('--poster-bg', posterBg);
      materialCard.style.setProperty('--poster-bg-area-x', `${hasBackgroundArea ? Number(backgroundArea.x) : 0}%`);
      materialCard.style.setProperty('--poster-bg-area-y', `${hasBackgroundArea ? Number(backgroundArea.y) : 0}%`);
      materialCard.style.setProperty('--poster-bg-area-w', `${hasBackgroundArea ? Number(backgroundArea.w) : 100}%`);
      materialCard.style.setProperty('--poster-bg-area-h', `${hasBackgroundArea ? Number(backgroundArea.h) : 100}%`);
      materialCard.style.setProperty('--copy-color', styles.textColor);
      materialCard.style.setProperty('--cta-bg', styles.buttonColor || FIGMA_BUTTON_FILL_COLOR);
      materialCard.style.setProperty('--cta-fg', styles.buttonTextColor || FIGMA_BUTTON_TEXT_COLOR);
      applyRuleLogo(currentLanguageIndex, styles);
    }

    function fitAnchorCanvasPreview(size = materialSizes[frameworkSizeIndex]) {
      frameEditorHelpers.fitAnchorCanvasPreview(size, anchorCanvas?.parentElement);
    }

    function templateSizeKey(size = materialSizes[frameworkSizeIndex]) {
      return size?.id || `${size?.width || 0}x${size?.height || 0}`;
    }

    function isTemplateBaseSize(size = materialSizes[frameworkSizeIndex]) {
      return size?.id === TEMPLATE_PREVIEW_SIZE_ID || (size?.width === 1200 && size?.height === 628);
    }

    function isExactFigmaFrameSize(size = materialSizes[frameworkSizeIndex]) {
      return Boolean(size?.id && generationLayoutRules[size.id]?.exact);
    }

    function mergeTemplateAnchorSet(baseAnchors, overrideAnchors, size = materialSizes[frameworkSizeIndex]) {
      let anchors = cloneAnchors(baseAnchors || defaultTemplateAnchors);
      Object.entries(overrideAnchors || {}).forEach(([key, anchor]) => {
        if (!anchors[key] || !anchor || typeof anchor !== 'object') return;
        anchors[key] = { ...anchors[key], ...anchor };
      });
      anchors = ensureIndependentCopyAnchors(anchors);
      anchors.text = textAnchorFromChildren(anchors);
      anchors.cta = normalizeCtaAnchorRatio(anchors.cta, size);
      return anchors;
    }

    function anchorEditorPreviewAnchors(size = materialSizes[frameworkSizeIndex]) {
      if (isExactFigmaFrameSize(size) && !isTemplateBaseSize(size)) {
        return basePosterAnchorsForSize(size, defaultTemplateAnchors);
      }
      const baseAnchors = basePosterAnchorsForSize(size, draftTemplateAnchors);
      if (isTemplateBaseSize(size)) return baseAnchors;
      return mergeTemplateAnchorSet(baseAnchors, draftTemplateAnchors.sizeAnchors?.[templateSizeKey(size)], size);
    }

    function ensureDraftAnchorsForActiveSize(size = materialSizes[frameworkSizeIndex]) {
      if (isTemplateBaseSize(size)) return draftTemplateAnchors;
      const sizeKey = templateSizeKey(size);
      if (!draftTemplateAnchors.sizeAnchors || typeof draftTemplateAnchors.sizeAnchors !== 'object') {
        draftTemplateAnchors.sizeAnchors = {};
      }
      draftTemplateAnchors.sizeAnchors[sizeKey] = anchorEditorPreviewAnchors(size);
      return draftTemplateAnchors.sizeAnchors[sizeKey];
    }

    function styleAnchorPreview(nodeId, anchor) {
      const node = document.getElementById(nodeId);
      frameEditorHelpers.styleAnchorPreview(node, anchor, nodeId === 'anchorPreviewCta');
    }

    function fitAnchorPreviewTextElement(element, minSize = 6) {
      if (!element) return;
      element.style.overflow = 'visible';
      element.style.whiteSpace = 'pre-wrap';
      element.style.lineHeight = '1.4';
    }

    function fitAnchorPreviewTextBoxes() {
      fitAnchorPreviewTextElement(anchorPreviewTitle, 6);
      fitAnchorPreviewTextElement(anchorPreviewSubtitle, 5);
      fitAnchorPreviewTextElement(anchorPreviewCta, 5);
    }

    function renderAnchorPreview(previewAnchors = anchorEditorPreviewAnchors(), size = materialSizes[frameworkSizeIndex]) {
      const previewStyles = frameworkPreviewStyles();
      styleAnchorPreview('anchorPreviewImage', previewAnchors.image);
      styleAnchorPreview('anchorPreviewTitle', previewAnchors.title);
      styleAnchorPreview('anchorPreviewSubtitle', previewAnchors.subtitle);
      styleAnchorPreview('anchorPreviewCta', previewAnchors.cta);
      styleAnchorPreview('anchorPreviewLogo', previewAnchors.logo);
      anchorCanvas.style.background = templateBackgroundCss(previewStyles);
      const sourceCopy = getSourceCopy();
      if (anchorPreviewTitle) anchorPreviewTitle.textContent = sourceCopy.title || 'Headline Text';
      if (anchorPreviewSubtitle) renderMultilineText(anchorPreviewSubtitle, sourceCopy.subtitle || 'More information and key features here.');
      if (anchorPreviewCta) anchorPreviewCta.textContent = sourceCopy.cta || 'Button';
      renderGradientControl(previewStyles);
      const logoPreview = document.querySelector('#anchorPreviewLogo img');
      if (logoPreview) {
        const variant = previewStyles.logoVariant || 'black';
        logoPreview.src = logoSrcFor('market', variant);
        logoPreview.alt = logoAltFor('market', variant);
      }
      ['anchorPreviewTitle', 'anchorPreviewSubtitle', 'anchorPreviewCta'].forEach(nodeId => {
        const textPreview = document.getElementById(nodeId);
        if (!textPreview) return;
        const key = nodeId === 'anchorPreviewTitle' ? 'title' : (nodeId === 'anchorPreviewSubtitle' ? 'subtitle' : 'cta');
        const anchor = previewAnchors[key];
        const textScale = posterTextScale(size);
        const fallbackFont = key === 'title'
          ? Math.max(1, anchor.h * 0.58 * textScale)
          : (key === 'subtitle' ? Math.max(1, anchor.h * 0.30 * textScale) : Math.max(1, anchor.h * 0.38));
        const fontPx = Number(anchor?.fontPx);
        const fontScale = Number(anchor?.fontScale);
        const fontPct = Number.isFinite(fontPx) && fontPx > 0
          ? (fontPx * (Number.isFinite(fontScale) && fontScale > 0 ? fontScale : 1) / Math.max(1, Number(size?.height) || 1)) * 100
          : (Number(anchor?.font) || fallbackFont);
        if (key !== 'cta') {
          textPreview.style.textAlign = previewAnchors.title.align || previewAnchors.subtitle.align || previewAnchors.text?.align || 'left';
          textPreview.style.color = previewStyles.textColor;
        }
        textPreview.style.fontSize = `max(1px, ${fontPct}cqh)`;
      });
      const ctaPreview = document.getElementById('anchorPreviewCta');
      if (ctaPreview) {
        ctaPreview.style.background = previewStyles.buttonColor || FIGMA_BUTTON_FILL_COLOR;
        ctaPreview.style.color = previewStyles.buttonTextColor || FIGMA_BUTTON_TEXT_COLOR;
      }
      requestAnimationFrame(fitAnchorPreviewTextBoxes);
    }

    function gradientHandlePoints(styles = draftTemplateStyles) {
      const cssAngle = Number(styles.gradientAngle) || 0;
      const angle = ((cssAngle - 90) * Math.PI) / 180;
      const length = 34;
      const dx = Math.cos(angle) * length;
      const dy = Math.sin(angle) * length;
      return {
        start: { x: 50 - dx, y: 50 - dy },
        end: { x: 50 + dx, y: 50 + dy },
        lineAngle: cssAngle - 90
      };
    }

    function renderGradientControl(styles = draftTemplateStyles) {
      if (!gradientControl || !gradientLine) return;
      const isGradient = styles.backgroundMode === 'gradient';
      const shouldShowControl = isGradient && gradientControlActive;
      gradientControl.classList.toggle('visible', shouldShowControl);
      if (!shouldShowControl) return;
      const points = gradientHandlePoints(styles);
      gradientLine.style.transform = `translate(-50%, -50%) rotate(${points.lineAngle}deg)`;
      gradientControl.querySelectorAll('.gradient-handle').forEach(handle => {
        const point = points[handle.dataset.gradientHandle];
        if (!point) return;
        handle.style.left = `${point.x}%`;
        handle.style.top = `${point.y}%`;
        handle.style.setProperty('--handle-color', handle.dataset.gradientHandle === 'start'
          ? styles.gradientStart
          : styles.gradientEnd);
      });
    }

    function applyImageTextSideLayout(imageOnLeft) {
      draftTemplateAnchors.image = {
        ...draftTemplateAnchors.image,
        x: imageOnLeft ? 0 : 55.8,
        y: 0,
        w: 44.2,
        h: 100
      };
      draftTemplateAnchors.title = {
        ...draftTemplateAnchors.title,
        x: imageOnLeft ? 48.3 : 7,
        y: 30,
        w: 44,
        h: 12
      };
      draftTemplateAnchors.subtitle = {
        ...draftTemplateAnchors.subtitle,
        x: imageOnLeft ? 48.3 : 7,
        y: 45,
        w: 44,
        h: 13
      };
      draftTemplateAnchors.text = textAnchorFromChildren(draftTemplateAnchors);
      draftTemplateAnchors.cta = defaultCtaAnchorForText(draftTemplateAnchors.text);
      draftTemplateAnchors.logo = {
        ...draftTemplateAnchors.logo,
        x: imageOnLeft ? 48.3 : 7,
        y: 8,
        w: 24,
        h: 10
      };
      draftTemplateAnchors.trust = {
        ...draftTemplateAnchors.trust,
        x: imageOnLeft ? 81 : 7,
        y: 87,
        w: 15,
        h: 8
      };
    }

    function maybeSwapImageTextSides(anchorKey) {
      if (!['image', 'title', 'subtitle'].includes(anchorKey)) return;
      const textAnchor = textAnchorFromChildren(draftTemplateAnchors);
      const anchor = anchorKey === 'image' ? draftTemplateAnchors.image : textAnchor;
      const centerX = anchor.x + anchor.w / 2;
      const imageOnLeft = anchorKey === 'image' ? centerX < 50 : centerX >= 50;
      applyImageTextSideLayout(imageOnLeft);
      renderAnchorEditor();
    }

    function anchorSide(anchor) {
      if (!anchor) return null;
      return anchor.x + anchor.w / 2 < 50 ? 'left' : 'right';
    }

    function axisLockedDelta(dx, dy, dragState, lockAxis, threshold = 0) {
      return frameEditorHelpers.axisLockedDelta(dx, dy, dragState, lockAxis, threshold);
    }

    function ensureEdgeResizeHandles(box, handleClass) {
      if (!box) return;
      const existingDefault = box.querySelector(`.${handleClass}:not([data-resize-side])`);
      if (existingDefault) {
        existingDefault.dataset.resizeSide = 'se';
        existingDefault.classList.add('edit-resize-handle');
      }
      if (box.dataset.edgeHandlesReady === 'true') return;
      ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'].forEach(side => {
        if (box.querySelector(`.${handleClass}[data-resize-side="${side}"]`)) return;
        const handle = document.createElement('span');
        handle.className = `edit-resize-handle ${handleClass}`;
        handle.dataset.resizeSide = side;
        handle.setAttribute('aria-hidden', 'true');
        box.appendChild(handle);
      });
      box.dataset.edgeHandlesReady = 'true';
    }

    function resizeAnchorFromSide(base, delta, side, proportional = false) {
      const next = { ...base };
      const right = Number(base.x) + Number(base.w);
      const bottom = Number(base.y) + Number(base.h);
      const hasWest = side.includes('w');
      const hasEast = side.includes('e');
      const hasNorth = side.includes('n');
      const hasSouth = side.includes('s');
      if (!proportional) {
        if (hasEast) next.w = base.w + delta.dx;
        if (hasWest) { next.x = base.x + delta.dx; next.w = base.w - delta.dx; }
        if (hasSouth) next.h = base.h + delta.dy;
        if (hasNorth) { next.y = base.y + delta.dy; next.h = base.h - delta.dy; }
        return next;
      }
      let scale = 1;
      const xScale = hasEast ? 1 + delta.dx / Math.max(base.w, 1) : (hasWest ? 1 - delta.dx / Math.max(base.w, 1) : 1);
      const yScale = hasSouth ? 1 + delta.dy / Math.max(base.h, 1) : (hasNorth ? 1 - delta.dy / Math.max(base.h, 1) : 1);
      scale = side.length > 1 ? Math.min(xScale, yScale) : (xScale !== 1 ? xScale : yScale);
      scale = Math.max(0.15, scale);
      next.w = base.w * scale;
      next.h = base.h * scale;
      if (hasWest) next.x = right - next.w;
      else if (!hasEast) next.x = base.x + (base.w - next.w) / 2;
      if (hasNorth) next.y = bottom - next.h;
      else if (!hasSouth) next.y = base.y + (base.h - next.h) / 2;
      return next;
    }

    function resizeAnchorForInteraction(base, delta, side, key) {
      const isCorner = String(side || '').length > 1;
      const proportional = key === 'image' || key === 'logo' || isCorner;
      const resized = resizeAnchorFromSide(base, delta, side, proportional);
      if (['title', 'subtitle', 'cta'].includes(key)) {
        if (isCorner) {
          const scale = Math.max(
            0.15,
            Math.min(
              resized.w / Math.max(1, Number(base.w) || 1),
              resized.h / Math.max(1, Number(base.h) || 1)
            )
          );
          resized.fontScale = posterCore.clamp((Number(base.fontScale) || 1) * scale, 0.05, 8);
        } else if (key === 'cta' && (side === 'e' || side === 'w')) {
          resized.autoWidth = false;
        }
      }
      return resized;
    }

    const ALIGNMENT_GUIDE_SNAP_PX = 6;

    function anchorBounds(anchors, anchorKeys) {
      const selected = anchorKeys.map(key => anchors[key]).filter(Boolean);
      if (!selected.length) return null;
      const left = Math.min(...selected.map(anchor => anchor.x));
      const top = Math.min(...selected.map(anchor => anchor.y));
      const right = Math.max(...selected.map(anchor => anchor.x + anchor.w));
      const bottom = Math.max(...selected.map(anchor => anchor.y + anchor.h));
      return { x: left, y: top, w: right - left, h: bottom - top };
    }

    function alignmentCandidates(allAnchors, ignoredKeys = []) {
      const ignored = new Set(ignoredKeys);
      const vertical = [
        { value: 0, kind: 'edge' },
        { value: 50, kind: 'center' },
        { value: 100, kind: 'edge' }
      ];
      const horizontal = [
        { value: 0, kind: 'edge' },
        { value: 50, kind: 'center' },
        { value: 100, kind: 'edge' }
      ];
      Object.entries(allAnchors || {}).forEach(([key, anchor]) => {
        if (ignored.has(key) || !anchor || anchor.hidden) return;
        vertical.push(
          { value: anchor.x, kind: 'edge' },
          { value: anchor.x + anchor.w / 2, kind: 'center' },
          { value: anchor.x + anchor.w, kind: 'edge' }
        );
        horizontal.push(
          { value: anchor.y, kind: 'edge' },
          { value: anchor.y + anchor.h / 2, kind: 'center' },
          { value: anchor.y + anchor.h, kind: 'edge' }
        );
      });
      return { vertical, horizontal };
    }

    function closestGuide(points, candidates, threshold) {
      let match = null;
      points.forEach(point => {
        candidates.forEach(candidate => {
          const distance = Math.abs(candidate.value - point.value);
          if (distance <= threshold && (!match || distance < match.distance)) {
            match = {
              value: candidate.value,
              kind: candidate.kind,
              offset: candidate.value - point.value,
              distance
            };
          }
        });
      });
      return match;
    }

    function getAlignmentForBounds(host, bounds, allAnchors, movingKeys) {
      const rect = host?.getBoundingClientRect?.();
      if (!rect?.width || !rect?.height || !bounds) return { dx: 0, dy: 0, guides: [] };
      const thresholdX = (ALIGNMENT_GUIDE_SNAP_PX / rect.width) * 100;
      const thresholdY = (ALIGNMENT_GUIDE_SNAP_PX / rect.height) * 100;
      const candidates = alignmentCandidates(allAnchors, movingKeys);
      const verticalMatch = closestGuide([
        { value: bounds.x },
        { value: bounds.x + bounds.w / 2 },
        { value: bounds.x + bounds.w }
      ], candidates.vertical, thresholdX);
      const horizontalMatch = closestGuide([
        { value: bounds.y },
        { value: bounds.y + bounds.h / 2 },
        { value: bounds.y + bounds.h }
      ], candidates.horizontal, thresholdY);
      return {
        dx: verticalMatch?.offset || 0,
        dy: horizontalMatch?.offset || 0,
        guides: [
          ...(verticalMatch ? [{ axis: 'x', value: verticalMatch.value, kind: verticalMatch.kind }] : []),
          ...(horizontalMatch ? [{ axis: 'y', value: horizontalMatch.value, kind: horizontalMatch.kind }] : [])
        ]
      };
    }

    function showAlignmentGuides(host, guides = []) {
      if (!host) return;
      let layer = host.querySelector(':scope > .alignment-guide-layer');
      if (!layer) {
        layer = document.createElement('div');
        layer.className = 'alignment-guide-layer';
        host.appendChild(layer);
      }
      layer.replaceChildren(...guides.map(guide => {
        const line = document.createElement('span');
        line.className = `alignment-guide alignment-guide--${guide.axis} alignment-guide--${guide.kind}`;
        if (guide.axis === 'x') line.style.left = formatPct(guide.value);
        else line.style.top = formatPct(guide.value);
        return line;
      }));
      layer.classList.toggle('is-visible', guides.length > 0);
    }

    function clearAlignmentGuides(host) {
      showAlignmentGuides(host, []);
    }

    function renderAnchorEditor() {
      if (!anchorCanvas) return;
      draftTemplateAnchors = ensureIndependentCopyAnchors(draftTemplateAnchors);
      const size = materialSizes[frameworkSizeIndex] || materialSizes[0];
      fitAnchorCanvasPreview(size);
      const previewAnchors = anchorEditorPreviewAnchors(size);
      renderAnchorPreview(previewAnchors, size);
      renderStyleEditor();
      anchorCanvas.querySelectorAll('.anchor-box').forEach(box => {
        ensureEdgeResizeHandles(box, 'anchor-handle');
        const anchor = previewAnchors[box.dataset.anchor];
        if (!anchor) return;
        box.style.left = formatPct(anchor.x);
        box.style.top = formatPct(anchor.y);
        box.style.width = formatPct(anchor.w);
        box.style.height = formatPct(anchor.h);
        box.classList.toggle('is-active', box.dataset.anchor === activeAnchor);
        box.classList.toggle('is-selected', selectedAnchorKeys.has(box.dataset.anchor));
        syncFontSizeToolbar(box, 'template', box.dataset.anchor, anchor);
      });
      updateAnchorAlignToolbar();
      updateTemplateMappingStatus();
    }

    function updateBackgroundFieldVisibility() {
      const mode = draftTemplateStyles.backgroundMode || 'solid';
      document.querySelectorAll('[data-background-field]').forEach(field => {
        field.classList.toggle('is-hidden', field.dataset.backgroundField !== mode);
      });
    }

    const colorStyleKeys = new Set([
      'backgroundColor',
      'gradientStart',
      'gradientEnd',
      'textColor',
      'buttonColor',
      'buttonTextColor'
    ]);

    function normalizeHexColor(value) {
      let hex = String(value || '').trim().replace(/^#/, '');
      if (/^[0-9a-fA-F]{3}$/.test(hex)) {
        hex = hex.split('').map(char => char + char).join('');
      }
      if (!/^[0-9a-fA-F]{6}$/.test(hex)) return null;
      return `#${hex.toUpperCase()}`;
    }

    function syncColorControl(colorInput, hexInput, value) {
      const hex = normalizeHexColor(value) || '#000000';
      // Native color inputs are strict in some browsers and may fall back to black
      // when assigned uppercase hex values such as #FFFFFF.
      if (colorInput) colorInput.value = hex.toLowerCase();
      if (hexInput) hexInput.value = hex;
    }

    function renderStyleEditor() {
      if (!backgroundModeSelect) return;
      backgroundModeSelect.value = draftTemplateStyles.backgroundMode || 'solid';
      syncColorControl(backgroundColorInput, backgroundColorHexInput, draftTemplateStyles.backgroundColor);
      syncColorControl(gradientStartInput, gradientStartHexInput, draftTemplateStyles.gradientStart);
      syncColorControl(gradientEndInput, gradientEndHexInput, draftTemplateStyles.gradientEnd);
      gradientAngleInput.value = String(draftTemplateStyles.gradientAngle ?? 135);
      syncColorControl(textColorInput, textColorHexInput, draftTemplateStyles.textColor);
      syncColorControl(buttonColorInput, buttonColorHexInput, draftTemplateStyles.buttonColor || FIGMA_BUTTON_FILL_COLOR);
      syncColorControl(buttonTextColorInput, buttonTextColorHexInput, draftTemplateStyles.buttonTextColor || FIGMA_BUTTON_TEXT_COLOR);
      document.querySelectorAll('.logo-tone-card').forEach(button => {
        button.classList.toggle('active', button.dataset.logoVariant === (draftTemplateStyles.logoVariant || 'black'));
      });
      updateBackgroundFieldVisibility();
      syncStyleDemoPreview();
    }

    function syncStyleDemoPreview(styles = draftTemplateStyles) {
      if (!styleDemoCard) return;
      const previewStyles = normalizeButtonColors(styles || defaultTemplateStyles);
      styleDemoCard.style.setProperty('--style-demo-bg', templateBackgroundCss(previewStyles));
      styleDemoCard.style.setProperty('--style-demo-copy', previewStyles.textColor || '#081840');
      styleDemoCard.style.setProperty('--style-demo-button', previewStyles.buttonColor || FIGMA_BUTTON_FILL_COLOR);
      styleDemoCard.style.setProperty('--style-demo-button-text', previewStyles.buttonTextColor || FIGMA_BUTTON_TEXT_COLOR);
      if (styleDemoLogo) {
        const variant = previewStyles.logoVariant || 'black';
        styleDemoLogo.src = logoSrcFor('market', variant);
        styleDemoLogo.alt = logoAltFor('market', variant);
      }
    }

    function updateDraftTemplateStyle(key, value) {
      let nextValue = key === 'gradientAngle' ? clamp(Number(value) || 0, 0, 360) : value;
      if (colorStyleKeys.has(key)) {
        nextValue = normalizeHexColor(value);
        if (!nextValue) {
          showToast('请输入有效的 HEX 颜色，例如 #2144B2');
          renderStyleEditor();
          return;
        }
      }
      draftTemplateStyles = {
        ...draftTemplateStyles,
        [key]: nextValue
      };
      if (key === 'backgroundMode' && nextValue === 'gradient') {
        draftTemplateStyles.gradientStart = draftTemplateStyles.gradientStart || draftTemplateStyles.backgroundColor;
        draftTemplateStyles.gradientEnd = draftTemplateStyles.gradientEnd || '#ffffff';
      }
      if (key === 'backgroundMode') gradientControlActive = false;
      updateBackgroundFieldVisibility();
      styleMaps[selectedStyle] = cloneStyles(draftTemplateStyles);
      templateStyles = cloneStyles(draftTemplateStyles);
      applyTemplateStyles();
      renderAnchorEditor();
      renderTemplateOptions();
      saveTemplateState();
    }

    function bindColorStyleControl(colorInput, hexInput, key) {
      const commitColor = value => updateDraftTemplateStyle(key, value);
      colorInput?.addEventListener('input', () => commitColor(colorInput.value));
      colorInput?.addEventListener('change', () => commitColor(colorInput.value));
      colorInput?.addEventListener('keydown', event => {
        if (event.key === 'Enter') {
          event.preventDefault();
          requestAnimationFrame(() => commitColor(colorInput.value));
        }
      });
      hexInput?.addEventListener('keydown', event => {
        if (event.key === 'Enter') {
          event.preventDefault();
          commitColor(hexInput.value);
        }
      });
      hexInput?.addEventListener('blur', () => commitColor(hexInput.value));
    }

    function updateGradientAngleFromPoint(clientX, clientY, handle = 'end') {
      if (!anchorCanvas) return;
      const rect = anchorCanvas.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;
      const mathAngle = (Math.atan2(clientY - centerY, clientX - centerX) * 180) / Math.PI;
      const offset = handle === 'start' ? 270 : 90;
      updateDraftTemplateStyle('gradientAngle', (mathAngle + offset + 360) % 360);
    }

    function updateAnchorAlignToolbar() {
      const canAlign = selectedAnchorKeys.size > 1;
      document.querySelectorAll('[data-align-action]').forEach(button => { button.disabled = !canAlign; });
      updatePosterAlignToolbar();
    }

    function normalizedAnchor(anchorKey, nextAnchor, baseAnchor = null, size = materialSizes[frameworkSizeIndex]) {
      const minSize = anchorKey === 'logo' || anchorKey === 'trust'
        ? 6
        : (anchorKey === 'title' || anchorKey === 'subtitle' ? 5 : 12);
      const base = baseAnchor || anchorEditorPreviewAnchors(size)[anchorKey] || {};
      const numericOrBase = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : Number(fallback) || 0;
      const normalized = {
        ...base,
        x: clamp(numericOrBase(nextAnchor.x, base.x), 0, 100 - minSize),
        y: clamp(numericOrBase(nextAnchor.y, base.y), 0, 100 - minSize),
        w: clamp(numericOrBase(nextAnchor.w, base.w || minSize), minSize, 100),
        h: clamp(numericOrBase(nextAnchor.h, base.h || minSize), minSize, 100)
      };
      if (Number.isFinite(Number(nextAnchor.font))) normalized.font = clamp(Number(nextAnchor.font), 0.6, 40);
      if (Number.isFinite(Number(nextAnchor.fontScale))) normalized.fontScale = clamp(Number(nextAnchor.fontScale), 0.05, 8);
      normalized.x = clamp(normalized.x, 0, 100 - normalized.w);
      normalized.y = clamp(normalized.y, 0, 100 - normalized.h);
      return anchorKey === 'cta' ? normalizeCtaAnchorRatio(normalized, size || CTA_TEMPLATE_RATIO_SIZE) : normalized;
    }

    function syncDraftAnchorsToActiveTemplate() {
      templateAnchorMaps[selectedTemplate] = completeAnchors(draftTemplateAnchors);
      templateAnchors = cloneAnchors(templateAnchorMaps[selectedTemplate]);
      applyPosterLayoutForSize(currentSizeIndex);
      scheduleTemplateStateSave();
    }

    function updateAnchor(anchorKey, nextAnchor) {
      const size = materialSizes[frameworkSizeIndex] || materialSizes[0];
      const targetAnchors = ensureDraftAnchorsForActiveSize(size);
      targetAnchors[anchorKey] = normalizedAnchor(anchorKey, nextAnchor, targetAnchors[anchorKey], size);
      if (isTemplateBaseSize(size)) {
        draftTemplateAnchors = ensureIndependentCopyAnchors(draftTemplateAnchors);
      } else {
        draftTemplateAnchors.sizeAnchors[templateSizeKey(size)] = ensureIndependentCopyAnchors(targetAnchors);
      }
      renderAnchorEditor();
    }

    function updateAnchors(anchorKeys, nextAnchorForKey) {
      const size = materialSizes[frameworkSizeIndex] || materialSizes[0];
      const targetAnchors = ensureDraftAnchorsForActiveSize(size);
      anchorKeys.forEach(anchorKey => {
        targetAnchors[anchorKey] = normalizedAnchor(anchorKey, nextAnchorForKey(anchorKey), targetAnchors[anchorKey], size);
      });
      if (isTemplateBaseSize(size)) {
        draftTemplateAnchors = ensureIndependentCopyAnchors(draftTemplateAnchors);
      } else {
        draftTemplateAnchors.sizeAnchors[templateSizeKey(size)] = ensureIndependentCopyAnchors(targetAnchors);
      }
      renderAnchorEditor();
    }

    function alignSelectedAnchors(action) {
      const currentAnchors = anchorEditorPreviewAnchors();
      const anchorKeys = [...selectedAnchorKeys].filter(key => currentAnchors[key]);
      if (anchorKeys.length < 2) {
        showToast('请先多选至少两个锚点');
        return;
      }
      const anchors = anchorKeys.map(key => currentAnchors[key]);
      const left = Math.min(...anchors.map(anchor => anchor.x));
      const top = Math.min(...anchors.map(anchor => anchor.y));
      const right = Math.max(...anchors.map(anchor => anchor.x + anchor.w));
      const bottom = Math.max(...anchors.map(anchor => anchor.y + anchor.h));
      const centerX = (left + right) / 2;
      const centerY = (top + bottom) / 2;
      updateAnchors(anchorKeys, anchorKey => {
        const anchor = currentAnchors[anchorKey];
        if (action === 'left') return { ...anchor, x: left };
        if (action === 'hcenter') return { ...anchor, x: centerX - anchor.w / 2 };
        if (action === 'right') return { ...anchor, x: right - anchor.w };
        if (action === 'top') return { ...anchor, y: top };
        if (action === 'vcenter') return { ...anchor, y: centerY - anchor.h / 2 };
        if (action === 'bottom') return { ...anchor, y: bottom - anchor.h };
        return anchor;
      });
      showToast('已对齐选中的锚点，请提交模板映射');
    }

    const imageAlphaBoundsCache = new WeakMap();

    function elementTextBounds(element) {
      if (!element) return null;
      const rects = [];
      const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
      let node = walker.nextNode();
      while (node) {
        const text = node.textContent || '';
        for (let index = 0; index < text.length; index += 1) {
          if (!/\S/.test(text[index])) continue;
          const range = document.createRange();
          range.setStart(node, index);
          range.setEnd(node, index + 1);
          const rect = range.getBoundingClientRect();
          range.detach?.();
          if (rect.width && rect.height) rects.push(rect);
        }
        node = walker.nextNode();
      }
      if (rects.length) {
        const left = Math.min(...rects.map(rect => rect.left));
        const top = Math.min(...rects.map(rect => rect.top));
        const right = Math.max(...rects.map(rect => rect.right));
        const bottom = Math.max(...rects.map(rect => rect.bottom));
        return { left, top, right, bottom, width: right - left, height: bottom - top };
      }
      const fallbackRange = document.createRange();
      fallbackRange.selectNodeContents(element);
      const fallbackRect = fallbackRange.getBoundingClientRect();
      fallbackRange.detach?.();
      return fallbackRect.width && fallbackRect.height ? fallbackRect : element.getBoundingClientRect();
    }

    function imageAlphaBounds(image) {
      if (!image?.complete || !image.naturalWidth || !image.naturalHeight) return null;
      if (imageAlphaBoundsCache.has(image)) return imageAlphaBoundsCache.get(image);
      let bounds = null;
      try {
        const canvas = document.createElement('canvas');
        canvas.width = image.naturalWidth;
        canvas.height = image.naturalHeight;
        const context = canvas.getContext('2d', { willReadFrequently: true });
        context.drawImage(image, 0, 0);
        const { data, width, height } = context.getImageData(0, 0, canvas.width, canvas.height);
        let left = width;
        let top = height;
        let right = -1;
        let bottom = -1;
        for (let y = 0; y < height; y += 1) {
          for (let x = 0; x < width; x += 1) {
            const alpha = data[(y * width + x) * 4 + 3];
            if (alpha <= 8) continue;
            left = Math.min(left, x);
            top = Math.min(top, y);
            right = Math.max(right, x);
            bottom = Math.max(bottom, y);
          }
        }
        if (right >= left && bottom >= top) {
          bounds = { left, top, width: right - left + 1, height: bottom - top + 1 };
        }
      } catch (error) {
        bounds = null;
      }
      imageAlphaBoundsCache.set(image, bounds);
      return bounds;
    }

    function containedImageBounds(image) {
      const container = image?.parentElement?.getBoundingClientRect();
      if (!image || !container || !image.naturalWidth || !image.naturalHeight) return image?.getBoundingClientRect() || null;
      const imageRatio = image.naturalWidth / image.naturalHeight;
      const containerRatio = container.width / Math.max(1, container.height);
      let width = container.width;
      let height = container.height;
      if (imageRatio > containerRatio) {
        height = width / imageRatio;
      } else {
        width = height * imageRatio;
      }
      const visible = imageAlphaBounds(image);
      if (visible) {
        const scaleX = width / image.naturalWidth;
        const scaleY = height / image.naturalHeight;
        return {
          left: container.left + visible.left * scaleX,
          top: container.top + visible.top * scaleY,
          width: visible.width * scaleX,
          height: visible.height * scaleY
        };
      }
      return {
        left: container.left,
        top: container.top,
        width,
        height
      };
    }

    function posterVisibleBoundsForAnchor(key) {
      if (key === 'title') return elementTextBounds(previewTitle);
      if (key === 'subtitle') return elementTextBounds(previewSubtitle);
      if (key === 'cta') return previewCta?.getBoundingClientRect() || null;
      if (key === 'logo') return containedImageBounds(creativeLogoImage);
      if (key === 'image') return productFrame?.getBoundingClientRect() || null;
      return null;
    }

    function posterOverlayAnchor(key, anchor) {
      const bounds = posterVisibleBoundsForAnchor(key);
      const host = materialCard?.getBoundingClientRect();
      if (!bounds || !host || !bounds.width || !bounds.height) return anchor;
      const padding = key === 'title' || key === 'subtitle' ? 3 : 2;
      const leftPx = clamp(bounds.left - host.left - padding, 0, host.width);
      const topPx = clamp(bounds.top - host.top - padding, 0, host.height);
      const rightPx = clamp(bounds.left - host.left + bounds.width + padding, 0, host.width);
      const bottomPx = clamp(bounds.top - host.top + bounds.height + padding, 0, host.height);
      const widthPct = ((rightPx - leftPx) / Math.max(1, host.width)) * 100;
      const heightPct = ((bottomPx - topPx) / Math.max(1, host.height)) * 100;
      return {
        ...anchor,
        x: (leftPx / Math.max(1, host.width)) * 100,
        y: (topPx / Math.max(1, host.height)) * 100,
        w: Math.max(1, widthPct),
        h: Math.max(1, heightPct)
      };
    }

    function renderPosterEditOverlay(anchors = effectivePosterAnchorsForSize()) {
      if (!posterEditOverlay) return;
      posterEditOverlay.querySelectorAll('.poster-anchor-box').forEach(box => {
        const key = box.dataset.posterAnchor;
        if (key === 'image') {
          box.querySelectorAll('.poster-anchor-handle').forEach(handle => handle.remove());
          box.dataset.edgeHandlesReady = '';
        } else {
          ensureEdgeResizeHandles(box, 'poster-anchor-handle');
        }
        const anchor = anchors[key];
        if (!anchor) return;
        const overlayAnchor = posterOverlayAnchor(key, anchor);
        box.classList.toggle('hidden', Boolean(anchor.hidden) || (key === 'trust' && !effectiveTrustVisible()));
        box.style.left = formatPct(overlayAnchor.x);
        box.style.top = formatPct(overlayAnchor.y);
        box.style.width = formatPct(overlayAnchor.w);
        box.style.height = formatPct(overlayAnchor.h);
        box.classList.toggle('is-active', key === activePosterAnchor);
        box.classList.toggle('is-selected', selectedPosterAnchorKeys.has(key));
        syncFontSizeToolbar(box, 'poster', key, anchor);
      });
      updatePosterAlignToolbar();
    }

    function clearPosterAnchorSelection() {
      if (!activePosterAnchor && !selectedPosterAnchorKeys.size) return;
      activePosterAnchor = null;
      selectedPosterAnchorKeys = new Set();
      renderPosterEditOverlay();
    }

    function updatePosterAlignToolbar() {
      const singleCopyAreaAnchorSelected = selectedPosterAnchorKeys.size === 1
        && ['logo', 'title', 'subtitle', 'cta'].includes([...selectedPosterAnchorKeys][0]);
      const canAlign = generated && (selectedPosterAnchorKeys.size > 1 || singleCopyAreaAnchorSelected);
      document.querySelectorAll('[data-poster-align-action]').forEach(button => {
        button.disabled = !generated || (button.dataset.posterAlignAction !== 'reset' && !canAlign);
      });
      updatePosterUndoState();
    }

    const POSTER_CONTEXT_ALIGN_ACTIONS = [
      { action: 'left', label: '左对齐', icon: '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 3.5v13"/><path d="M8 6h8"/><path d="M8 10h6"/><path d="M8 14h9"/></svg>' },
      { action: 'hcenter', label: '水平居中对齐', icon: '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 3.5v13"/><path d="M6 6h8"/><path d="M7.5 10h5"/><path d="M5 14h10"/></svg>' },
      { action: 'right', label: '右对齐', icon: '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 3.5v13"/><path d="M4 6h8"/><path d="M6 10h6"/><path d="M3 14h9"/></svg>' },
      { action: 'top', label: '顶部对齐', icon: '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 4h13"/><path d="M6 8v8"/><path d="M10 8v6"/><path d="M14 8v9"/></svg>' },
      { action: 'vcenter', label: '垂直居中对齐', icon: '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 10h13"/><path d="M6 6v8"/><path d="M10 7.5v5"/><path d="M14 5v10"/></svg>' },
      { action: 'bottom', label: '底部对齐', icon: '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 16h13"/><path d="M6 4v8"/><path d="M10 6v6"/><path d="M14 3v9"/></svg>' },
      { action: 'reset', label: '恢复当前尺寸', icon: '' }
    ];

    const POSTER_CONTEXT_CTA_SIZE_ACTIONS = [
      { action: 'cta-size-large', label: '大尺寸' },
      { action: 'cta-size-small', label: '小尺寸' }
    ];

    function posterContextAlignTitle() {
      const alignableCount = [...selectedPosterAnchorKeys]
        .filter(key => key !== 'image' && posterEditableAnchorKeys.includes(key))
        .length;
      return alignableCount > 1 ? '元素对齐' : '页面对齐';
    }

    function ensurePosterContextMenu() {
      let menu = document.getElementById('posterContextMenu');
      if (menu) return menu;
      menu = document.createElement('div');
      menu.id = 'posterContextMenu';
      menu.className = 'poster-context-menu';
      menu.setAttribute('role', 'menu');
      menu.innerHTML = `
        <div class="poster-context-row poster-context-row--submenu poster-context-row--no-icon" data-poster-submenu-trigger="align" role="menuitem" tabindex="0">
          <span class="poster-context-row-label" data-poster-context-align-title>页面对齐</span>
          <span class="poster-context-row-arrow" aria-hidden="true">›</span>
          <div class="poster-context-flyout poster-context-flyout--align" role="menu" aria-label="对齐选项">
            ${POSTER_CONTEXT_ALIGN_ACTIONS.filter(item => item.action !== 'reset').map(item => `
              <button class="poster-context-action" type="button" role="menuitem" data-poster-context-action="${item.action}">
                ${item.icon}
                <span>${item.label}</span>
              </button>
            `).join('')}
          </div>
        </div>
        <button class="poster-context-row poster-context-row--button" type="button" role="menuitem" data-poster-context-action="reset">
          <span class="poster-context-row-label">恢复当前尺寸</span>
        </button>
        <div class="poster-context-row poster-context-row--submenu poster-context-row--no-icon poster-context-row--cta-size" data-poster-submenu-trigger="cta-size" role="menuitem" tabindex="0">
          <span class="poster-context-row-label">按钮尺寸</span>
          <span class="poster-context-row-arrow" aria-hidden="true">›</span>
          <div class="poster-context-flyout poster-context-flyout--cta-size" role="menu" aria-label="按钮尺寸">
            ${POSTER_CONTEXT_CTA_SIZE_ACTIONS.map(item => `
              <button class="poster-context-action poster-context-action--cta-size" type="button" role="menuitem" data-poster-context-action="${item.action}">
                <span>${item.label}</span>
              </button>
            `).join('')}
          </div>
        </div>
      `;
      menu.addEventListener('click', event => {
        const button = event.target.closest('[data-poster-context-action]');
        if (!button || button.disabled) return;
        const action = button.dataset.posterContextAction;
        hidePosterContextMenu();
        if (action?.startsWith('cta-size-')) {
          applyCtaSizePreset(action === 'cta-size-small' ? 'small' : 'large');
          return;
        }
        alignSelectedPosterAnchors(action);
      });
      document.body.appendChild(menu);
      return menu;
    }

    function hidePosterContextMenu() {
      const menu = document.getElementById('posterContextMenu');
      if (!menu) return;
      menu.classList.remove('open');
      menu.style.removeProperty('left');
      menu.style.removeProperty('top');
    }

    function hideMainImageMenus() {
      hidePosterContextMenu();
    }

    function showPosterContextMenu(event) {
      const menu = ensurePosterContextMenu();
      const alignableCount = [...selectedPosterAnchorKeys]
        .filter(key => key !== 'image' && posterEditableAnchorKeys.includes(key))
        .length;
      const singleCopyAnchorSelected = selectedPosterAnchorKeys.size === 1 && ['logo', 'title', 'subtitle', 'cta'].includes(activePosterAnchor);
      menu.classList.toggle('show-cta-size', activePosterAnchor === 'cta');
      menu.querySelector('[data-poster-context-align-title]').textContent = posterContextAlignTitle();
      menu.querySelectorAll('[data-poster-context-action]').forEach(button => {
        const action = button.dataset.posterContextAction;
        const isCtaSizeAction = action?.startsWith('cta-size-');
        button.disabled = !generated
          || (isCtaSizeAction && activePosterAnchor !== 'cta')
          || (!isCtaSizeAction && action !== 'reset' && alignableCount < 2 && !singleCopyAnchorSelected);
      });
      menu.classList.add('open');
      const rect = menu.getBoundingClientRect();
      menu.classList.toggle('open-left', event.clientX + rect.width + 370 > window.innerWidth);
      const left = Math.min(event.clientX, window.innerWidth - rect.width - 12);
      const top = Math.min(event.clientY, window.innerHeight - rect.height - 12);
      menu.style.left = `${Math.max(12, left)}px`;
      menu.style.top = `${Math.max(12, top)}px`;
    }

    function normalizedPosterAnchor(anchorKey, nextAnchor, baseAnchor, size = materialSizes[currentSizeIndex]) {
      const minSize = anchorKey === 'logo' || anchorKey === 'trust' ? 4 : 5;
      const normalized = {
        ...(baseAnchor || {}),
        x: clamp(nextAnchor.x, 0, 100 - minSize),
        y: clamp(nextAnchor.y, 0, 100 - minSize),
        w: clamp(nextAnchor.w, minSize, 100),
        h: clamp(nextAnchor.h, minSize, 100)
      };
      if (Number.isFinite(Number(nextAnchor.font))) normalized.font = clamp(Number(nextAnchor.font), 0.6, 40);
      if (Number.isFinite(Number(nextAnchor.fontScale))) normalized.fontScale = clamp(Number(nextAnchor.fontScale), 0.05, 8);
      if (['left', 'center', 'right'].includes(nextAnchor.align)) normalized.align = nextAnchor.align;
      if (['top', 'center', 'bottom'].includes(nextAnchor.vAlign)) normalized.vAlign = nextAnchor.vAlign;
      if (anchorKey === 'cta') {
        if (Number.isFinite(Number(nextAnchor.padX))) normalized.padX = Math.max(0, Number(nextAnchor.padX));
        if (Number.isFinite(Number(nextAnchor.padY))) normalized.padY = Math.max(0, Number(nextAnchor.padY));
        if (Number.isFinite(Number(nextAnchor.lineHeight))) normalized.lineHeight = Math.max(0.5, Number(nextAnchor.lineHeight));
        if (typeof nextAnchor.autoWidth === 'boolean') normalized.autoWidth = nextAnchor.autoWidth;
      }
      normalized.x = clamp(normalized.x, 0, 100 - normalized.w);
      normalized.y = clamp(normalized.y, 0, 100 - normalized.h);
      return anchorKey === 'cta' ? normalizeCtaAnchorRatio(normalized, size) : normalized;
    }

    function ctaDefaultPaddingPercent(size, axis) {
      const width = Number(size?.width) || CTA_TEMPLATE_RATIO_SIZE.width;
      const height = Number(size?.height) || CTA_TEMPLATE_RATIO_SIZE.height;
      const scale = Math.max(0.08, Math.min(width / 1200, height / 628));
      const px = axis === 'y' ? Math.max(2, 20 * scale) : Math.max(4, 40 * scale);
      return (px / Math.max(1, axis === 'y' ? height : width)) * 100;
    }

    function ctaPaddingPercent(anchor, size, axis) {
      const key = axis === 'y' ? 'padY' : 'padX';
      const value = Number(anchor?.[key]);
      return Number.isFinite(value) ? value : ctaDefaultPaddingPercent(size, axis);
    }

    function ctaWrapLines(ctx, text, maxWidth) {
      const cleanText = String(text || '').replace(/\s+/g, ' ').trim();
      if (!cleanText) return [''];
      const lines = [];
      cleanText.split('\n').forEach(sourceLine => {
        const hasSpaces = /\s/.test(sourceLine.trim());
        const parts = hasSpaces ? sourceLine.split(/(\s+)/).filter(Boolean) : [...sourceLine];
        let current = '';
        parts.forEach(part => {
          const next = current + part;
          if (current && ctx.measureText(next).width > maxWidth) {
            lines.push(current.trim());
            current = part.trimStart();
          } else {
            current = next;
          }
        });
        if (current) lines.push(current.trim());
      });
      return lines.length ? lines : [''];
    }

    function ctaTextHeightPercent(anchor, size, text = '', padXPercent = ctaPaddingPercent(anchor, size, 'x')) {
      const height = Math.max(1, Number(size?.height) || CTA_TEMPLATE_RATIO_SIZE.height);
      const width = Math.max(1, Number(size?.width) || CTA_TEMPLATE_RATIO_SIZE.width);
      const fontPx = Number(anchor?.fontPx);
      const fontScale = Number(anchor?.fontScale);
      const fontPercent = Number.isFinite(fontPx) && fontPx > 0
        ? (fontPx * (Number.isFinite(fontScale) && fontScale > 0 ? fontScale : 1) / height) * 100
        : (Number(anchor?.font) || Math.max(1, (Number(anchor?.h) || 8) * 0.38));
      const lineHeight = Number(anchor?.lineHeight) || 1.4;
      const fontSize = (fontPercent / 100) * height;
      const padX = (Number(padXPercent) / 100) * width;
      const rectWidth = Math.max(1, ((Number(anchor?.w) || 1) / 100) * width);
      let lineCount = String(text || '').split('\n').length || 1;
      const cleanText = String(text || '').replace(/\s+/g, ' ').trim();
      if (cleanText && anchor?.autoWidth !== true) {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.font = `700 ${fontSize}px Arial, "Noto Sans CJK SC", "PingFang SC", sans-serif`;
          lineCount = ctaWrapLines(ctx, cleanText, Math.max(1, rectWidth - padX * 2)).length;
        }
      }
      return fontPercent * lineHeight * Math.max(1, lineCount);
    }

    function applyCtaSizePreset(preset) {
      const size = materialSizes[currentSizeIndex] || materialSizes[0];
      const anchors = effectivePosterAnchorsForSize();
      const current = anchors.cta;
      if (!generated || !current) return;
      const base = basePosterAnchorsForSize(size, templateAnchors).cta || current;
      const basePadX = ctaPaddingPercent(base, size, 'x');
      const basePadY = ctaPaddingPercent(base, size, 'y');
      const scale = preset === 'small' ? 0.5 : 1;
      const nextPadX = basePadX * scale;
      const nextPadY = basePadY * scale;
      const contentHeight = ctaTextHeightPercent(current, size, previewCta?.textContent || getLanguageCopy(currentLanguageIndex).cta, nextPadX);
      const fittedHeight = clamp(contentHeight + nextPadY * 2, 4, 100);
      const next = {
        ...current,
        padX: nextPadX,
        padY: nextPadY,
        h: preset === 'small'
          ? fittedHeight
          : Math.max(Number(base.h) || current.h, fittedHeight)
      };
      pushPosterEditHistory();
      setPosterOverride('cta', next);
      activePosterAnchor = 'cta';
      selectedPosterAnchorKeys = new Set(['cta']);
      renderPosterEditOverlay();
      showToast(preset === 'small' ? '按钮已切换为小尺寸：上下左右间距约为当前一半' : '按钮已切换为大尺寸：恢复当前尺寸默认间距');
    }

    function setPosterOverride(anchorKey, nextAnchor) {
      const size = materialSizes[currentSizeIndex] || materialSizes[0];
      const key = posterOverrideBucketKey(anchorKey, size, currentLanguageIndex);
      const base = basePosterAnchorsForSize(size, templateAnchors)[anchorKey];
      posterAnchorOverrides[key] = posterAnchorOverrides[key] || {};
      posterAnchorOverrides[key][anchorKey] = normalizedPosterAnchor(anchorKey, nextAnchor, base, size);
      applyPosterLayoutForSize(currentSizeIndex);
      requestAnimationFrame(updateProductImageFrame);
    }

    function setPosterOverrides(anchorKeys, nextAnchorForKey) {
      const size = materialSizes[currentSizeIndex] || materialSizes[0];
      const baseAnchors = basePosterAnchorsForSize(size, templateAnchors);
      anchorKeys.forEach(anchorKey => {
        const key = posterOverrideBucketKey(anchorKey, size, currentLanguageIndex);
        posterAnchorOverrides[key] = posterAnchorOverrides[key] || {};
        posterAnchorOverrides[key][anchorKey] = normalizedPosterAnchor(anchorKey, nextAnchorForKey(anchorKey), baseAnchors[anchorKey], size);
      });
      applyPosterLayoutForSize(currentSizeIndex);
      requestAnimationFrame(updateProductImageFrame);
    }

    function isKeyboardMoveBlocked(event) {
      const target = event.target;
      const isEditableTarget = target?.matches?.('input, textarea, select, button') || target?.isContentEditable;
      return isEditableTarget || Boolean(document.querySelector('.confirm-modal.open'));
    }

    function keyboardMoveDelta(event, host) {
      const rect = host?.getBoundingClientRect?.();
      if (!rect?.width || !rect?.height) return null;
      const stepPx = event.shiftKey ? 10 : 1;
      const delta = {
        ArrowLeft: { dx: -stepPx, dy: 0 },
        ArrowRight: { dx: stepPx, dy: 0 },
        ArrowUp: { dx: 0, dy: -stepPx },
        ArrowDown: { dx: 0, dy: stepPx }
      }[event.key];
      if (!delta) return null;
      return {
        dx: (delta.dx / rect.width) * 100,
        dy: (delta.dy / rect.height) * 100
      };
    }

    function moveSelectedTemplateAnchorsByKeyboard(event) {
      if (document.getElementById('templateManagerView')?.classList.contains('hidden')) return false;
      const currentAnchors = anchorEditorPreviewAnchors();
      const anchorKeys = [...selectedAnchorKeys].filter(key => currentAnchors[key]);
      const delta = anchorKeys.length ? keyboardMoveDelta(event, anchorCanvas) : null;
      if (!delta) return false;
      event.preventDefault();
      updateAnchors(anchorKeys, anchorKey => {
        const base = currentAnchors[anchorKey];
        return { ...base, x: base.x + delta.dx, y: base.y + delta.dy };
      });
      return true;
    }

    function moveSelectedPosterAnchorsByKeyboard(event) {
      if (!generated || document.getElementById('generatorView')?.classList.contains('hidden')) return false;
      const anchors = effectivePosterAnchorsForSize();
      const anchorKeys = [...selectedPosterAnchorKeys]
        .filter(key => key !== 'image' && posterEditableAnchorKeys.includes(key) && anchors[key]);
      const delta = anchorKeys.length ? keyboardMoveDelta(event, materialCard) : null;
      if (!delta) return false;
      event.preventDefault();
      pushPosterEditHistory();
      setPosterOverrides(anchorKeys, anchorKey => {
        const base = anchors[anchorKey];
        return { ...base, x: base.x + delta.dx, y: base.y + delta.dy };
      });
      return true;
    }

    function normalizedFrame(frame) {
      if (!frame || !['x', 'y', 'w', 'h'].every(key => Number.isFinite(Number(frame[key])))) return null;
      const x = clamp(Number(frame.x), 0, 100);
      const y = clamp(Number(frame.y), 0, 100);
      const w = clamp(Number(frame.w), 0, 100 - x);
      const h = clamp(Number(frame.h), 0, 100 - y);
      return w > 0 && h > 0 ? { x, y, w, h } : null;
    }

    function visibleCopyContentBounds(anchors) {
      const copyAnchors = ['logo', 'title', 'subtitle', 'cta']
        .map(key => anchors?.[key])
        .filter(anchor => anchor && !anchor.hidden);
      if (!copyAnchors.length) return null;
      const left = Math.min(...copyAnchors.map(anchor => Number(anchor.x) || 0));
      const top = Math.min(...copyAnchors.map(anchor => Number(anchor.y) || 0));
      const right = Math.max(...copyAnchors.map(anchor => (Number(anchor.x) || 0) + (Number(anchor.w) || 0)));
      const bottom = Math.max(...copyAnchors.map(anchor => (Number(anchor.y) || 0) + (Number(anchor.h) || 0)));
      return normalizedFrame({ x: left, y: top, w: right - left, h: bottom - top });
    }

    function nonImageCopyAreaForAlignment(anchors) {
      const image = normalizedFrame(anchors?.imageVisibleArea || anchors?.imageVisualArea || anchors?.image);
      if (!image || anchors?.image?.hidden) return null;
      const imageRight = image.x + image.w;
      const imageBottom = image.y + image.h;
      const imageCenterX = image.x + image.w / 2;
      const imageCenterY = image.y + image.h / 2;
      const spansMostHeight = image.h >= 70;
      const spansMostWidth = image.w >= 70;

      // copyArea means the full non-image side of the current size, not the
      // smaller bounds currently occupied by title/subtitle/button/logo.
      if (spansMostHeight) {
        if (imageCenterX >= 50 && image.x > 0) return normalizedFrame({ x: 0, y: 0, w: image.x, h: 100 });
        if (imageRight < 100) return normalizedFrame({ x: imageRight, y: 0, w: 100 - imageRight, h: 100 });
      }

      if (spansMostWidth) {
        if (imageCenterY >= 50 && image.y > 0) return normalizedFrame({ x: 0, y: 0, w: 100, h: image.y });
        if (imageBottom < 100) return normalizedFrame({ x: 0, y: imageBottom, w: 100, h: 100 - imageBottom });
      }

      return null;
    }

    function posterCopyFrameForAlignment(anchors) {
      const explicitCopyArea = normalizedFrame(anchors?.copyArea);
      if (explicitCopyArea) return explicitCopyArea;
      const nonImageCopyArea = nonImageCopyAreaForAlignment(anchors);
      if (nonImageCopyArea) return nonImageCopyArea;
      const stack = anchors?.contentStack;
      const contentStackFrame = normalizedFrame(stack);
      if (contentStackFrame) return contentStackFrame;
      return visibleCopyContentBounds(anchors);
    }

    function alignSinglePosterCopyAnchor(anchorKey, action, anchors) {
      const anchor = anchors?.[anchorKey];
      const frame = normalizedFrame({ x: 0, y: 0, w: 100, h: 100 });
      if (!anchor || !frame) return false;
      const next = { ...anchor };
      if (action === 'left') next.x = frame.x;
      if (action === 'hcenter') next.x = frame.x + (frame.w - anchor.w) / 2;
      if (action === 'right') next.x = frame.x + frame.w - anchor.w;
      if (action === 'top') next.y = frame.y;
      if (action === 'vcenter') next.y = frame.y + (frame.h - anchor.h) / 2;
      if (action === 'bottom') next.y = frame.y + frame.h - anchor.h;
      pushPosterEditHistory();
      setPosterOverride(anchorKey, next);
      showToast('已按当前尺寸画布对齐选中元素');
      return true;
    }

    document.addEventListener('keydown', event => {
      if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key) || isKeyboardMoveBlocked(event)) return;
      moveSelectedTemplateAnchorsByKeyboard(event) || moveSelectedPosterAnchorsByKeyboard(event);
    });

    function alignSelectedPosterAnchors(action) {
      if (action === 'reset') {
        pushPosterEditHistory();
        const size = materialSizes[currentSizeIndex] || materialSizes[0];
        delete posterAnchorOverrides[posterOverrideKey(size)];
        delete posterAnchorOverrides[posterLanguageOverrideKey(size, currentLanguageIndex)];
        activePosterAnchor = null;
        selectedPosterAnchorKeys = new Set();
        applyPosterLayoutForSize(currentSizeIndex);
        renderPosterEditOverlay();
        showToast('当前语言文本布局与当前尺寸共享元素已恢复生成规则');
        return;
      }
      const anchorKeys = [...selectedPosterAnchorKeys].filter(key => posterEditableAnchorKeys.includes(key) && key !== 'image');
      const anchors = effectivePosterAnchorsForSize();
      if (anchorKeys.length === 1 && ['logo', 'title', 'subtitle', 'cta'].includes(anchorKeys[0])) {
        alignSinglePosterCopyAnchor(anchorKeys[0], action, anchors);
        return;
      }
      if (anchorKeys.length < 2) {
        showToast(selectedPosterAnchorKeys.has('image') ? '主图仅支持拖动图片，不支持对齐框位置' : '请先多选至少两个元素');
        return;
      }
      const selectedAnchors = anchorKeys.map(key => anchors[key]);
      const left = Math.min(...selectedAnchors.map(anchor => anchor.x));
      const top = Math.min(...selectedAnchors.map(anchor => anchor.y));
      const right = Math.max(...selectedAnchors.map(anchor => anchor.x + anchor.w));
      const bottom = Math.max(...selectedAnchors.map(anchor => anchor.y + anchor.h));
      const centerX = (left + right) / 2;
      const centerY = (top + bottom) / 2;
      pushPosterEditHistory();
      setPosterOverrides(anchorKeys, anchorKey => {
        const anchor = anchors[anchorKey];
        if (action === 'left') return { ...anchor, x: left };
        if (action === 'hcenter') return { ...anchor, x: centerX - anchor.w / 2 };
        if (action === 'right') return { ...anchor, x: right - anchor.w };
        if (action === 'top') return { ...anchor, y: top };
        if (action === 'vcenter') return { ...anchor, y: centerY - anchor.h / 2 };
        if (action === 'bottom') return { ...anchor, y: bottom - anchor.h };
        return anchor;
      });
      showToast('已对齐当前尺寸选中的元素');
    }

    function loadStyleMapping(styleKey) {
      selectedStyle = styleKey || stylePresets[0]?.id || 'style-1';
      styleMaps[selectedStyle] = styleMaps[selectedStyle] || cloneStyles(defaultTemplateStyles);
      templateStyles = cloneStyles(styleMaps[selectedStyle]);
      draftTemplateStyles = cloneStyles(templateStyles);
      renderStyleEditor();
      renderTemplateOptions();
      applyTemplateAnchors();
      saveTemplateState();
    }

    function renderStyleSwitchOptions() {
      if (!styleSwitchGrid) return;
      styleSwitchGrid.innerHTML = stylePresets.map(style => {
        const styles = normalizeButtonColors(cloneStyles(styleMaps[style.id] || defaultStylesForId(style.id)));
        const background = templateBackgroundCss(styles);
        const isActive = style.id === selectedStyle;
        return `
          <button class="style-option-card ${isActive ? 'active' : ''}" type="button" data-style-switch="${escapeHtml(style.id)}" aria-label="切换到${escapeHtml(styleDisplayName(style))}">
            <span class="style-option-preview" style="--style-bg:${escapeHtml(background)};--style-copy:${escapeHtml(styles.textColor || '#081840')};--style-button:${escapeHtml(styles.buttonColor || FIGMA_BUTTON_FILL_COLOR)};--style-button-text:${escapeHtml(styles.buttonTextColor || FIGMA_BUTTON_TEXT_COLOR)}" aria-hidden="true">
              <span class="style-option-dot"></span>
              <span class="style-option-title">Text</span>
              <span class="style-option-pill">Text</span>
            </span>
            <span class="style-option-copy">
              <span class="style-option-name">${escapeHtml(styleDisplayName(style))}</span>
            </span>
          </button>
        `;
      }).join('');
    }

    function closeStyleSwitchModal() {
      styleSwitchModal?.classList.remove('open');
      styleSwitchModal?.setAttribute('aria-hidden', 'true');
    }

    function openStyleSwitchModal() {
      if (!generated) {
        showToast('请先生成后再切换样式');
        return;
      }
      renderStyleSwitchOptions();
      styleSwitchModal?.classList.add('open');
      styleSwitchModal?.setAttribute('aria-hidden', 'false');
    }

    function applyStylePresetFromResults(styleKey) {
      if (!styleKey || !styleMaps[styleKey]) return;
      loadStyleMapping(styleKey);
      applyRuleVisualStyles(currentPreviewAsset());
      applyPosterLayoutForSize(currentSizeIndex);
      renderStyleSwitchOptions();
      showToast(`已切换为${styleName(styleKey)}`);
      closeStyleSwitchModal();
    }

    function loadTemplateMapping(templateKey) {
      selectedTemplate = templateKey || templates[0].id;
      templateAnchorMaps[selectedTemplate] = completeAnchors(templateAnchorMaps[selectedTemplate] || defaultTemplateAnchors);
      templateAnchors = cloneAnchors(templateAnchorMaps[selectedTemplate]);
      draftTemplateAnchors = cloneAnchors(templateAnchors);
      activeAnchor = null;
      selectedAnchorKeys = new Set();
      posterAnchorOverrides = {};
      activePosterAnchor = null;
      selectedPosterAnchorKeys = new Set();
      gradientControlActive = false;
      renderTemplateOptions();
      applyTemplateAnchors();
      materialCard.style.filter = templateById(selectedTemplate)?.variant === 'dark' ? 'saturate(.85) contrast(1.05)' : 'none';
      saveTemplateState();
    }

    function commitTemplateMapping() {
      templateAnchorMaps[selectedTemplate] = completeAnchors(draftTemplateAnchors);
      templateAnchors = cloneAnchors(templateAnchorMaps[selectedTemplate]);
      applyTemplateAnchors();
      saveTemplateState();
      showToast(`${templateName()}已同步到促销材料`);
    }

    function nextTemplateId() {
      let index = templates.length + 1;
      while (templates.some(template => template.id === `template-${index}`)) index += 1;
      return `template-${index}`;
    }

    function nextStyleId() {
      let index = stylePresets.length + 1;
      while (stylePresets.some(style => style.id === `style-${index}`)) index += 1;
      return `style-${index}`;
    }

    function addStyle() {
      const id = nextStyleId();
      const index = Number(id.replace('style-', ''));
      stylePresets.push({ id, name: `样式 ${index}` });
      styleMaps[id] = cloneStyles(templateStyles || defaultTemplateStyles);
      loadStyleMapping(id);
      showToast(`${styleName(id)}已新增`);
    }

    function deleteStyle() {
      if (stylePresets.length <= 1) {
        showToast('至少保留一个样式');
        return;
      }
      const deleteIndex = stylePresets.findIndex(style => style.id === selectedStyle);
      if (deleteIndex < 0) return;
      const deletedName = styleName(selectedStyle);
      const [deletedStyle] = stylePresets.splice(deleteIndex, 1);
      delete styleMaps[deletedStyle.id];
      const nextStyle = stylePresets[Math.min(deleteIndex, stylePresets.length - 1)] || stylePresets[0];
      loadStyleMapping(nextStyle.id);
      showToast(`${deletedName}已删除`);
    }

    function addTemplate() {
      const id = nextTemplateId();
      const index = Number(id.replace('template-', ''));
      templates.push({
        id,
        name: `模板 ${index}`,
        variant: templates.length % 2 === 0 ? 'light' : 'dark'
      });
      templateAnchorMaps[id] = completeAnchors(templateAnchors || defaultTemplateAnchors);
      loadTemplateMapping(id);
      saveTemplateState();
      showToast(`${templateName(id)}已新增，并映射到促销材料`);
    }

    function deleteTemplate() {
      if (templates.length <= 1) {
        showToast('至少保留一个模板');
        return;
      }
      const deleteIndex = templates.findIndex(template => template.id === selectedTemplate);
      if (deleteIndex < 0) return;
      const deletedName = templateName(selectedTemplate);
      const [deletedTemplate] = templates.splice(deleteIndex, 1);
      delete templateAnchorMaps[deletedTemplate.id];
      const nextTemplate = templates[Math.min(deleteIndex, templates.length - 1)] || templates[0];
      loadTemplateMapping(nextTemplate.id);
      saveTemplateState();
      showToast(`${deletedName}已删除，并同步到促销材料`);
    }

    function reorderTemplate(from, to) {
      if (!Number.isInteger(from) || !Number.isInteger(to) || from === to || !templates[from] || !templates[to]) return;
      moveArrayItem(templates, from, to);
      renderTemplateOptions();
      saveTemplateState();
      showToast('模板排序已同步到促销材料');
    }

    function renameTemplate(templateKey, nextName) {
      const template = templateById(templateKey);
      if (!template) return false;
      const trimmed = String(nextName || '').trim();
      if (!trimmed) {
        showToast('模板名称不能为空');
        return false;
      }
      template.name = trimmed.slice(0, 16);
      renderTemplateOptions();
      updateTemplateMappingStatus();
      saveTemplateState();
      showToast(`${template.name}已重命名，并同步到促销材料`);
      return true;
    }

    function startTemplateRename(card) {
      const template = templateById(card?.dataset.template);
      if (!template || !card) return;
      openTemplateRenameModal(template.id);
    }

    function closeTemplateRenameModal() {
      document.getElementById('templateRenameModal')?.classList.remove('open');
      templateRenameTarget = null;
    }

    function submitTemplateRenameModal() {
      const modal = document.getElementById('templateRenameModal');
      if (!modal || !templateRenameTarget) return;
      const input = modal.querySelector('#templateRenameInput');
      if (renameTemplate(templateRenameTarget, input?.value)) closeTemplateRenameModal();
    }

    function ensureTemplateRenameModal() {
      let modal = document.getElementById('templateRenameModal');
      if (modal) return modal;
      modal = document.createElement('div');
      modal.id = 'templateRenameModal';
      modal.className = 'confirm-modal';
      document.body.appendChild(modal);
      modal.addEventListener('click', event => {
        const action = event.target.closest('[data-template-rename-action]')?.dataset.templateRenameAction;
        if (event.target === modal || action === 'cancel') closeTemplateRenameModal();
        if (action === 'submit') submitTemplateRenameModal();
      });
      document.addEventListener('keydown', event => {
        if (!modal.classList.contains('open')) return;
        if (event.key === 'Escape') {
          event.preventDefault();
          closeTemplateRenameModal();
        }
        if (event.key === 'Enter' && event.target?.id === 'templateRenameInput') {
          event.preventDefault();
          submitTemplateRenameModal();
        }
      });
      return modal;
    }

    function openTemplateRenameModal(templateKey) {
      const template = templateById(templateKey);
      if (!template) return;
      templateRenameTarget = template.id;
      const modal = ensureTemplateRenameModal();
      modal.innerHTML = `
        <div class="confirm-dialog poster-edit-dialog" role="dialog" aria-modal="true" aria-label="重命名模板">
          <div class="confirm-title">重命名模板</div>
          <div class="confirm-desc">输入新的模板名称，确认后会同步到促销材料和模板管理。</div>
          <div class="poster-edit-form">
            <div class="poster-edit-field">
              <label for="templateRenameInput">模板名称</label>
              <input id="templateRenameInput" maxlength="16" value="${escapeHtml(templateDisplayName(template))}" />
            </div>
          </div>
          <div class="confirm-actions">
            <button class="modal-btn" type="button" data-template-rename-action="cancel">取消</button>
            <button class="modal-btn primary" type="button" data-template-rename-action="submit">确认</button>
          </div>
        </div>
      `;
      modal.classList.add('open');
      requestAnimationFrame(() => modal.querySelector('#templateRenameInput')?.select());
    }

    function escapeHtml(value) {
      return String(value ?? '').replace(/[&<>"]/g, char => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;'
      }[char]));
    }

    function normalizeSizeLabel(width, height, label = '') {
      const cleanLabel = String(label || '').trim();
      return cleanLabel || `${width} x ${height}`;
    }

    function parsePositiveInt(value) {
      const number = Number(value);
      return Number.isInteger(number) && number > 0 ? number : 0;
    }

    const MATERIAL_SIZE_DISPLAY_ORDER = [
      'ad_120x600',
      'ad_160x600',
      'ad_300x600',
      'ad_320x480',
      'ad_628x1200',
      'ad_828x1200',
      'ad_1200x1500',
      'ad_320x50',
      'ad_720x90',
      'ad_728x90',
      'ad_300x250',
      'ad_320x100',
      'ad_970x250',
      'ad_980x250',
      'ad_990x250',
      'landscape_1200x628',
      'square_800x800',
      'ad_1200x1200'
    ];
    const MATERIAL_SIZE_DISPLAY_RANK = new Map(MATERIAL_SIZE_DISPLAY_ORDER.map((id, index) => [id, index]));
    const MATERIAL_SIZE_CATEGORY_DEFS = [
      {
        id: 'vertical',
        label: '竖版',
        sizeIds: ['ad_120x600', 'ad_160x600', 'ad_300x600', 'ad_320x480', 'ad_628x1200', 'ad_828x1200', 'ad_1200x1500']
      },
      {
        id: 'smallBanner',
        label: '小横版',
        sizeIds: ['ad_320x50', 'ad_720x90', 'ad_728x90']
      },
      {
        id: 'landscape',
        label: '横版',
        sizeIds: ['ad_300x250', 'ad_320x100', 'ad_970x250', 'ad_980x250', 'ad_990x250', 'landscape_1200x628']
      },
      {
        id: 'square',
        label: '方版',
        sizeIds: ['square_800x800', 'ad_1200x1200']
      }
    ];
    const MATERIAL_SIZE_PREVIEW_GROUP_DEFS = [
      {
        id: 'smallVertical',
        label: '小竖版',
        fallbackCategoryId: 'vertical',
        sizeIds: ['ad_120x600', 'ad_160x600']
      },
      {
        id: 'largeVertical',
        label: '大竖版',
        fallbackCategoryId: 'vertical',
        sizeIds: ['ad_300x600', 'ad_320x480', 'ad_628x1200', 'ad_828x1200', 'ad_1200x1500']
      },
      {
        id: 'smallLandscape',
        label: '小横版',
        fallbackCategoryId: 'smallBanner',
        sizeIds: ['ad_320x50', 'ad_720x90', 'ad_728x90']
      },
      {
        id: 'largeLandscape',
        label: '大横版',
        fallbackCategoryId: 'landscape',
        sizeIds: ['ad_300x250', 'ad_320x100', 'ad_970x250', 'ad_980x250', 'ad_990x250', 'landscape_1200x628']
      },
      {
        id: 'square',
        label: '方版',
        fallbackCategoryId: 'square',
        sizeIds: ['square_800x800', 'ad_1200x1200']
      }
    ];
    const MATERIAL_SIZE_CATEGORY_BY_ID = new Map(
      MATERIAL_SIZE_CATEGORY_DEFS.flatMap(category => category.sizeIds.map(id => [id, category.id]))
    );

    function compareMaterialSizeByDesignOrder(a, b) {
      const aRank = MATERIAL_SIZE_DISPLAY_RANK.has(a?.id) ? MATERIAL_SIZE_DISPLAY_RANK.get(a.id) : Number.POSITIVE_INFINITY;
      const bRank = MATERIAL_SIZE_DISPLAY_RANK.has(b?.id) ? MATERIAL_SIZE_DISPLAY_RANK.get(b.id) : Number.POSITIVE_INFINITY;
      return (aRank - bRank)
        || (parsePositiveInt(a?.width) - parsePositiveInt(b?.width))
        || (parsePositiveInt(a?.height) - parsePositiveInt(b?.height))
        || String(a?.label || '').localeCompare(String(b?.label || ''), 'zh-Hans-CN');
    }

    function sortMaterialSizesByDesignOrder(sizes = materialSizes) {
      if (!Array.isArray(sizes)) return sizes;
      sizes.sort(compareMaterialSizeByDesignOrder);
      return sizes;
    }

    function materialSizeCategoryId(size) {
      if (MATERIAL_SIZE_CATEGORY_BY_ID.has(size?.id)) return MATERIAL_SIZE_CATEGORY_BY_ID.get(size.id);
      const width = parsePositiveInt(size?.width);
      const height = parsePositiveInt(size?.height);
      if (!width || !height) return 'landscape';
      const ratio = width / height;
      if (ratio < 0.85) return 'vertical';
      if (ratio <= 1.25) return 'square';
      if (height <= 120) return 'smallBanner';
      return 'landscape';
    }

    function materialSizePreviewGroupIndex(size) {
      const explicitIndex = MATERIAL_SIZE_PREVIEW_GROUP_DEFS.findIndex(group => group.sizeIds.includes(size?.id));
      if (explicitIndex >= 0) return explicitIndex;
      const categoryId = materialSizeCategoryId(size);
      const fallbackIndex = MATERIAL_SIZE_PREVIEW_GROUP_DEFS.findIndex(group => group.fallbackCategoryId === categoryId);
      return fallbackIndex >= 0 ? fallbackIndex : MATERIAL_SIZE_PREVIEW_GROUP_DEFS.length - 1;
    }

    function paddedExportRank(value, fallback = 999999) {
      const number = Number.isFinite(Number(value)) ? Number(value) : fallback;
      return String(Math.max(0, number)).padStart(6, '0');
    }

    function assetExportSortKey(asset = {}) {
      const size = materialSizes[asset.sizeIndex] || materialSizes[0] || {};
      const groupIndex = materialSizePreviewGroupIndex(size);
      const group = MATERIAL_SIZE_PREVIEW_GROUP_DEFS[groupIndex];
      const sizeRankInGroup = group?.sizeIds.indexOf(size.id) ?? -1;
      const displayRank = MATERIAL_SIZE_DISPLAY_RANK.has(size.id) ? MATERIAL_SIZE_DISPLAY_RANK.get(size.id) : Number.POSITIVE_INFINITY;
      return [
        paddedExportRank(asset.languageIndex),
        paddedExportRank(groupIndex),
        paddedExportRank(sizeRankInGroup >= 0 ? sizeRankInGroup : displayRank),
        paddedExportRank(displayRank),
        paddedExportRank(asset.sizeIndex)
      ].join('-');
    }

    function materialSizeExportRank(size, sizeIndex = 0) {
      const groupIndex = materialSizePreviewGroupIndex(size);
      const group = MATERIAL_SIZE_PREVIEW_GROUP_DEFS[groupIndex];
      const sizeRankInGroup = group?.sizeIds.indexOf(size?.id) ?? -1;
      const displayRank = MATERIAL_SIZE_DISPLAY_RANK.has(size?.id) ? MATERIAL_SIZE_DISPLAY_RANK.get(size.id) : Number.POSITIVE_INFINITY;
      return MATERIAL_SIZE_PREVIEW_GROUP_DEFS.slice(0, groupIndex).reduce((sum, item) => sum + item.sizeIds.length, 0)
        + (sizeRankInGroup >= 0 ? sizeRankInGroup : Number.isFinite(displayRank) ? displayRank : sizeIndex)
        + 1;
    }


    function groupedSizePreviewEntries(indices = []) {
      const groups = MATERIAL_SIZE_PREVIEW_GROUP_DEFS.map(group => ({ ...group, entries: [] }));
      const groupBySizeId = new Map(
        groups.flatMap(group => group.sizeIds.map(sizeId => [sizeId, group]))
      );
      const fallbackGroupByCategoryId = new Map(groups.map(group => [group.fallbackCategoryId, group]));
      indices.forEach(index => {
        const size = materialSizes[index];
        if (!size) return;
        const group = groupBySizeId.get(size.id)
          || fallbackGroupByCategoryId.get(materialSizeCategoryId(size))
          || groups[groups.length - 1];
        group.entries.push({ index, size });
      });
      return groups.filter(group => group.entries.length);
    }

    function sizePreviewButtonHtml(index, size, activeIndex) {
      return `<button class="size-thumb ${index === activeIndex ? 'active' : ''}" type="button" data-size-preview-index="${index}" aria-label="预览 ${escapeHtml(size.label)} 尺寸">${escapeHtml(size.label)}</button>`;
    }

    function categorizedSizePreviewHtml(indices, activeIndex) {
      return groupedSizePreviewEntries(indices).map(group => `
        <section class="size-category" aria-label="${escapeHtml(group.label)}尺寸">
          <div class="size-category-title">${escapeHtml(group.label)} ${group.entries.length}</div>
          <div class="size-category-grid">
            ${group.entries.map(({ index, size }) => sizePreviewButtonHtml(index, size, activeIndex)).join('')}
          </div>
        </section>
      `).join('');
    }

    function flatSizePreviewHtml(indices, activeIndex) {
      return indices.map(index => {
        const size = materialSizes[index];
        return size ? sizePreviewButtonHtml(index, size, activeIndex) : '';
      }).join('');
    }

    function categoryPreviewFontPercents(size) {
      const width = Number(size?.width) || 0;
      const height = Number(size?.height) || 0;
      const isLargePortrait = size?.id === 'ad_1200x1500' || (width >= 1000 && height >= 1400 && width < height);
      if (isLargePortrait) {
        return { title: 3.2, subtitle: 2.1, cta: 1.9 };
      }
      const category = materialSizeCategoryId(size);
      const fonts = {
        vertical: { title: 4.3333, subtitle: 2.6667, cta: 2.3333 },
        square: { title: 5.25, subtitle: 4.125, cta: 3.25 },
        smallBanner: { title: 31.1111, subtitle: 0, cta: 14.4444 },
        landscape: { title: 12, subtitle: 8.8, cta: 6.8 }
      };
      return fonts[category] || fonts.landscape;
    }

    function defaultLocalizedCopy() {
      return {
        title: titleInput.value || localizedCopy[0]?.title || 'Headline Text',
        subtitle: subtitleInput.value || localizedCopy[0]?.subtitle || 'More information and key features here.',
        cta: ctaInput.value || localizedCopy[0]?.cta || 'Button'
      };
    }

    function ruleCanvasType(size) {
      return generationRuleForSize(size).type;
    }

    function formatRuleAnchor(anchor) {
      return `${formatPct(anchor.x)} / ${formatPct(anchor.y)} / ${formatPct(anchor.w)} / ${formatPct(anchor.h)}`;
    }

    function moveArrayItem(list, from, to) {
      if (!Array.isArray(list) || from === to || from < 0 || to < 0 || from >= list.length || to >= list.length) return;
      const [item] = list.splice(from, 1);
      list.splice(to, 0, item);
    }

    function uniqueValidIndices(indices, list) {
      return [...new Set(indices)]
        .filter(index => Number.isInteger(index) && list[index]);
    }

    function remapIndexList(indices, mapIndex, list) {
      return uniqueValidIndices((indices || []).map(mapIndex), list);
    }

    function remapPosterCopyOverrides(mapIndex) {
      const next = {};
      Object.entries(posterCopyOverrides).forEach(([key, value]) => {
        const nextIndex = mapIndex(Number(key));
        if (Number.isInteger(nextIndex) && languages[nextIndex]) next[nextIndex] = value;
      });
      Object.keys(posterCopyOverrides).forEach(key => delete posterCopyOverrides[key]);
      Object.assign(posterCopyOverrides, next);
    }

    function syncLanguageCardsWithGenerated(indices = generatedLanguageIndices) {
      const selectedIndices = generated ? indices : languages.map((_, index) => index);
      const selectedSet = new Set(uniqueValidIndices(selectedIndices, languages));
      document.querySelectorAll('.language-card').forEach(card => {
        const index = Number(card.dataset.languageIndex);
        card.classList.toggle('active', selectedSet.has(index));
      });
    }

    function reorderSizeSetting(from, to) {
      if (!Number.isInteger(from) || !Number.isInteger(to) || from === to || !materialSizes[from] || !materialSizes[to]) return;
      const currentSizeId = materialSizes[currentSizeIndex]?.id;
      moveArrayItem(materialSizes, from, to);
      currentSizeIndex = Math.max(0, materialSizes.findIndex(size => size.id === currentSizeId));
      syncSettingsToGenerator('尺寸排序已同步到促销材料');
    }

    function reorderLanguageSetting(from, to) {
      if (!Number.isInteger(from) || !Number.isInteger(to) || from === to || !languages[from] || !languages[to]) return;
      const order = languages.map((_, index) => index);
      moveArrayItem(languages, from, to);
      moveArrayItem(localizedCopy, from, to);
      moveArrayItem(order, from, to);
      const indexMap = new Map(order.map((oldIndex, newIndex) => [oldIndex, newIndex]));
      const mapIndex = index => indexMap.has(index) ? indexMap.get(index) : -1;
      currentLanguageIndex = Math.max(0, mapIndex(currentLanguageIndex));
      generatedLanguageIndices = remapIndexList(generatedLanguageIndices, mapIndex, languages);
      remapPosterCopyOverrides(mapIndex);
      syncSettingsToGenerator('语言排序已同步到促销材料', { languageIndices: generatedLanguageIndices });
    }

    function renderGenerationRules() {
      if (rulesDesc) {
        rulesDesc.textContent = `上传生成规则文档后，系统会解析 MD、Word、PDF、XLSX 中的结构化规则并用于促销材料。当前已解析 ${parsedRulesCount()} 条规则。`;
      }
      updateRulesDocumentState();
    }

    function formatFileSize(bytes = 0) {
      if (bytes >= 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
      if (bytes >= 1024) return `${Math.round(bytes / 1024)} KB`;
      return `${bytes} B`;
    }

    const rulesParser = window.createRulesParser({ normalizeHexColor, parsePositiveInt });
    const rulesFileKind = rulesParser.rulesFileKind;
    const parseGenerationRulesFile = rulesParser.parseGenerationRulesFile;
    const isAllowedRulesFile = rulesParser.isAllowedRulesFile;

    function refreshSpreadsheetGenerationRules() {
      spreadsheetGenerationRules = rulesDocuments.flatMap(doc => doc.spreadsheetRules || []);
    }

    function parsedRulesCount() {
      return rulesDocuments.reduce((total, doc) => total + (doc.spreadsheetRules?.length || 0), 0);
    }

    function openLegacyRulesDocumentDb() {
      return new Promise((resolve, reject) => {
        if (!window.indexedDB) {
          reject(new Error('IndexedDB is not available'));
          return;
        }
        const request = indexedDB.open(LEGACY_RULES_DOCUMENT_DB, 1);
        request.onupgradeneeded = () => {
          const db = request.result;
          if (!db.objectStoreNames.contains(LEGACY_RULES_DOCUMENT_STORE)) {
            db.createObjectStore(LEGACY_RULES_DOCUMENT_STORE, { keyPath: 'id' });
          }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error || new Error('Failed to open legacy rules database'));
        request.onblocked = () => reject(new Error('Legacy rules database upgrade was blocked'));
      });
    }

    function rulesDocumentTransaction(mode, handler) {
      return appDatabaseTransaction(RULES_DOCUMENT_STORE, mode, handler);
    }

    function legacyRulesDocumentTransaction(mode, handler) {
      return openLegacyRulesDocumentDb().then(db => new Promise((resolve, reject) => {
        const transaction = db.transaction(LEGACY_RULES_DOCUMENT_STORE, mode);
        const store = transaction.objectStore(LEGACY_RULES_DOCUMENT_STORE);
        let result;
        transaction.oncomplete = () => {
          db.close();
          resolve(result);
        };
        transaction.onerror = () => {
          db.close();
          reject(transaction.error || new Error('Rules document transaction failed'));
        };
        transaction.onabort = () => {
          db.close();
          reject(transaction.error || new Error('Rules document transaction aborted'));
        };
        try {
          result = handler(store);
        } catch (error) {
          transaction.abort();
          db.close();
          reject(error);
        }
      }));
    }

    function rulesDbRequest(request) {
      return dbRequest(request, 'Rules document request failed');
    }

    function arrayBufferToBase64(buffer) {
      const bytes = new Uint8Array(buffer);
      let binary = '';
      const chunkSize = 0x8000;
      for (let index = 0; index < bytes.length; index += chunkSize) {
        binary += String.fromCharCode(...bytes.subarray(index, index + chunkSize));
      }
      return btoa(binary);
    }

    function base64ToBlob(dataBase64, type = '') {
      const binary = atob(String(dataBase64 || ''));
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
      return new Blob([bytes], { type });
    }

    async function rulesDocumentToServerRecord(doc, order) {
      return {
        id: doc.id,
        name: doc.file.name,
        type: doc.file.type,
        size: doc.file.size,
        lastModified: doc.file.lastModified || Date.now(),
        text: doc.text || '',
        order,
        dataBase64: arrayBufferToBase64(await doc.file.arrayBuffer())
      };
    }

    async function saveRulesDocumentsToServerDb() {
      const documents = await Promise.all(rulesDocuments.map((doc, order) => rulesDocumentToServerRecord(doc, order)));
      await serverDatabaseRequest('/rules-documents', {
        method: 'PUT',
        body: { documents }
      });
    }

    async function saveRulesDocumentsToDb() {
      await rulesDocumentTransaction('readwrite', store => {
        store.clear();
        rulesDocuments.forEach((doc, order) => {
          store.put({
            id: doc.id,
            name: doc.file.name,
            type: doc.file.type,
            size: doc.file.size,
            lastModified: doc.file.lastModified || Date.now(),
            blob: doc.file,
            text: doc.text || '',
            order
          });
        });
      });
    }

    async function persistRulesDocuments() {
      let saved = false;
      try {
        await saveRulesDocumentsToDb();
        saved = true;
      } catch (error) {
        console.warn('Failed to persist rules documents', error);
      }
      try {
        await saveRulesDocumentsToServerDb();
        saved = true;
      } catch (serverError) {
        console.warn('Server rules database unavailable, saved locally instead', serverError);
      }
      if (!saved) showToast('生成规则保存失败，请检查服务器或浏览器存储权限');
      return saved;
    }

    async function buildRulesDocumentsFromRecords(records) {
      return Promise.all((records || [])
        .sort((a, b) => (a.order || 0) - (b.order || 0))
        .map(async record => {
          const blob = record.blob || base64ToBlob(record.dataBase64 || '', record.type || '');
          const file = new File([blob], record.name || '生成规则文档', {
            type: record.type || blob.type || '',
            lastModified: record.lastModified || Date.now()
          });
          const doc = {
            id: record.id || `rules-${Date.now()}-${Math.random().toString(16).slice(2)}`,
            file,
            url: URL.createObjectURL(file),
            text: record.text || '',
            spreadsheetRules: []
          };
          const parsed = await parseGenerationRulesFile(file, doc.text);
          doc.text = parsed.text;
          doc.spreadsheetRules = parsed.rules;
          return doc;
        }));
    }

    async function loadRulesDocumentsFromDb() {
      const records = await rulesDocumentTransaction('readonly', store => rulesDbRequest(store.getAll()));
      return buildRulesDocumentsFromRecords(records);
    }

    async function loadRulesDocumentsFromServerDb() {
      const payload = await serverDatabaseRequest('/rules-documents');
      return buildRulesDocumentsFromRecords(payload?.documents || []);
    }

    async function loadLegacyRulesDocumentsFromDb() {
      const records = await legacyRulesDocumentTransaction('readonly', store => rulesDbRequest(store.getAll()));
      return buildRulesDocumentsFromRecords(records);
    }

    async function restoreRulesDocuments() {
      try {
        let restoredFromServer = false;
        let restoredDocuments = [];
        try {
          restoredDocuments = await loadRulesDocumentsFromServerDb();
          restoredFromServer = restoredDocuments.length > 0;
        } catch (serverError) {
          console.warn('Server rules database unavailable, restoring from local storage', serverError);
        }
        if (!restoredDocuments.length) {
          restoredDocuments = await loadRulesDocumentsFromDb();
        }
        if (!restoredDocuments.length) {
          restoredDocuments = await loadLegacyRulesDocumentsFromDb();
          if (restoredDocuments.length) {
            const currentDocuments = rulesDocuments;
            rulesDocuments = restoredDocuments;
            await persistRulesDocuments();
            rulesDocuments = currentDocuments;
          }
        }
        if (!restoredDocuments.length) return;
        rulesDocuments.forEach(doc => URL.revokeObjectURL(doc.url));
        rulesDocuments = restoredDocuments;
        refreshSpreadsheetGenerationRules();
        syncSpreadsheetRulesToOptions();
        renderSelectors();
        updateRulesDocumentState();
        if (restoredFromServer) await saveRulesDocumentsToDb();
        else await persistRulesDocuments();
      } catch (error) {
        console.warn('Failed to restore rules documents', error);
      }
    }

    function markdownToPreviewHtml(text) {
      const lines = String(text || '').split(/\r?\n/);
      let inList = false;
      let inCode = false;
      const output = [];
      const closeList = () => {
        if (inList) {
          output.push('</ul>');
          inList = false;
        }
      };
      lines.forEach(line => {
        if (/^```/.test(line.trim())) {
          closeList();
          if (inCode) output.push('</pre>');
          else output.push('<pre>');
          inCode = !inCode;
          return;
        }
        if (inCode) {
          output.push(`${escapeHtml(line)}\n`);
          return;
        }
        const heading = line.match(/^(#{1,3})\s+(.+)$/);
        if (heading) {
          closeList();
          const level = heading[1].length;
          output.push(`<h${level}>${escapeHtml(heading[2])}</h${level}>`);
          return;
        }
        const item = line.match(/^[-*]\s+(.+)$/);
        if (item) {
          if (!inList) {
            output.push('<ul>');
            inList = true;
          }
          output.push(`<li>${escapeHtml(item[1])}</li>`);
          return;
        }
        closeList();
        if (line.trim()) output.push(`<p>${escapeHtml(line)}</p>`);
      });
      closeList();
      if (inCode) output.push('</pre>');
      return output.join('');
    }

    function renderRulesDocumentList() {
      if (!rulesDocList) return;
      if (!rulesDocuments.length) {
        rulesDocList.innerHTML = '<div class="rules-doc-empty">未上传生成规则文档。支持 Markdown、Word、PDF、XLSX 等文件。</div>';
        return;
      }
      rulesDocList.innerHTML = rulesDocuments.map((doc, index) => `
        <div class="rules-doc-row" data-rules-index="${index}">
          <div class="rules-doc-main">
            <strong>${escapeHtml(doc.file.name)}</strong>
            <span>${formatFileSize(doc.file.size)} · ${rulesFileKind(doc).toUpperCase()} · 已解析 ${doc.spreadsheetRules?.length || 0} 条规则 · ${index + 1} / ${rulesDocuments.length}</span>
          </div>
          <div class="rules-doc-actions">
            <button class="settings-action primary" type="button" data-rules-action="preview">预览</button>
            <button class="settings-action" type="button" data-rules-action="reupload">重新上传</button>
            <button class="settings-action danger" type="button" data-rules-action="delete">删除</button>
          </div>
        </div>
      `).join('');
    }

    function updateRulesDocumentState() {
      if (rulesDocStatus) rulesDocStatus.textContent = rulesDocuments.length ? `${rulesDocuments.length} 个文档 · ${parsedRulesCount()} 条规则` : '未上传';
      renderRulesDocumentList();
    }

    async function createRulesDocument(file) {
      const doc = {
        id: `rules-${Date.now()}-${Math.random().toString(16).slice(2)}`,
        file,
        url: URL.createObjectURL(file),
        text: '',
        spreadsheetRules: []
      };
      const parsed = await parseGenerationRulesFile(file);
      doc.text = parsed.text;
      doc.spreadsheetRules = parsed.rules;
      return doc;
    }

    async function setRulesDocuments(fileList, replaceIndex = null) {
      const incoming = [...(fileList || [])].filter(Boolean);
      const files = incoming.filter(isAllowedRulesFile);
      if (!files.length) {
        if (incoming.length) showToast('生成规则仅支持 MD、Word、PDF、XLSX 文件');
        return;
      }
      if (files.length < incoming.length) showToast('已忽略不支持的文件格式');
      const nextDocs = [];
      for (const file of files) nextDocs.push(await createRulesDocument(file));
      let successMessage = '';
      if (Number.isInteger(replaceIndex) && rulesDocuments[replaceIndex]) {
        URL.revokeObjectURL(rulesDocuments[replaceIndex].url);
        rulesDocuments.splice(replaceIndex, 1, nextDocs[0]);
        if (nextDocs.length > 1) rulesDocuments.splice(replaceIndex + 1, 0, ...nextDocs.slice(1));
        successMessage = '生成规则文档已重新上传';
      } else {
        rulesDocuments.push(...nextDocs);
        successMessage = `已上传 ${nextDocs.length} 个生成规则文档`;
      }
      if (rulesFileInput) rulesFileInput.value = '';
      rulesReplaceIndex = null;
      refreshSpreadsheetGenerationRules();
      syncSpreadsheetRulesToOptions();
      renderSelectors();
      updateRulesDocumentState();
      if (await persistRulesDocuments()) showToast(successMessage);
    }

    async function deleteRulesDocument(index) {
      const doc = rulesDocuments[index];
      if (!doc) return;
      URL.revokeObjectURL(doc.url);
      rulesDocuments.splice(index, 1);
      if (rulesPreviewIndex >= rulesDocuments.length) rulesPreviewIndex = Math.max(0, rulesDocuments.length - 1);
      refreshSpreadsheetGenerationRules();
      syncSpreadsheetRulesToOptions();
      renderSelectors();
      updateRulesDocumentState();
      if (await persistRulesDocuments()) showToast('生成规则文档已删除');
    }

    function rulesPreviewContent(doc) {
      const kind = rulesFileKind(doc);
      const name = escapeHtml(doc.file.name);
      const parsedMeta = `<span>已解析 ${doc.spreadsheetRules?.length || 0} 条生成规则；生成和下载将优先按规则产出。</span>`;
      if (kind === 'pdf') return doc.text
        ? `<div class="rules-preview-text">${markdownToPreviewHtml(doc.text)}</div><div class="rules-preview-file"><strong>${name}</strong>${parsedMeta}</div>`
        : `<object data="${doc.url}" type="application/pdf"><div class="rules-preview-file"><strong>${name}</strong><span>当前 PDF 未抽取到可解析文本，可用系统查看。</span>${parsedMeta}</div></object>`;
      if (kind === 'text') return `<div class="rules-preview-text">${markdownToPreviewHtml(doc.text)}</div><div class="rules-preview-file"><strong>${name}</strong>${parsedMeta}</div>`;
      if (kind === 'word') return doc.text
        ? `<div class="rules-preview-text">${markdownToPreviewHtml(doc.text)}</div><div class="rules-preview-file"><strong>${name}</strong>${parsedMeta}</div>`
        : `<div class="rules-preview-file"><strong>${name}</strong><span>Word 文档已上传，但当前浏览器未抽取到可解析文本。</span>${parsedMeta}</div>`;
      if (kind === 'spreadsheet') return `<div class="rules-preview-file"><strong>${name}</strong><span>XLSX 表格已上传，已解析 ${doc.spreadsheetRules?.length || 0} 条生成规则；生成和下载将优先按规则产出。</span></div>`;
      return `<div class="rules-preview-file"><strong>${name}</strong><span>文件已上传，当前格式不支持内嵌预览。</span></div>`;
    }

    function ensureRulesPreviewModal() {
      let modal = document.getElementById('rulesPreviewModal');
      if (modal) return modal;
      modal = document.createElement('div');
      modal.id = 'rulesPreviewModal';
      modal.className = 'rules-preview-modal';
      modal.innerHTML = `
        <div class="rules-preview-dialog" role="dialog" aria-modal="true" aria-label="预览生成规则文档">
          <div class="rules-preview-header">
            <div class="rules-preview-title"><strong id="rulesPreviewModalTitle">预览</strong><span id="rulesPreviewModalMeta"></span></div>
            <div class="rules-preview-actions">
              <button class="icon-button" type="button" data-rules-modal-action="prev" aria-label="上一个">&lt;</button>
              <button class="icon-button" type="button" data-rules-modal-action="next" aria-label="下一个">&gt;</button>
              <button class="modal-btn" type="button" data-rules-modal-action="close">关闭</button>
            </div>
          </div>
          <div class="rules-preview-body" id="rulesPreviewModalBody"></div>
        </div>
      `;
      document.body.appendChild(modal);
      modal.addEventListener('click', event => {
        const action = event.target.closest('[data-rules-modal-action]')?.dataset.rulesModalAction;
        if (event.target === modal || action === 'close') closeRulesPreviewModal();
        if (action === 'prev') renderRulesPreview(rulesPreviewIndex - 1);
        if (action === 'next') renderRulesPreview(rulesPreviewIndex + 1);
      });
      document.addEventListener('keydown', event => {
        if (!modal.classList.contains('open')) return;
        if (event.key === 'Escape') closeRulesPreviewModal();
        if (event.key === 'ArrowLeft') renderRulesPreview(rulesPreviewIndex - 1);
        if (event.key === 'ArrowRight') renderRulesPreview(rulesPreviewIndex + 1);
      });
      return modal;
    }

    function renderRulesPreview(index = rulesPreviewIndex) {
      if (!rulesDocuments.length) {
        showToast('请先上传生成规则文档');
        return;
      }
      rulesPreviewIndex = (index + rulesDocuments.length) % rulesDocuments.length;
      const doc = rulesDocuments[rulesPreviewIndex];
      const modal = ensureRulesPreviewModal();
      modal.querySelector('#rulesPreviewModalTitle').textContent = doc.file.name;
      modal.querySelector('#rulesPreviewModalMeta').textContent = `${rulesPreviewIndex + 1} / ${rulesDocuments.length} · ${formatFileSize(doc.file.size)} · ${rulesFileKind(doc).toUpperCase()}`;
      modal.querySelector('#rulesPreviewModalBody').innerHTML = rulesPreviewContent(doc);
      modal.classList.add('open');
    }

    function closeRulesPreviewModal() {
      document.getElementById('rulesPreviewModal')?.classList.remove('open');
    }

    function initRulesDocumentUpload() {
      if (!rulesFileInput || !rulesUploadCard) return;
      rulesUploadCard.addEventListener('click', () => {
        rulesReplaceIndex = null;
        rulesFileInput.multiple = true;
        rulesFileInput.click();
      });
      rulesFileInput.addEventListener('change', () => setRulesDocuments(rulesFileInput.files, rulesReplaceIndex));
      rulesDocList?.addEventListener('click', event => {
        const row = event.target.closest('[data-rules-index]');
        const action = event.target.closest('[data-rules-action]')?.dataset.rulesAction;
        if (!row || !action) return;
        const index = Number(row.dataset.rulesIndex);
        if (action === 'preview') renderRulesPreview(index);
        if (action === 'delete') deleteRulesDocument(index);
        if (action === 'reupload') {
          rulesReplaceIndex = index;
          rulesFileInput.multiple = false;
          rulesFileInput.click();
        }
      });
      ['dragenter', 'dragover'].forEach(type => {
        rulesUploadCard.addEventListener(type, event => {
          event.preventDefault();
          rulesUploadCard.classList.add('is-dragover');
        });
      });
      ['dragleave', 'drop'].forEach(type => {
        rulesUploadCard.addEventListener(type, event => {
          event.preventDefault();
          rulesUploadCard.classList.remove('is-dragover');
        });
      });
      rulesUploadCard.addEventListener('drop', event => setRulesDocuments(event.dataTransfer?.files));
    }

    function renderSizeLanguageSettings() {
      normalizeSizeLanguageState();
      if (sizeSettingsCount) sizeSettingsCount.textContent = `${materialSizes.length} 个`;
      if (languageSettingsCount) languageSettingsCount.textContent = `${languages.length} 种`;
      if (sizeSettingsBody) {
        sizeSettingsBody.innerHTML = materialSizes.map((size, index) => `
          <tr data-size-setting-index="${index}" data-settings-row="size">
            <td class="drag-cell"><button class="drag-handle" type="button" draggable="true" data-drag-type="size" data-drag-index="${index}" aria-label="拖拽排序 ${escapeHtml(size.label)}">☰</button></td>
            <td><input class="settings-input" data-size-field="label" value="${escapeHtml(size.label)}"></td>
            <td><input class="settings-input" data-size-field="width" type="number" min="1" value="${size.width}"></td>
            <td><input class="settings-input" data-size-field="height" type="number" min="1" value="${size.height}"></td>
            <td><div class="settings-actions"><button class="settings-action" type="button" data-size-setting-action="save">保存</button><button class="settings-action danger" type="button" data-size-setting-action="delete">删除</button></div></td>
          </tr>
        `).join('');
      }
      if (languageSettingsBody) {
        languageSettingsBody.innerHTML = languages.map(([cn, en], index) => `
          <tr data-language-setting-index="${index}" data-settings-row="language">
            <td class="drag-cell"><button class="drag-handle" type="button" draggable="true" data-drag-type="language" data-drag-index="${index}" aria-label="拖拽排序 ${escapeHtml(cn)}">☰</button></td>
            <td><input class="settings-input" data-language-field="cn" value="${escapeHtml(cn)}"></td>
            <td><input class="settings-input" data-language-field="en" value="${escapeHtml(en)}"></td>
            <td><div class="settings-actions"><button class="settings-action" type="button" data-language-setting-action="save">保存</button><button class="settings-action danger" type="button" data-language-setting-action="delete">删除</button></div></td>
          </tr>
        `).join('');
      }
    }

    function syncSettingsToGenerator(message = '设置已同步到促销材料', options = {}) {
      normalizeSizeLanguageState();
      currentSizeIndex = Math.min(currentSizeIndex, Math.max(0, materialSizes.length - 1));
      frameworkSizeIndex = Math.min(frameworkSizeIndex, Math.max(0, materialSizes.length - 1));
      currentLanguageIndex = Math.min(currentLanguageIndex, Math.max(0, languages.length - 1));
      alignUngeneratedPreviewWithTemplateManager();
      generatedSizeIndices = generated && materialSizes.length ? materialSizes.map((_, index) => index) : (materialSizes.length ? [currentSizeIndex] : []);
      const preferredLanguageIndices = Array.isArray(options.languageIndices) ? options.languageIndices : generatedLanguageIndices;
      generatedLanguageIndices = generated && languages.length
        ? (uniqueValidIndices(preferredLanguageIndices, languages).length ? uniqueValidIndices(preferredLanguageIndices, languages) : [currentLanguageIndex])
        : (languages.length ? [currentLanguageIndex] : []);
      if (generatedLanguageIndices.length && !generatedLanguageIndices.includes(currentLanguageIndex)) {
        currentLanguageIndex = generatedLanguageIndices[0];
      }
      generatedAssets = generatedSizeIndices.flatMap(sizeIndex =>
        generatedLanguageIndices.map(languageIndex => ({
          sizeIndex,
          languageIndex,
          fileName: buildAssetFileName(sizeIndex, languageIndex)
        }))
      );
      saveSizeLanguageState();
      renderSelectors();
      syncLanguageCardsWithGenerated(generatedLanguageIndices);
      renderLanguagePreview(generatedLanguageIndices);
      applySizePreview(currentSizeIndex);
      applyLanguagePreview(currentLanguageIndex);
      refreshOpenPosterEditModal(generatedLanguageIndices);
      updateGeneratedMeta();
      updateUploadState();
      clearPosterEditHistory();
      showToast(message);
    }

    function addSizeSetting() {
      const labelInput = document.getElementById('newSizeLabel');
      const widthInput = document.getElementById('newSizeWidth');
      const heightInput = document.getElementById('newSizeHeight');
      const width = parsePositiveInt(widthInput?.value);
      const height = parsePositiveInt(heightInput?.value);
      if (!width || !height) {
        showToast('请输入有效的尺寸宽高');
        return false;
      }
      const label = normalizeSizeLabel(width, height, labelInput?.value);
      materialSizes.push({ id: `custom_${width}x${height}_${Date.now()}`, label, width, height });
      if (labelInput) labelInput.value = '';
      if (widthInput) widthInput.value = '';
      if (heightInput) heightInput.value = '';
      syncSettingsToGenerator('尺寸已新增并同步到促销材料');
      return true;
    }

    function saveSizeSetting(row) {
      const index = Number(row?.dataset.sizeSettingIndex);
      if (!Number.isInteger(index) || !materialSizes[index]) return;
      const width = parsePositiveInt(row.querySelector('[data-size-field="width"]')?.value);
      const height = parsePositiveInt(row.querySelector('[data-size-field="height"]')?.value);
      if (!width || !height) {
        showToast('请输入有效的尺寸宽高');
        return;
      }
      materialSizes[index] = { ...materialSizes[index], label: normalizeSizeLabel(width, height, row.querySelector('[data-size-field="label"]')?.value), width, height };
      syncSettingsToGenerator('尺寸已更新并同步到促销材料');
    }

    function deleteSizeSetting(row) {
      const index = Number(row?.dataset.sizeSettingIndex);
      if (!Number.isInteger(index) || !materialSizes[index]) return;
      if (materialSizes.length <= 1) {
        showToast('至少保留一个尺寸');
        return;
      }
      materialSizes.splice(index, 1);
      syncSettingsToGenerator('尺寸已删除并同步到促销材料');
    }

    function addLanguageSetting() {
      const cnInput = document.getElementById('newLanguageCn');
      const nativeInput = document.getElementById('newLanguageNative');
      const cn = String(cnInput?.value || '').trim();
      const en = String(nativeInput?.value || '').trim();
      if (!cn || !en) {
        showToast('请输入语言名称');
        return false;
      }
      const nextIndex = languages.length;
      languages.push([cn, en]);
      localizedCopy.push(defaultLocalizedCopy());
      generatedLanguageIndices = uniqueValidIndices([...generatedLanguageIndices, nextIndex], languages);
      if (cnInput) cnInput.value = '';
      if (nativeInput) nativeInput.value = '';
      syncSettingsToGenerator('语言已新增并同步到促销材料', { languageIndices: generatedLanguageIndices });
      return true;
    }

    function saveLanguageSetting(row) {
      const index = Number(row?.dataset.languageSettingIndex);
      if (!Number.isInteger(index) || !languages[index]) return;
      const cn = String(row.querySelector('[data-language-field="cn"]')?.value || '').trim();
      const en = String(row.querySelector('[data-language-field="en"]')?.value || '').trim();
      if (!cn || !en) {
        showToast('请输入语言名称');
        return;
      }
      languages[index] = [cn, en];
      syncSettingsToGenerator('语言已更新并同步到促销材料', { languageIndices: generatedLanguageIndices });
    }

    function deleteLanguageSetting(row) {
      const index = Number(row?.dataset.languageSettingIndex);
      if (!Number.isInteger(index) || !languages[index]) return;
      if (languages.length <= 1) {
        showToast('至少保留一种语言');
        return;
      }
      languages.splice(index, 1);
      localizedCopy.splice(index, 1);
      const mapIndex = oldIndex => {
        if (oldIndex === index) return -1;
        return oldIndex > index ? oldIndex - 1 : oldIndex;
      };
      currentLanguageIndex = Math.max(0, mapIndex(currentLanguageIndex));
      generatedLanguageIndices = remapIndexList(generatedLanguageIndices, mapIndex, languages);
      remapPosterCopyOverrides(mapIndex);
      syncSettingsToGenerator('语言已删除并同步到促销材料', { languageIndices: generatedLanguageIndices });
    }

    function getSourceCopy() {
      return {
        title: titleInput.value.trim() || localizedCopy[0]?.title || 'Headline Text',
        subtitle: subtitleInput.value.trim() || localizedCopy[0]?.subtitle || 'More information and key features here.',
        cta: ctaInput.value.trim() || localizedCopy[0]?.cta || 'Button'
      };
    }

    function getLanguageCopy(languageIndex) {
      const copy = posterCopyOverrides[languageIndex]
        || (languageIndex === 0 ? getSourceCopy() : localizedCopy[languageIndex] || getSourceCopy());
      return normalizeCopy(copy, languageIndex);
    }

    function renderMultilineText(element, text) {
      element.textContent = normalizeCopyText(text);
    }

    let inlineCopyEditor = null;

    function closeInlineCopyEditor() {
      inlineCopyEditor?.remove();
      inlineCopyEditor = null;
    }

    function syncInlineTextareaSize(textarea) {
      if (!textarea) return;
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(42, textarea.scrollHeight)}px`;
    }

    function anchorFontPx(scope, key, anchor) {
      const host = scope === 'template' ? anchorCanvas : materialCard;
      const fallback = scope === 'template'
        ? (key === 'title' ? anchorPreviewTitle : (key === 'subtitle' ? anchorPreviewSubtitle : anchorPreviewCta))
        : (key === 'title' ? previewTitle : (key === 'subtitle' ? previewSubtitle : previewCta));
      const computed = fallback ? Number.parseFloat(window.getComputedStyle(fallback).fontSize) : 16;
      const fontPx = Number(anchor?.fontPx);
      const fontScale = Number(anchor?.fontScale);
      if (Number.isFinite(fontPx) && fontPx > 0) {
        return Math.round(fontPx * (Number.isFinite(fontScale) && fontScale > 0 ? fontScale : 1));
      }
      return Math.round(Number(anchor?.font) ? (host.clientHeight || 628) * Number(anchor.font) / 100 : computed || 16);
    }

    function syncFontSizeToolbar(box, scope, key, anchor) {
      const value = box?.querySelector('[data-font-size-value]');
      if (!value || !['title', 'subtitle', 'cta'].includes(key)) return;
      value.textContent = String(anchorFontPx(scope, key, anchor));
    }

    function fontSizeToolbarHtml(key) {
      const label = key === 'title' ? '标题' : (key === 'subtitle' ? '副标题' : '按钮');
      return `
        <div class="font-size-toolbar" aria-label="调整${label}字号">
          <span class="font-size-current" data-font-size-value>--</span>
          <button class="font-size-step" type="button" data-font-size-action="increase" aria-label="增大${label}字号">+</button>
          <button class="font-size-step" type="button" data-font-size-action="decrease" aria-label="减小${label}字号">-</button>
        </div>
      `;
    }

    function adjustCopyFontFromToolbar(button) {
      const box = button.closest('.edit-select-box');
      const inlineEditor = button.closest('.inline-copy-editor');
      const scope = inlineEditor?.dataset.inlineCopyEditor || (box?.classList.contains('anchor-box') ? 'template' : 'poster');
      const key = inlineEditor?.dataset.inlineCopyKey || box?.dataset.anchor || box?.dataset.posterAnchor;
      if (scope === 'poster') return;
      if (!['template', 'poster'].includes(scope) || !['title', 'subtitle', 'cta'].includes(key)) return;
      const anchors = scope === 'template' ? anchorEditorPreviewAnchors() : effectivePosterAnchorsForSize();
      const currentPx = anchorFontPx(scope, key, anchors[key]);
      const delta = button.dataset.fontSizeAction === 'decrease' ? -1 : 1;
      setCopyFontForInlineEditor(scope, key, clamp(currentPx + delta, 6, 180));
    }

    function setCopyTextForInlineEditor(scope, key, value) {
      const cleanValue = String(value || '');
      if (scope === 'template') {
        if (key === 'title') {
          titleInput.value = cleanValue;
          anchorPreviewTitle.textContent = cleanValue || 'Headline Text';
        } else if (key === 'subtitle') {
          subtitleInput.value = cleanValue;
          renderMultilineText(anchorPreviewSubtitle, cleanValue || 'More information and key features here.');
        } else if (key === 'cta') {
          ctaInput.value = cleanValue;
          anchorPreviewCta.textContent = cleanValue || 'Button';
        }
        localizedCopy[0] = { ...(localizedCopy[0] || defaultLocalizedCopy()), [key]: cleanValue };
        updateCounters();
        schedulePosterTextFit();
        return;
      }
      const asset = currentPreviewAsset();
      const targetLanguageIndex = Number.isInteger(asset?.languageIndex) ? asset.languageIndex : currentLanguageIndex;
      const nextCopy = {
        ...copyForAsset(asset),
        [key]: cleanValue
      };
      posterCopyOverrides[targetLanguageIndex] = nextCopy;
      if (targetLanguageIndex === 0) {
        titleInput.value = nextCopy.title;
        subtitleInput.value = nextCopy.subtitle;
        ctaInput.value = nextCopy.cta;
        updateCounters();
      }
      if (key === 'title') previewTitle.textContent = cleanValue;
      else if (key === 'subtitle') renderMultilineText(previewSubtitle, cleanValue);
      else if (key === 'cta') previewCta.textContent = cleanValue;
      schedulePosterTextFit();
    }

    function setCopyFontForInlineEditor(scope, key, pxValue) {
      const host = scope === 'template' ? anchorCanvas : materialCard;
      const hostHeight = Math.max(1, host.clientHeight || 628);
      if (scope === 'template') {
        const anchors = anchorEditorPreviewAnchors();
        const fontPx = Number(anchors[key]?.fontPx);
        const nextAnchor = Number.isFinite(fontPx) && fontPx > 0
          ? { ...anchors[key], fontScale: clamp((Number(pxValue) || fontPx) / fontPx, 0.05, 8) }
          : { ...anchors[key], font: clamp((Number(pxValue) || 1) / hostHeight * 100, 0.6, 40) };
        updateAnchor(key, nextAnchor);
      } else {
        pushPosterEditHistory();
        const anchors = effectivePosterAnchorsForSize();
        const fontPx = Number(anchors[key]?.fontPx);
        const nextAnchor = Number.isFinite(fontPx) && fontPx > 0
          ? { ...anchors[key], fontScale: clamp((Number(pxValue) || fontPx) / fontPx, 0.05, 8) }
          : { ...anchors[key], font: clamp((Number(pxValue) || 1) / hostHeight * 100, 0.6, 40) };
        setPosterOverride(key, nextAnchor);
      }
      if (inlineCopyEditor?.dataset.inlineCopyEditor === scope && inlineCopyEditor.dataset.inlineCopyKey === key) {
        const nextAnchors = scope === 'template' ? anchorEditorPreviewAnchors() : effectivePosterAnchorsForSize();
        syncFontSizeToolbar(inlineCopyEditor, scope, key, nextAnchors[key]);
      }
    }

    function openInlineCopyEditor(scope, key) {
      if (!INLINE_COPY_EDITOR_ENABLED) return;
      if (!['title', 'subtitle', 'cta'].includes(key)) return;
      const host = scope === 'template' ? anchorCanvas : materialCard;
      const anchors = scope === 'template' ? anchorEditorPreviewAnchors() : effectivePosterAnchorsForSize();
      const anchor = anchors[key];
      if (!host || !anchor) return;
      closeInlineCopyEditor();
      const editor = document.createElement('div');
      editor.className = 'inline-copy-editor';
      editor.dataset.inlineCopyEditor = scope;
      editor.dataset.inlineCopyKey = key;
      editor.style.left = formatPct(anchor.x);
      editor.style.top = formatPct(anchor.y);
      editor.style.width = formatPct(anchor.w);
      editor.style.height = formatPct(anchor.h);
      const canEditFontSize = scope === 'template' && key === 'cta';
      const editorHint = canEditFontSize ? '拖动边框调整折行，+ / - 调整字号' : '拖动边框调整折行';
      editor.innerHTML = `${canEditFontSize ? fontSizeToolbarHtml(key) : ''}<textarea maxlength="${COPY_LIMITS[key] || COPY_LIMITS.subtitle}"></textarea><label>${editorHint}</label>`;
      const textarea = editor.querySelector('textarea');
      const source = scope === 'template' ? getSourceCopy() : copyForAsset(currentPreviewAsset());
      textarea.value = source[key] || '';
      host.appendChild(editor);
      inlineCopyEditor = editor;
      syncFontSizeToolbar(editor, scope, key, anchor);
      textarea.addEventListener('input', () => {
        syncInlineTextareaSize(textarea);
        setCopyTextForInlineEditor(scope, key, textarea.value);
      });
      editor.addEventListener('pointerdown', event => event.stopPropagation());
      requestAnimationFrame(() => {
        syncInlineTextareaSize(textarea);
        textarea.focus();
        textarea.select();
      });
    }

    function applyLanguagePreview(languageIndex) {
      currentLanguageIndex = languageIndex;
      const asset = currentPreviewAsset(currentSizeIndex, languageIndex);
      const copy = copyForAsset(asset);
      applyRuleVisualStyles(asset);
      previewTitle.textContent = copy.title;
      renderMultilineText(previewSubtitle, copy.subtitle);
      previewCta.textContent = copy.cta;
      applyPosterLayoutForSize(currentSizeIndex);
      applySelectedLogo(logoBrandForLanguage(languageIndex), asset?.rule?.logoVariant || templateStyles.logoVariant || selectedLogoVariant);
      document.querySelectorAll('.language-pill').forEach(pill => {
        pill.classList.toggle('active', Number(pill.dataset.languagePreviewIndex) === languageIndex);
      });
    }

    function selectedSizeIndices() {
      return [...document.querySelectorAll('#sizeChecks input:checked')]
        .map(input => Number(input.dataset.sizeIndex))
        .filter(index => Number.isInteger(index) && materialSizes[index]);
    }

    function selectedLanguageIndices() {
      return [...document.querySelectorAll('.language-card.active')]
        .map(card => Number(card.dataset.languageIndex))
        .filter(index => Number.isInteger(index) && languages[index]);
    }

    function renderSizePreview(indices = generatedSizeIndices) {
      sizePreviewRow.classList.add('size-category-list');
      sizePreviewRow.innerHTML = categorizedSizePreviewHtml(indices, currentSizeIndex);
      if (bottomSizePreviewRow) {
        bottomSizePreviewRow.classList.remove('size-category-list');
        bottomSizePreviewRow.innerHTML = flatSizePreviewHtml(indices, currentSizeIndex);
      }
      syncResultCollapseState();
    }

    function renderFrameworkSizePreview() {
      if (!frameworkSizePreviewRow) return;
      frameworkSizePreviewRow.classList.add('size-category-list');
      frameworkSizePreviewRow.innerHTML = categorizedSizePreviewHtml(materialSizes.map((_, index) => index), frameworkSizeIndex);
      syncResultCollapseState();
    }

    function applyFrameworkSizePreview(sizeIndex) {
      if (!materialSizes[sizeIndex] || !anchorCanvas) return;
      frameworkSizeIndex = sizeIndex;
      const size = materialSizes[sizeIndex];
      anchorCanvas.style.aspectRatio = `${size.width} / ${size.height}`;
      renderAnchorEditor();
      document.querySelectorAll('#frameworkSizePreviewRow .size-thumb').forEach(thumb => {
        thumb.classList.toggle('active', Number(thumb.dataset.sizePreviewIndex) === sizeIndex);
      });
    }

    const productImageController = window.createProductImageController({
      clamp,
      getCurrentSize: () => materialSizes[currentSizeIndex],
      getMaterialCard: () => materialCard,
      getProductFrame: () => productFrame,
      getProductImage: () => phoneHand,
      getHasImage: () => hasImage,
      getIsGenerating: () => isGenerating,
      getAdjustments: () => productImageAdjustments,
      getPosterRenderer: () => posterRenderer,
      getEffectivePosterAnchorsForSize: size => effectivePosterAnchorsForSize(size),
      axisLockedDelta,
      pushPosterEditHistory,
      beginProductWheelUndo: () => beginProductWheelUndo(),
      finishProductWheelUndoSoon: () => finishProductWheelUndoSoon()
    });

    const {
      productAdjustmentKey,
      defaultProductAdjustment,
      currentProductAdjustment,
      productImageGeometry,
      clampProductAdjustment,
      updateProductImageFrame,
      selectProductFrame,
      updateProductAdjustment,
      panProductImageFromDrag,
      zoomProductImage,
      initProductImageInteractions
    } = productImageController;

    materialCard?.addEventListener('poster-layout-adjusted', () => {
      requestAnimationFrame(updateProductImageFrame);
    });

    const PREVIEW_PADDING = 40;

    function clampPreviewScale(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function previewScaleForSize(size = materialSizes[currentSizeIndex]) {
      const width = Math.max(1, Number(size?.width) || 1);
      const height = Math.max(1, Number(size?.height) || 1);
      const areaRect = canvasArea?.getBoundingClientRect();
      const maxWidth = Math.max(260, (areaRect?.width || 980) - PREVIEW_PADDING);
      const canvasTop = areaRect?.top || 0;
      const maxHeight = Math.max(180, Math.min(720, window.innerHeight - canvasTop - 28));
      const fitScale = Math.min(maxWidth / width, maxHeight / height);
      const ratio = width / height;
      const largestSide = Math.max(width, height);

      if (height <= 100) return clampPreviewScale(fitScale, 1.15, 2.35);
      if (width <= 320 && height <= 250) return clampPreviewScale(fitScale, 1.15, 2);
      if (width <= 180 && height >= 500) return clampPreviewScale(fitScale, 0.85, 1.3);
      if (largestSide >= 1000) return clampPreviewScale(fitScale, 0.24, 0.9);
      if (ratio >= 3) return clampPreviewScale(fitScale, 0.7, 1);
      return clampPreviewScale(fitScale, 0.55, 1.05);
    }

    function realSizePreviewCanvas(size = materialSizes[currentSizeIndex]) {
      const width = Math.max(1, Number(size?.width) || 1);
      const height = Math.max(1, Number(size?.height) || 1);
      const scale = previewScaleForSize(size);
      return {
        scale,
        width: Math.max(1, Math.round(width * scale)),
        height: Math.max(1, Math.round(height * scale))
      };
    }

    function updatePreviewZoomControls(size = materialSizes[currentSizeIndex], scale = previewScaleForSize(size)) {
      if (previewScaleMeta && size?.width && size?.height) {
        previewScaleMeta.textContent = `${size.width} × ${size.height} · 预览 ${Math.round(scale * 100)}%`;
      }
      canvasArea?.classList.toggle('is-fixed-zoom', true);
    }

    function fitMaterialPreview(size = materialSizes[currentSizeIndex]) {
      if (!materialCard || !canvasArea || !size?.width || !size?.height) return;
      canvasArea.classList.toggle('is-fixed-zoom', true);
      const dimensions = realSizePreviewCanvas(size);
      updatePreviewZoomControls(size, dimensions.scale);
      materialCard.style.setProperty('--preview-w', `${Math.max(1, Math.round(dimensions.width))}px`);
      materialCard.style.setProperty('--preview-h', `${Math.max(1, Math.round(dimensions.height))}px`);
      requestAnimationFrame(updateProductImageFrame);
    }

    function applySizePreview(sizeIndex) {
      if (!materialSizes[sizeIndex]) return;
      currentSizeIndex = sizeIndex;
      const size = materialSizes[sizeIndex];
      materialCard.style.aspectRatio = `${size.width} / ${size.height}`;
      fitMaterialPreview(size);
      applyPosterLayoutForSize(sizeIndex);
      applyLanguagePreview(currentLanguageIndex);
      requestAnimationFrame(updateProductImageFrame);
      document.querySelectorAll('#sizePreviewRow .size-thumb, #bottomSizePreviewRow .size-thumb').forEach(thumb => {
        thumb.classList.toggle('active', Number(thumb.dataset.sizePreviewIndex) === sizeIndex);
      });
      updatePager();
    }

    function renderLanguagePreview(indices = generatedLanguageIndices) {
      const html = indices.map(index => {
        const [cn, en] = languages[index] || languages[0];
        const complete = isPosterCopyComplete(languageEditorCopy(index));
        return `
          <button class="language-pill ${index === currentLanguageIndex ? 'active' : ''} ${complete ? 'is-complete' : ''}" type="button" data-language-preview-index="${index}">
            ${complete ? '<i class="language-complete-dot" aria-label="已填写"></i>' : ''}
            ${cn}<span>${en}</span>
          </button>
        `;
      }).join('');
      languagePreviewRow.innerHTML = html;
      if (bottomLanguagePreviewRow) bottomLanguagePreviewRow.innerHTML = html;
      syncResultCollapseState();
    }

    function setLanguagePreviewCompleteState(languageIndex, complete) {
      document.querySelectorAll(`.language-pill[data-language-preview-index="${languageIndex}"]`).forEach(pill => {
        pill.classList.toggle('is-complete', complete);
        const existing = pill.querySelector('.language-complete-dot');
        if (complete && !existing) {
          pill.insertAdjacentHTML('afterbegin', '<i class="language-complete-dot" aria-label="已填写"></i>');
        }
        if (!complete) existing?.remove();
      });
    }

    function generatedAssetCount() {
      return generatedAssets.length || (generatedSizeIndices.length * generatedLanguageIndices.length);
    }

    function updatePager() {
      // Preview paging controls were removed; keep this hook for existing state updates.
    }

    function updateGeneratedMeta() {
      statusMeta.textContent = generatedAssets.some(asset => asset.rule)
        ? `已按生成规则准备 ${generatedAssetCount()} 张素材。`
        : `${generatedSizeIndices.length} 个尺寸 × ${generatedLanguageIndices.length} 种语言，共 ${generatedAssetCount()} 张素材已准备下载。`;
    }

    function resetGeneratorPanelScroll(targetPanel = null) {
      [settingsPanel, resultPreviewPanel, generatorLayout, document.scrollingElement]
        .filter(Boolean)
        .forEach(element => {
          element.scrollTop = 0;
          element.scrollLeft = 0;
        });
      if (targetPanel?.scrollIntoView) {
        requestAnimationFrame(() => targetPanel.scrollIntoView({ block: 'start', inline: 'nearest' }));
      }
    }

    function syncGeneratorPanelState() {
      activeGeneratorPanel = 'results';
      const showingResults = true;
      settingsPanel?.classList.add('hidden');
      resultPreviewPanel?.classList.remove('hidden');
      settingsTabButton?.classList.remove('active');
      resultsTabButton?.classList.add('active');
      settingsTabButton?.setAttribute('aria-selected', 'false');
      resultsTabButton?.setAttribute('aria-selected', 'true');
      resultsTabButton?.setAttribute('aria-disabled', generated ? 'false' : 'true');
      if (resultsTabButton) resultsTabButton.disabled = !generated || isGenerating;
      if (settingsTabButton) settingsTabButton.disabled = isGenerating;
      syncPreviewActionVisibility(showingResults);
    }

    function syncPreviewActionVisibility(showingResults = generated && activeGeneratorPanel === 'results') {
      const shouldShowActions = Boolean(generated && showingResults);
      downloadMenu?.classList.toggle('hidden', !shouldShowActions);
      downloadButton?.classList.toggle('hidden', !shouldShowActions);
      styleSwitchButton?.classList.toggle('hidden', !shouldShowActions);
      editPosterButton?.classList.toggle('hidden', !shouldShowActions);
      regenerateButton?.classList.toggle('hidden', !shouldShowActions);
      if (!shouldShowActions) closeDownloadMenu();
    }

    function switchGeneratorPanel(panel, options = {}) {
      const target = panel === 'results' ? 'results' : 'settings';
      if (target === 'results' && !generated && !options.force) {
        showToast('请先填写信息并点击生成');
        syncGeneratorPanelState();
        return;
      }
      activeGeneratorPanel = target;
      syncGeneratorPanelState();
      resetGeneratorPanelScroll(target === 'results' ? resultPreviewPanel : settingsPanel);
    }

    function syncCopyPlaceholderState() {
      [titleInput, subtitleInput, ctaInput].forEach(input => input?.classList.remove('copy-placeholder'));
    }

    function enforceCopyInputLimit(input, limit) {
      if (!input || !Number.isFinite(limit)) return;
      if (input.value.length > limit) input.value = input.value.slice(0, limit);
    }

    function updateCounters() {
      enforceCopyInputLimit(titleInput, COPY_LIMITS.title);
      enforceCopyInputLimit(subtitleInput, COPY_LIMITS.subtitle);
      enforceCopyInputLimit(ctaInput, COPY_LIMITS.cta);
      titleCounter.textContent = `${titleInput.value.length}/${COPY_LIMITS.title}`;
      subtitleCounter.textContent = `${subtitleInput.value.length}/${COPY_LIMITS.subtitle}`;
      ctaCounter.textContent = `${ctaInput.value.length}/${COPY_LIMITS.cta}`;
      syncCopyPlaceholderState();
      if (!generated || currentLanguageIndex === 0) applyLanguagePreview(0);
      if (!document.getElementById('templateManagerView')?.classList.contains('hidden')) renderAnchorEditor();
      updateUploadState();
    }

    function handleSourceCopyInput() {
      enforceCopyInputLimit(titleInput, COPY_LIMITS.title);
      enforceCopyInputLimit(subtitleInput, COPY_LIMITS.subtitle);
      enforceCopyInputLimit(ctaInput, COPY_LIMITS.cta);
      syncLocalizedCopyFromInputs();
      updateCounters();
      if (generated && currentLanguageIndex !== 0) applyLanguagePreview(currentLanguageIndex);
    }

    function bindCopyPlaceholderBehavior(input) {
      if (!input) return;
      const originalPlaceholder = input.getAttribute('placeholder') || '';
      input.addEventListener('focus', () => {
        input.setAttribute('placeholder', originalPlaceholder);
      });
      input.addEventListener('blur', () => {
        input.setAttribute('placeholder', originalPlaceholder);
        updateCounters();
      });
    }

    function isGenerationReady() {
      return titleInput.value.trim()
        && subtitleInput.value.trim()
        && ctaInput.value.trim()
        && hasImage
        && selectedSizeIndices().length > 0
        && selectedLanguageIndices().length > 0;
    }

    function updateUploadState() {
      uploadPreview.classList.toggle('hidden', !hasImage);
      uploadMeta.classList.toggle('hidden', !hasImage);
      uploadCard.classList.toggle('hidden', hasImage);
      productFrame.classList.toggle('hidden', !hasImage);
      if (!hasImage && activePosterAnchor !== 'image') selectProductFrame(false);
      if (posterUploadAction) {
        posterUploadAction.textContent = hasImage ? '重新上传' : '上传主图';
        posterUploadAction.classList.remove('hidden');
      }
      emptyNote.classList.add('hidden');
      materialCard.classList.toggle('empty', !generated && !hasImage);
      materialCard.classList.toggle('generated', generated);
      materialCard.classList.toggle('no-upload', !hasImage);
      if (!generated) {
        activePosterAnchor = null;
        selectedPosterAnchorKeys = new Set();
      }
      renderPosterEditOverlay();
      generateButton.disabled = !appInitialized || !isGenerationReady();
      downloadButton.disabled = !generated || !hasImage;
      if (styleSwitchButton) styleSwitchButton.disabled = !generated;
      editPosterButton.disabled = !generated;
      if (regenerateButton) regenerateButton.disabled = !generated;
      syncGeneratorPanelState();
      previewBottomSwitcher?.classList.toggle('hidden', !generated);
      generatorLayout.classList.toggle('result-mode', generated);
      sizePreviewSection.classList.toggle('is-empty', !generated);
      languagePreviewSection.classList.toggle('is-empty', !generated);
      updatePager();
      requestAnimationFrame(() => fitMaterialPreview());
    }

    function showToast(message) {
      const toast = document.getElementById('toast');
      if (!toast) return;
      toast.textContent = message;
      toast.classList.add('visible');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => toast.classList.remove('visible'), 2400);
    }

    function setGeneratingState(next) {
      isGenerating = next;
      generateButton.disabled = next || !appInitialized || !isGenerationReady();
      downloadButton.disabled = next || !generated || !hasImage;
      if (styleSwitchButton) styleSwitchButton.disabled = next || !generated;
      if (next) closeDownloadMenu();
      editPosterButton.disabled = next || !generated;
      if (regenerateButton) regenerateButton.disabled = next || !generated;
      syncGeneratorPanelState();
      uploadInput.disabled = next;
      uploadCard.disabled = next;
      removeUpload.disabled = next;
      document.querySelectorAll('[data-upload-action], .template-card, .logo-tone-card, .language-card, #sizeChecks input, .select-all, #resetButton, #addTemplateButton, #deleteTemplateButton, #commitAnchorsButton, [data-size-setting-action], [data-language-setting-action], .settings-input, .drag-handle, .style-field input, .style-field select')
        .forEach(control => { control.disabled = next; });
    }

    function renderUploadPreview() {
      uploadPreview.classList.toggle('has-image', Boolean(uploadedImageSrc));
      uploadPreview.querySelector('.upload-image')?.remove();
      if (uploadedImageSrc) {
        const img = document.createElement('img');
        img.className = 'upload-image';
        img.src = uploadedImageSrc;
        img.alt = uploadedImageName;
        uploadPreview.prepend(img);
      }
      if (uploadedImageSrc) {
        phoneHand.src = uploadedImageSrc;
        phoneHand.onload = () => updateProductImageFrame();
      } else {
        phoneHand.removeAttribute('src');
        phoneHand.removeAttribute('style');
      }
      uploadName.textContent = uploadedImageName;
    }

    function setUploadEmpty() {
      hasImage = false;
      uploadedImageSrc = '';
      uploadedImageName = '未上传图片';
      productImageAdjustments = {};
      posterAnchorOverrides = {};
      activePosterAnchor = null;
      selectedPosterAnchorKeys = new Set();
      clearPosterEditHistory();
      phoneHand.removeAttribute('style');
      uploadInput.value = '';
      renderUploadPreview();
      updateUploadState();
      setTrustVisible(trustVisible);
    }

    function setUploadImage(file, src) {
      hasImage = true;
      uploadedImageSrc = src;
      uploadedImageName = file.name || '已上传图片';
      productImageAdjustments = {};
      posterAnchorOverrides = {};
      activePosterAnchor = null;
      selectedPosterAnchorKeys = new Set();
      clearPosterEditHistory();
      uploadInput.value = '';
      renderUploadPreview();
      updateUploadState();
      setTrustVisible(trustVisible);
    }

    function deleteUploadedImage() {
      if (isGenerating) {
        showToast('生成中暂不支持删除图片');
        return;
      }
      setUploadEmpty();
      showToast('图片已删除');
    }

    function fileToDataUrl(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
      });
    }

    function canvasToBlob(canvas, type, quality) {
      return new Promise(resolve => canvas.toBlob(resolve, type, quality));
    }

    async function cropCanvasToUploadDataUrl(canvas, mimeType = 'image/jpeg') {
      if (mimeType === 'image/png') {
        const blob = await canvasToBlob(canvas, 'image/png');
        if (!blob) throw new Error('crop too large');
        return fileToDataUrl(blob);
      }
      const maxBytes = 2 * 1024 * 1024;
      let blob = null;
      for (let quality = 0.92; quality >= 0.56; quality -= 0.08) {
        blob = await canvasToBlob(canvas, 'image/jpeg', quality);
        if (blob && blob.size <= maxBytes) break;
      }
      if (!blob || blob.size > maxBytes) throw new Error('crop too large');
      return fileToDataUrl(blob);
    }

    function destroyUploadCropper() {
      if (!uploadCropper) return;
      uploadCropper.destroy();
      uploadCropper = null;
    }

    function closeUploadCropper(resetInput = true) {
      document.getElementById('uploadCropModal')?.classList.remove('open');
      destroyUploadCropper();
      uploadCropFile = null;
      if (resetInput) uploadInput.value = '';
    }

    function ensureUploadCropModal() {
      let modal = document.getElementById('uploadCropModal');
      if (!modal) {
        modal = document.createElement('div');
        modal.id = 'uploadCropModal';
        modal.className = 'crop-modal';
        document.body.appendChild(modal);
        modal.addEventListener('click', event => {
          if (event.target === modal || event.target.closest('[data-crop-action="cancel"]')) closeUploadCropper(true);
        });
        document.addEventListener('keydown', event => {
          if (event.key === 'Escape' && modal.classList.contains('open')) closeUploadCropper(true);
        });
      }
      modal.innerHTML = `
        <div class="crop-dialog" role="dialog" aria-modal="true" aria-label="裁切图片">
          <div class="crop-header">
            <div>
              <div class="image-title">裁切图片</div>
              <div class="upload-hint">拖动图片生成 530×628 右侧商品图层，应用后会同步显示到海报右侧。</div>
            </div>
            <button class="image-close" type="button" data-crop-action="cancel" aria-label="取消">×</button>
          </div>
          <div class="crop-body">
            <div class="crop-canvas"><img class="crop-image" id="uploadCropImage" alt="待裁切图片" /></div>
          </div>
          <div class="crop-actions">
            <button class="modal-btn" type="button" data-crop-action="cancel">取消</button>
            <button class="modal-btn primary" type="button" data-crop-action="apply">应用裁切</button>
          </div>
        </div>
      `;
      modal.querySelector('[data-crop-action="apply"]')?.addEventListener('click', async () => {
        try {
          const outputType = uploadCropFile?.type === 'image/png' ? 'image/png' : 'image/jpeg';
          const canvas = uploadCropper?.getCroppedCanvas({
            width: 530,
            height: 628,
            fillColor: outputType === 'image/png' ? 'rgba(0,0,0,0)' : '#ffffff',
            imageSmoothingEnabled: true,
            imageSmoothingQuality: 'high'
          });
          if (!canvas || !uploadCropFile) throw new Error('crop failed');
          const src = await cropCanvasToUploadDataUrl(canvas, outputType);
          setUploadImage(uploadCropFile, src);
          closeUploadCropper(false);
          showToast('图片已裁切并上传');
        } catch (error) {
          showToast('图片裁切失败，请换一张图片重试');
        }
      });
      return modal;
    }

    async function openUploadCropper(file, src) {
      try {
        await window.SpecPromoDependencies?.ensureCropper?.();
      } catch (error) {
        setUploadImage(file, src);
        showToast('裁切工具加载失败，已使用原图预览');
        return;
      }
      if (!window.Cropper) {
        setUploadImage(file, src);
        showToast('裁切工具未加载，已使用原图预览');
        return;
      }
      const modal = ensureUploadCropModal();
      const image = modal.querySelector('#uploadCropImage');
      uploadCropFile = file;
      destroyUploadCropper();
      image.onload = () => {
        uploadCropper = new Cropper(image, {
          aspectRatio: 530 / 628,
          viewMode: 1,
          autoCropArea: 1,
          background: false,
          responsive: true,
          dragMode: 'move'
        });
      };
      image.src = src;
      modal.classList.add('open');
    }

    async function validateUploadImage(src) {
      const image = await loadCanvasImage(src);
      if (image.naturalWidth > 8000 || image.naturalHeight > 8000) {
        throw new Error('image too large');
      }
      return image;
    }

    async function handleUploadFile(file) {
      if (!file) return;
      if (isGenerating) {
        showToast('生成中暂不支持更换图片');
        uploadInput.value = '';
        return;
      }
      if (!['image/jpeg', 'image/png'].includes(file.type)) {
        showToast('仅支持 JPG、JPEG、PNG 图片');
        uploadInput.value = '';
        return;
      }
      if (file.size > 2 * 1024 * 1024) {
        showToast('图片不能超过 2MB');
        uploadInput.value = '';
        return;
      }
      try {
        const src = await fileToDataUrl(file);
        await validateUploadImage(src);
        setUploadImage(file, src);
        showToast('图片已上传，可在预览区拖动调整裁切或滚轮缩放');
      } catch (error) {
        const message = error.message === 'image too large'
            ? '图片像素过大，请压缩后上传'
            : '图片读取失败，请重试';
        showToast(message);
        uploadInput.value = '';
      }
    }

    function openUploadPicker() {
      uploadInput.click();
    }

    function closeImageViewer() {
      document.getElementById('uploadImageModal')?.classList.remove('open');
    }

    function openImageViewer() {
      if (!hasImage) {
        showToast('暂无可查看图片');
        return;
      }
      let modal = document.getElementById('uploadImageModal');
      if (!modal) {
        modal = document.createElement('div');
        modal.id = 'uploadImageModal';
        modal.className = 'image-modal';
        modal.innerHTML = `
          <div class="image-dialog" role="dialog" aria-modal="true" aria-label="图片预览">
            <div class="image-header">
              <div class="image-title">图片预览</div>
              <button class="image-close" type="button" aria-label="关闭图片预览">×</button>
            </div>
            <div class="image-body"><img class="image-large" alt="图片预览" /></div>
          </div>
        `;
        document.body.appendChild(modal);
        modal.addEventListener('click', event => {
          if (event.target === modal || event.target.closest('.image-close')) closeImageViewer();
        });
        document.addEventListener('keydown', event => {
          if (event.key === 'Escape') closeImageViewer();
        });
      }
      const large = modal.querySelector('.image-large');
      large.src = uploadedImageSrc;
      large.alt = uploadedImageName;
      modal.classList.add('open');
    }

    function initUploadInteractions() {
      renderUploadPreview();

      uploadInput.addEventListener('change', () => handleUploadFile(uploadInput.files?.[0]));

      uploadCard.addEventListener('click', openUploadPicker);
      uploadCard.addEventListener('keydown', event => {
        if (!['Enter', ' '].includes(event.key)) return;
        event.preventDefault();
        openUploadPicker();
      });

      uploadPreview.addEventListener('keydown', event => {
        if (!['Enter', ' '].includes(event.key)) return;
        event.preventDefault();
        openImageViewer();
      });

      uploadZone.addEventListener('click', event => {
        const action = event.target.closest('[data-upload-action]')?.dataset.uploadAction;
        if (!action) return;
        if (action === 'view') openImageViewer();
        if (action === 'delete') deleteUploadedImage();
        if (action === 'reupload') openUploadPicker();
      });

      ['dragenter', 'dragover'].forEach(type => {
        uploadZone.addEventListener(type, event => {
          event.preventDefault();
          if (!hasImage) uploadCard.classList.add('is-dragover');
        });
      });

      ['dragleave', 'drop'].forEach(type => {
        uploadZone.addEventListener(type, event => {
          event.preventDefault();
          uploadCard.classList.remove('is-dragover');
        });
      });

      uploadZone.addEventListener('drop', event => handleUploadFile(event.dataTransfer?.files?.[0]));
      posterUploadAction?.addEventListener('click', event => {
        event.stopPropagation();
        openUploadPicker();
      });
      const selectMainImageArea = () => {
        activePosterAnchor = 'image';
        selectedPosterAnchorKeys = new Set(['image']);
        renderPosterEditOverlay();
        updateUploadState();
      };
      posterImagePlaceholder?.addEventListener('click', event => {
        event.stopPropagation();
        if (!hasImage) {
          openUploadPicker();
          return;
        }
        selectMainImageArea();
      });
      posterImagePlaceholder?.addEventListener('keydown', event => {
        if (!['Enter', ' '].includes(event.key)) return;
        event.preventDefault();
        if (!hasImage) {
          openUploadPicker();
          return;
        }
        selectMainImageArea();
      });
    }

    function beginProductWheelUndo() {
      if (!generated || productWheelUndoActive) return;
      pushPosterEditHistory();
      productWheelUndoActive = true;
    }

    function finishProductWheelUndoSoon() {
      if (productWheelUndoTimer) window.clearTimeout(productWheelUndoTimer);
      productWheelUndoTimer = window.setTimeout(() => {
        productWheelUndoActive = false;
        productWheelUndoTimer = null;
      }, 360);
    }

    document.addEventListener('click', event => {
      if (event.target.closest('#productFrame, #posterUploadAction, #posterImagePlaceholder, .poster-anchor-box[data-poster-anchor="image"]')) return;
      if (activePosterAnchor === 'image') {
        activePosterAnchor = null;
        selectedPosterAnchorKeys.delete('image');
        renderPosterEditOverlay();
        updateUploadState();
      }
      selectProductFrame(false);
    });

    document.addEventListener('keydown', event => {
      const isUndoShortcut = (event.metaKey || event.ctrlKey) && !event.shiftKey && event.key.toLowerCase() === 'z';
      if (!isUndoShortcut || !generated) return;
      const target = event.target;
      const isEditableTarget = target?.matches?.('input, textarea, select') || target?.isContentEditable;
      if (isEditableTarget) return;
      event.preventDefault();
      undoPosterEdit();
    });

    function closeEditPosterModal() {
      document.getElementById('editPosterModal')?.classList.remove('open');
    }

    function ensureEditPosterModal() {
      let modal = document.getElementById('editPosterModal');
      if (!modal) {
        modal = document.createElement('div');
        modal.id = 'editPosterModal';
        modal.className = 'confirm-modal side-drawer-modal';
        document.body.appendChild(modal);
        modal.addEventListener('click', event => {
          if (event.target === modal || event.target.closest('[data-edit-action="cancel"]')) closeEditPosterModal();
          if (event.target.closest('[data-edit-action="submit"]')) submitPosterEdit();
          if (event.target.closest('[data-edit-action="clear-copy"]')) {
            event.stopPropagation();
            clearPosterCopySettings();
            return;
          }
          const removeButton = event.target.closest('[data-remove-copy-language]');
          if (removeButton) {
            event.stopPropagation();
            removePosterCopyLanguage(Number(removeButton.dataset.removeCopyLanguage));
            return;
          }
          const selector = event.target.closest('[data-language-selector-toggle]');
          if (selector) {
            event.stopPropagation();
            togglePosterLanguageDropdown();
            return;
          }
          const addButton = event.target.closest('[data-add-copy-language]');
          if (addButton && !addButton.disabled) {
            event.stopPropagation();
            addPosterCopyLanguage(Number(addButton.dataset.addCopyLanguage));
          }
        });
        modal.addEventListener('input', event => {
          if (event.target.closest('[data-copy-field]')) syncPosterCopyStatus();
        });
        document.addEventListener('keydown', event => {
          if (event.key === 'Escape') closeEditPosterModal();
        });
      }
      return modal;
    }

    function selectedPosterCopyLanguageIndices() {
      const selected = generatedLanguageIndices.length ? generatedLanguageIndices : selectedLanguageIndices();
      const valid = validIndices(selected, languages);
      return valid.length ? valid : (languages.length ? [0] : []);
    }

    function posterCopyLanguageIndicesFromModal() {
      const modal = document.getElementById('editPosterModal');
      const selected = [...modal?.querySelectorAll('[data-selected-copy-language]') || []]
        .map(item => Number(item.dataset.selectedCopyLanguage))
        .filter(index => Number.isInteger(index) && languages[index]);
      return validIndices(selected, languages);
    }

    function isPosterCopyComplete(copy) {
      return ['title', 'subtitle', 'cta'].every(key => String(copy?.[key] || '').trim());
    }

    function posterCopyStatus(copy) {
      return isPosterCopyComplete(copy) ? '已填写' : '';
    }

    function isInitialCopyPlaceholderValue(value, languageIndex, key) {
      const current = normalizeCopyText(value);
      const defaultValue = normalizeCopyText(cloneDefaultCopy(languageIndex)?.[key]);
      const placeholderSourceKeys = {
        title: ['Headline Text'],
        subtitle: [
          'More information and key features here.',
          'More information and key features can be detailed here.'
        ],
        cta: ['Button', 'Button Text']
      };
      const translatedDefaults = (placeholderSourceKeys[key] || [])
        .map(sourceKey => COPY_TRANSLATION_MAP[sourceKey]?.[languageIndex] || sourceKey)
        .map(normalizeCopyText);
      return Boolean(current && (current === defaultValue || translatedDefaults.includes(current)));
    }

    function copyValueForPosterEditor(copy, languageIndex, key) {
      const value = normalizeCopyText(copy?.[key]);
      return isInitialCopyPlaceholderValue(value, languageIndex, key) ? '' : value;
    }

    function languageEditorCopy(languageIndex) {
      const copy = normalizeCopy(localizedCopy[languageIndex] || getLanguageCopy(languageIndex), languageIndex);
      return {
        title: copyValueForPosterEditor(copy, languageIndex, 'title'),
        subtitle: copyValueForPosterEditor(copy, languageIndex, 'subtitle'),
        cta: copyValueForPosterEditor(copy, languageIndex, 'cta')
      };
    }

    function posterEditorCopyFromCard(card) {
      return {
        title: normalizeCopyText(card.querySelector('[data-copy-field="title"]')?.value),
        subtitle: normalizeCopyText(card.querySelector('[data-copy-field="subtitle"]')?.value),
        cta: normalizeCopyText(card.querySelector('[data-copy-field="cta"]')?.value)
      };
    }

    function posterCopyCardHtml(index) {
      const [cn = '', en = ''] = languages[index] || [];
      const editorCopy = languageEditorCopy(index);
      const complete = isPosterCopyComplete(editorCopy);
      return `
        <section class="language-copy-card ${complete ? 'is-complete' : ''}" data-copy-language-index="${index}">
          <div class="language-copy-head">
            <div>
              <strong>${escapeHtml(cn)}</strong>
              <span>${escapeHtml(en)}</span>
            </div>
            <em data-copy-status>${complete ? '<i>✓</i>已填写' : ''}</em>
          </div>
          <label>标题
            <input data-copy-field="title" maxlength="${COPY_LIMITS.title}" placeholder="请输入内容" value="${escapeHtml(editorCopy.title)}" autocomplete="off">
          </label>
          <label>副标题
            <textarea data-copy-field="subtitle" maxlength="${COPY_LIMITS.subtitle}" placeholder="请输入内容" autocomplete="off">${escapeHtml(editorCopy.subtitle)}</textarea>
          </label>
          <label>按钮文案
            <input data-copy-field="cta" maxlength="${COPY_LIMITS.cta}" placeholder="请输入内容" value="${escapeHtml(editorCopy.cta)}" autocomplete="off">
          </label>
        </section>
      `;
    }

    function posterLanguageSelectHtml(selectedIndices) {
      const selectedSet = new Set(selectedIndices);
      const chips = selectedIndices.map(index => {
        const [cn = '', en = ''] = languages[index] || [];
        const removable = selectedIndices.length > 1;
        return `
          <span class="copy-language-chip" data-selected-copy-language="${index}">
            ${escapeHtml(cn)}
            <button type="button" ${removable ? '' : 'disabled'} data-remove-copy-language="${index}" aria-label="移除 ${escapeHtml(cn)}">×</button>
          </span>
        `;
      }).join('');
      const options = languages.map(([cn, en], index) => {
        const selected = selectedSet.has(index);
        return `
          <button class="copy-language-option${selected ? ' is-selected' : ''}" type="button" data-add-copy-language="${index}" ${selected ? 'disabled' : ''}>
            <span>${escapeHtml(cn)} <small>${escapeHtml(en)}</small></span>
            <em>${selected ? '已选择' : '添加'}</em>
          </button>
        `;
      }).join('');
      return `
        <div class="copy-language-select-wrap">
          <div class="copy-language-label">本次产出语言</div>
          <div class="copy-language-select" role="button" tabindex="0" data-language-selector-toggle aria-expanded="false">
            <span class="copy-language-chip-list">${chips}</span>
            <span class="copy-language-arrow">▾</span>
          </div>
          <div class="copy-language-menu" data-copy-language-menu>
            ${options}
          </div>
        </div>
      `;
    }

    function normalizedPosterCopyLanguageSelection(selectedIndices = selectedPosterCopyLanguageIndices()) {
      const validSelected = validIndices(selectedIndices, languages);
      return validSelected.length ? validSelected : (languages.length ? [0] : []);
    }

    function posterEditLanguageFormHtml(selectedIndices = selectedPosterCopyLanguageIndices()) {
      const safeSelected = normalizedPosterCopyLanguageSelection(selectedIndices);
      return `
        ${posterLanguageSelectHtml(safeSelected)}
        <div class="multi-language-divider"></div>
        ${safeSelected.map(index => posterCopyCardHtml(index)).join('')}
      `;
    }

    function renderPosterEditModalContent(modal, selectedIndices = selectedPosterCopyLanguageIndices()) {
      modal.innerHTML = `
        <div class="confirm-dialog poster-edit-dialog side-drawer-dialog multi-language-dialog" role="dialog" aria-modal="true" aria-label="多语言设置">
          <div class="style-switch-head">
            <div>
              <div class="confirm-title">多语言设置</div>
              <p class="style-switch-desc">选择本次要预览和产出的语言，未选择的语言不会生成素材。</p>
            </div>
            <button class="image-close" type="button" data-edit-action="cancel" aria-label="关闭多语言设置">×</button>
          </div>
          <div class="multi-language-form">
            ${posterEditLanguageFormHtml(selectedIndices)}
          </div>
          <div class="confirm-actions drawer-actions">
            <button class="modal-btn clear-copy-btn" type="button" data-edit-action="clear-copy" title="清除所有已填写文案" aria-label="清除所有已填写文案">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <path d="m7 21-4.3-4.3c-1-1-1-2.5 0-3.4l9.6-9.6c1-1 2.5-1 3.4 0l5.6 5.6c1 1 1 2.5 0 3.4L13 21"/>
                <path d="M22 21H7"/>
                <path d="m5 11 9 9"/>
              </svg>
            </button>
            <button class="modal-btn" type="button" data-edit-action="cancel">取消</button>
            <button class="modal-btn primary" type="button" data-edit-action="submit">保存设置</button>
          </div>
        </div>
      `;
    }

    function refreshOpenPosterEditModal(selectedIndices = selectedPosterCopyLanguageIndices()) {
      const modal = document.getElementById('editPosterModal');
      if (!modal?.classList.contains('open')) return;
      syncPosterCopyFromModal();
      renderPosterEditModalContent(modal, normalizedPosterCopyLanguageSelection(selectedIndices));
      syncPosterCopyStatus();
    }

    function emptyPosterCopy() {
      return { title: '', subtitle: '', cta: '' };
    }

    function clearPosterCopySettings() {
      const modal = document.getElementById('editPosterModal');
      if (!modal) return;
      localizedCopy = languages.map(() => emptyPosterCopy());
      Object.keys(posterCopyOverrides).forEach(key => delete posterCopyOverrides[key]);
      modal.querySelectorAll('[data-copy-field]').forEach(field => {
        field.value = '';
        field.defaultValue = '';
        field.setAttribute('value', '');
      });
      titleInput.value = '';
      subtitleInput.value = '';
      ctaInput.value = '';
      updateCounters();
      syncPosterCopyStatus();
      renderLanguagePreview(generatedLanguageIndices);
      applyLanguagePreview(currentLanguageIndex);
      saveTemplateState();
      showToast('已清除所有多语言文案填写');
    }

    function syncPosterCopyFromModal() {
      const modal = document.getElementById('editPosterModal');
      if (!modal) return;
      modal.querySelectorAll('[data-copy-language-index]').forEach(card => {
        const index = Number(card.dataset.copyLanguageIndex);
        if (!Number.isInteger(index) || !languages[index]) return;
        localizedCopy[index] = posterEditorCopyFromCard(card);
      });
    }

    function syncPosterCopyStatus() {
      const modal = document.getElementById('editPosterModal');
      modal?.querySelectorAll('[data-copy-language-index]').forEach(card => {
        const copy = posterEditorCopyFromCard(card);
        const status = card.querySelector('[data-copy-status]');
        const complete = isPosterCopyComplete(copy);
        card.classList.toggle('is-complete', complete);
        if (status) status.innerHTML = complete ? '<i>✓</i>已填写' : '';
        const index = Number(card.dataset.copyLanguageIndex);
        if (Number.isInteger(index)) setLanguagePreviewCompleteState(index, complete);
      });
    }

    function togglePosterLanguageDropdown(forceOpen = null) {
      const modal = document.getElementById('editPosterModal');
      const select = modal?.querySelector('[data-language-selector-toggle]');
      const wrap = modal?.querySelector('.copy-language-select-wrap');
      if (!select || !wrap) return;
      const open = forceOpen === null ? !wrap.classList.contains('open') : Boolean(forceOpen);
      wrap.classList.toggle('open', open);
      select.setAttribute('aria-expanded', String(open));
    }

    function updatePosterCopyLanguages(nextIndices) {
      const modal = document.getElementById('editPosterModal');
      if (!modal) return;
      const form = modal.querySelector('.multi-language-form');
      if (!form) return;
      const previousScrollTop = form.scrollTop;
      syncPosterCopyFromModal();
      form.innerHTML = posterEditLanguageFormHtml(nextIndices);
      form.scrollTop = previousScrollTop;
      syncPosterCopyStatus();
    }

    function addPosterCopyLanguage(index) {
      if (!Number.isInteger(index) || !languages[index]) return;
      const selected = posterCopyLanguageIndicesFromModal();
      if (selected.includes(index)) return;
      updatePosterCopyLanguages([...selected, index].sort((a, b) => a - b));
      togglePosterLanguageDropdown(true);
    }

    function removePosterCopyLanguage(index) {
      const selected = posterCopyLanguageIndicesFromModal();
      if (selected.length <= 1) {
        showToast('至少需要保留一种产出语言');
        return;
      }
      updatePosterCopyLanguages(selected.filter(item => item !== index));
    }

    function openEditPosterModal() {
      if (!generated) {
        showToast('素材正在初始化，请稍候');
        return;
      }
      const modal = ensureEditPosterModal();
      renderPosterEditModalContent(modal);
      modal.classList.add('open');
      modal.querySelector('[data-copy-field="title"]')?.focus();
    }

    function submitPosterEdit() {
      const modal = document.getElementById('editPosterModal');
      if (!modal) return;
      pushPosterEditHistory();
      const selectedLanguages = posterCopyLanguageIndicesFromModal();
      modal.querySelectorAll('[data-copy-language-index]').forEach(card => {
        const index = Number(card.dataset.copyLanguageIndex);
        if (!Number.isInteger(index) || !languages[index]) return;
        localizedCopy[index] = posterEditorCopyFromCard(card);
        delete posterCopyOverrides[index];
      });
      document.querySelectorAll('.language-card').forEach(card => {
        const index = Number(card.dataset.languageIndex);
        card.classList.toggle('active', selectedLanguages.includes(index));
      });
      generatedLanguageIndices = selectedLanguages;
      if (!generatedLanguageIndices.includes(currentLanguageIndex)) currentLanguageIndex = generatedLanguageIndices[0] || 0;
      generatedAssets = generatedSizeIndices.flatMap(sizeIndex =>
        generatedLanguageIndices.map(languageIndex => ({
          sizeIndex,
          languageIndex,
          fileName: buildAssetFileName(sizeIndex, languageIndex)
        }))
      );
      titleInput.value = localizedCopy[0]?.title || '';
      subtitleInput.value = localizedCopy[0]?.subtitle || '';
      ctaInput.value = localizedCopy[0]?.cta || '';
      updateCounters();
      renderLanguagePreview(generatedLanguageIndices);
      applyLanguagePreview(currentLanguageIndex);
      updateGeneratedMeta();
      updateUploadState();
      closeEditPosterModal();
      showToast('多语言设置已同步到预览和下载素材');
    }

    function setTrustVisible() {
      trustVisible = false;
      trustSwitch?.classList.toggle('off', true);
      renderPosterEditOverlay();
    }

    function buildAssetFileName(sizeIndex, languageIndex) {
      const size = materialSizes[sizeIndex] || materialSizes[0];
      const language = (languages[languageIndex]?.[1] || 'English')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '') || `lang-${languageIndex}`;
      const sizeOrder = String(materialSizeExportRank(size, sizeIndex)).padStart(2, '0');
      return `promo-material-${sizeOrder}-${size.id}-${language}.png`;
    }

    function defaultDownloadFolderName(date = new Date()) {
      const two = value => String(value).padStart(2, '0');
      const year = two(date.getFullYear() % 100);
      const month = two(date.getMonth() + 1);
      const day = two(date.getDate());
      const hour = two(date.getHours());
      const minute = two(date.getMinutes());
      return `promo-materials-${year}.${month}.${day}-${hour}:${minute}`;
    }


    function ruleSizeIndex(rule = {}) {
      if (!rule.width || !rule.height) return currentSizeIndex;
      return Math.max(0, materialSizes.findIndex(size => size.width === rule.width && size.height === rule.height));
    }

    function ruleLanguageIndex(rule = {}) {
      const language = normalizeRuleText(rule.language).toLowerCase();
      if (!language) return 0;
      const index = languages.findIndex(([cn, en]) => [cn, en].some(item => String(item || '').trim().toLowerCase() === language));
      return Math.max(0, index);
    }

    function syncSpreadsheetRulesToOptions() {
      if (!spreadsheetGenerationRules.length) return;
      spreadsheetGenerationRules.forEach(rule => {
        if (rule.width && rule.height && !materialSizes.some(size => size.width === rule.width && size.height === rule.height)) {
          materialSizes.push({
            id: `rule_${rule.width}x${rule.height}`,
            label: normalizeSizeLabel(rule.width, rule.height, rule.sizeLabel),
            width: rule.width,
            height: rule.height
          });
        }
        const language = normalizeRuleText(rule.language);
        if (language && !languages.some(([cn, en]) => [cn, en].some(item => String(item || '').trim().toLowerCase() === language.toLowerCase()))) {
          languages.push([language, language]);
          localizedCopy.push(defaultLocalizedCopy());
        }
      });
      normalizeSizeLanguageState();
      saveSizeLanguageState();
    }

    function buildRuleAsset(rule, ruleIndex) {
      const sizeIndex = ruleSizeIndex(rule);
      const languageIndex = ruleLanguageIndex(rule);
      const fallbackName = buildAssetFileName(sizeIndex, languageIndex).replace(/\.png$/i, `-rule-${ruleIndex + 1}.png`);
      return {
        ruleIndex,
        rule,
        sizeIndex,
        languageIndex,
        fileName: rule.fileName || fallbackName
      };
    }

    function uniqueAssetIndices(assets, key) {
      return [...new Set(assets.map(asset => asset[key]).filter(index => Number.isInteger(index)))];
    }

    function currentPreviewAsset(sizeIndex = currentSizeIndex, languageIndex = currentLanguageIndex) {
      return generatedAssets.find(asset => asset.sizeIndex === sizeIndex && asset.languageIndex === languageIndex)
        || generatedAssets.find(asset => asset.sizeIndex === sizeIndex)
        || generatedAssets.find(asset => asset.languageIndex === languageIndex)
        || null;
    }

    function copyForAsset(asset = currentPreviewAsset()) {
      if (!asset) return getLanguageCopy(currentLanguageIndex);
      const copy = posterCopyOverrides[asset.languageIndex]
        || { ...getLanguageCopy(asset.languageIndex), ...(asset.rule?.copy || {}) };
      return normalizeCopy(copy, asset.languageIndex);
    }

    function effectiveTrustVisible() {
      return false;
    }

    function validIndices(indices, collection) {
      return [...new Set(indices)]
        .filter(index => Number.isInteger(index) && index >= 0 && index < collection.length);
    }

    function recoverGenerationFailure(error) {
      console.error('Generation failed', error);
      generated = false;
      generatedAssets = [];
      progressCard.classList.remove('visible');
      materialCard.classList.remove('hidden');
      setGeneratingState(false);
      updateUploadState();
      showToast('生成失败，已恢复预览界面，请重试');
    }

    function buildDefaultGeneratedAssets() {
      return generatedSizeIndices.flatMap(sizeIndex =>
        generatedLanguageIndices.map(languageIndex => ({
          sizeIndex,
          languageIndex,
          fileName: buildAssetFileName(sizeIndex, languageIndex)
        }))
      );
    }

    function initializeGeneratedPreview() {
      normalizeSizeLanguageState();
      loadStyleMapping(stylePresets[0]?.id || 'style-1');
      generated = true;
      activeGeneratorPanel = 'results';
      generatedSizeIndices = materialSizes.map((_, index) => index);
      generatedLanguageIndices = languages.map((_, index) => index);
      generatedAssets = buildDefaultGeneratedAssets();
      if (!generatedSizeIndices.includes(currentSizeIndex)) currentSizeIndex = generatedSizeIndices[0] || 0;
      if (!generatedLanguageIndices.includes(currentLanguageIndex)) currentLanguageIndex = generatedLanguageIndices[0] || 0;
      renderSizePreview(generatedSizeIndices);
      renderLanguagePreview(generatedLanguageIndices);
      applySizePreview(currentSizeIndex);
      applyLanguagePreview(currentLanguageIndex);
      updateGeneratedMeta();
      progressCard.classList.remove('visible');
      materialCard.classList.remove('hidden');
      statusDock.classList.remove('visible');
      updateUploadState();
    }

    async function runGeneration() {
      if (isGenerating) return;
      if (!appInitialized) {
        pendingGenerationAfterInit = true;
        generateButton.disabled = true;
        showToast('素材配置加载中，请稍候');
        return;
      }
      normalizeSizeLanguageState();
      currentSizeIndex = Math.min(currentSizeIndex, Math.max(0, materialSizes.length - 1));
      frameworkSizeIndex = Math.min(frameworkSizeIndex, Math.max(0, materialSizes.length - 1));
      currentLanguageIndex = Math.min(currentLanguageIndex, Math.max(0, languages.length - 1));
      if (!isGenerationReady()) {
        showToast('请先填写标题、副标题、按钮文案，上传主图并至少选择一个尺寸和一种语言');
        updateUploadState();
        return;
      }
      syncSpreadsheetRulesToOptions();
      showToast('正在翻译多语言文案...');
      localizedCopy = await buildLocalizedCopyFromSourceAsync(getSourceCopy());
      Object.keys(posterCopyOverrides).forEach(key => delete posterCopyOverrides[key]);
      const ruleAssets = spreadsheetGenerationRules.map(buildRuleAsset).filter(asset =>
        Number.isInteger(asset?.sizeIndex) && materialSizes[asset.sizeIndex]
        && Number.isInteger(asset?.languageIndex) && languages[asset.languageIndex]
      );
      if (rulesDocuments.length && !ruleAssets.length) {
        showToast('已上传生成规则文档，但未解析到可执行规则，将按默认设置生成');
      }
      const nextSizeIndices = validIndices(
        ruleAssets.length ? uniqueAssetIndices(ruleAssets, 'sizeIndex') : selectedSizeIndices(),
        materialSizes
      );
      const nextLanguageIndices = validIndices(
        ruleAssets.length ? uniqueAssetIndices(ruleAssets, 'languageIndex') : selectedLanguageIndices(),
        languages
      );
      if (!nextSizeIndices.length) {
        showToast('请至少选择一个尺寸');
        return;
      }
      if (!nextLanguageIndices.length) {
        showToast('请至少选择一种语言');
        return;
      }
      generated = false;
      generatedAssets = [];
      generationToken += 1;
      const token = generationToken;
      statusDock.classList.remove('visible');
      resetGeneratorPanelScroll(settingsPanel);
      materialCard.classList.add('hidden');
      progressCard.classList.add('visible');
      progressFill.style.width = '0%';
      progressText.textContent = '0%';
      setGeneratingState(true);
      let value = 0;
      const timer = setInterval(() => {
        if (token !== generationToken) {
          clearInterval(timer);
          return;
        }
        value += 20;
        if (value >= 100) value = 100;
        progressFill.style.width = `${value}%`;
        progressText.textContent = `${value}%`;
        if (value === 100) {
          clearInterval(timer);
          setTimeout(() => {
            if (token !== generationToken) return;
            try {
              resetGeneratorPanelScroll(resultPreviewPanel);
              generated = true;
              generatedSizeIndices = nextSizeIndices;
              generatedLanguageIndices = nextLanguageIndices;
              generatedAssets = ruleAssets.length ? ruleAssets : generatedSizeIndices.flatMap(sizeIndex =>
                generatedLanguageIndices.map(languageIndex => ({
                  sizeIndex,
                  languageIndex,
                  fileName: buildAssetFileName(sizeIndex, languageIndex)
                }))
              );
              // 生成完成后从结果列表的第一个尺寸开始预览，而不是继续停留在模板预览尺寸。
              if (generatedSizeIndices.length) currentSizeIndex = generatedSizeIndices[0];
              if (!generatedLanguageIndices.includes(currentLanguageIndex)) currentLanguageIndex = generatedLanguageIndices[0];
              renderSizePreview(generatedSizeIndices);
              renderLanguagePreview(generatedLanguageIndices);
              clearPosterEditHistory();
              activeGeneratorPanel = 'results';
              applySizePreview(currentSizeIndex);
              applyLanguagePreview(currentLanguageIndex);
              updateGeneratedMeta();
              progressCard.classList.remove('visible');
              materialCard.classList.remove('hidden');
              updateUploadState();
              resetGeneratorPanelScroll(resultPreviewPanel);
              setTrustVisible(trustVisible);
              setGeneratingState(false);
              statusDock.classList.add('visible');
              setTimeout(() => statusDock.classList.remove('visible'), 1800);
            } catch (error) {
              recoverGenerationFailure(error);
            }
          }, 350);
        }
      }, 160);
    }

    window.specRunGeneration = runGeneration;

    function triggerGenerationFromButton(event) {
      const button = event.target?.closest?.('#generateButton');
      if (!button || button.disabled) return;
      event.preventDefault();
      event.stopPropagation();
      runGeneration(event);
    }

    document.addEventListener('pointerdown', triggerGenerationFromButton, true);

    function prepareRegeneration() {
      if (isGenerating) return;
      resetDemo();
      showToast('已重置为未上传图片状态，请重新填写后生成');
    }

    function loadCanvasImage(src) {
      return new Promise((resolve, reject) => {
        const image = new Image();
        image.onload = () => resolve(image);
        image.onerror = reject;
        image.src = canvasSafeImageSrc(src);
      });
    }

    function resetOptionCards(selector) {
      const cards = [...document.querySelectorAll(selector)];
      cards.forEach((item, index) => {
        item.classList.toggle('active', index === 0);
        const corner = item.querySelector('.check-corner');
        if (corner) corner.remove();
        if (index === 0) item.insertAdjacentHTML('beforeend', '<span class="check-corner"></span>');
      });
    }

    function resetDemo() {
      generationToken += 1;
      isGenerating = false;
      normalizeTemplateState();
      titleInput.value = localizedCopy[0]?.title || 'Headline Text';
      subtitleInput.value = localizedCopy[0]?.subtitle || 'More information and key features here.';
      ctaInput.value = localizedCopy[0]?.cta || 'Button';
      hasImage = false;
      uploadedImageSrc = '';
      uploadedImageName = '未上传图片';
      productImageAdjustments = {};
      posterAnchorOverrides = {};
      activePosterAnchor = null;
      selectedPosterAnchorKeys = new Set();
      clearPosterEditHistory();
      uploadInput.value = '';
      renderUploadPreview();
      statusDock.classList.remove('visible');
      progressCard.classList.remove('visible');
      materialCard.classList.remove('hidden');
      materialCard.style.filter = 'none';
      materialCard.style.aspectRatio = '';
      selectedLogoBrand = 'market';
      selectedLogoVariant = 'black';
      loadTemplateMapping(selectedTemplate || templates[0]?.id || 'template-1');
      applyRuleLogo(currentLanguageIndex, templateStyles);
      document.querySelector('.creative-logo').classList.remove('hidden');
      setTrustVisible(true);
      document.querySelectorAll('#sizeChecks input').forEach(input => input.checked = true);
      document.querySelectorAll('.language-card').forEach(card => card.classList.add('active'));
      Object.keys(posterCopyOverrides).forEach(key => delete posterCopyOverrides[key]);
      alignUngeneratedPreviewWithTemplateManager();
      currentLanguageIndex = 0;
      updateCounters();
      initializeGeneratedPreview();
      setGeneratingState(false);
      setTrustVisible(true);
    }

    function initAnchorInteractions() {
      if (!anchorCanvas) return;
      let dragState = null;
      anchorCanvas.addEventListener('pointerdown', event => {
        const fontButton = event.target.closest('[data-font-size-action]');
        if (fontButton) {
          adjustCopyFontFromToolbar(fontButton);
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        if (event.target.closest('.font-size-toolbar')) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        const gradientHandle = event.target.closest('[data-gradient-handle]');
        if (gradientHandle && draftTemplateStyles.backgroundMode === 'gradient' && gradientControlActive) {
          dragState = {
            mode: 'gradient',
            gradientHandle: gradientHandle.dataset.gradientHandle === 'start' ? 'start' : 'end'
          };
          updateGradientAngleFromPoint(event.clientX, event.clientY, dragState.gradientHandle);
          event.preventDefault();
          return;
        }
        const box = event.target.closest('.anchor-box');
        if (!box) {
          activeAnchor = null;
          selectedAnchorKeys = new Set();
          gradientControlActive = draftTemplateStyles.backgroundMode === 'gradient';
          renderAnchorEditor();
          return;
        }
        gradientControlActive = false;
        activeAnchor = box.dataset.anchor;
        const isMultiSelect = event.shiftKey || event.metaKey || event.ctrlKey;
        if (isMultiSelect) {
          if (selectedAnchorKeys.has(activeAnchor) && selectedAnchorKeys.size > 1) {
            selectedAnchorKeys.delete(activeAnchor);
          } else {
            selectedAnchorKeys.add(activeAnchor);
          }
        } else if (!selectedAnchorKeys.has(activeAnchor)) {
          selectedAnchorKeys = new Set([activeAnchor]);
        }
        const currentAnchors = anchorEditorPreviewAnchors();
        const resizeHandle = event.target.closest('.anchor-handle');
        const anchorKeys = resizeHandle
          ? [activeAnchor]
          : [...selectedAnchorKeys].filter(key => currentAnchors[key]);
        const anchors = Object.fromEntries(anchorKeys.map(key => [key, { ...currentAnchors[key] }]));
        const rect = anchorCanvas.getBoundingClientRect();
        dragState = {
          anchorKey: activeAnchor,
          anchorKeys,
          mode: resizeHandle ? 'resize' : 'move',
          resizeSide: resizeHandle?.dataset.resizeSide || 'se',
          startX: event.clientX,
          startY: event.clientY,
          rect,
          allAnchors: currentAnchors,
          anchors,
          startSide: anchorSide(anchors[activeAnchor]),
          moved: false
        };
        box.setPointerCapture?.(event.pointerId);
        renderAnchorEditor();
        event.preventDefault();
      });

      anchorCanvas.addEventListener('pointermove', event => {
        if (!dragState) return;
        if (dragState.mode === 'gradient') {
          updateGradientAngleFromPoint(event.clientX, event.clientY, dragState.gradientHandle);
          return;
        }
        const dx = ((event.clientX - dragState.startX) / dragState.rect.width) * 100;
        const dy = ((event.clientY - dragState.startY) / dragState.rect.height) * 100;
        const delta = dragState.mode === 'move'
          ? axisLockedDelta(dx, dy, dragState, event.shiftKey, 0.25)
          : { dx, dy };
        dragState.lastDx = delta.dx;
        dragState.lastDy = delta.dy;
        dragState.moved = dragState.moved || Math.abs(event.clientX - dragState.startX) > 3 || Math.abs(event.clientY - dragState.startY) > 3;
        if (dragState.mode === 'resize') {
          const base = dragState.anchors[dragState.anchorKey];
          const nextAnchor = resizeAnchorForInteraction(base, delta, dragState.resizeSide, dragState.anchorKey);
          updateAnchor(
            dragState.anchorKey,
            nextAnchor
          );
          showAlignmentGuides(
            anchorCanvas,
            getAlignmentForBounds(anchorCanvas, nextAnchor, dragState.allAnchors, dragState.anchorKeys).guides
          );
        } else {
          const nextAnchors = Object.fromEntries(dragState.anchorKeys.map(anchorKey => {
            const base = dragState.anchors[anchorKey];
            return [anchorKey, { ...base, x: base.x + delta.dx, y: base.y + delta.dy }];
          }));
          const movingBounds = anchorBounds(nextAnchors, dragState.anchorKeys);
          const alignment = getAlignmentForBounds(anchorCanvas, movingBounds, dragState.allAnchors, dragState.anchorKeys);
          updateAnchors(dragState.anchorKeys, anchorKey => {
            const next = nextAnchors[anchorKey];
            return { ...next, x: next.x + alignment.dx, y: next.y + alignment.dy };
          });
          showAlignmentGuides(anchorCanvas, alignment.guides);
        }
      });

      window.addEventListener('pointerup', () => {
        const completedDrag = dragState;
        if (dragState?.mode === 'gradient') {
          dragState = null;
          showToast('渐变角度已更新，请提交模板映射');
          return;
        }
        if (
          dragState?.mode === 'move'
          && isTemplateBaseSize()
          && dragState.anchorKeys.length === 1
          && ['image', 'title', 'subtitle'].includes(dragState.anchorKey)
          && dragState.startSide
          && anchorSide(draftTemplateAnchors[dragState.anchorKey]) !== dragState.startSide
        ) {
          maybeSwapImageTextSides(dragState.anchorKey);
          showToast('左右板块已自动互换，请提交模板映射');
        }
        dragState = null;
        clearAlignmentGuides(anchorCanvas);
        if (
          completedDrag
          && completedDrag.mode === 'move'
          && !completedDrag.moved
          && ['title', 'subtitle', 'cta'].includes(completedDrag.anchorKey)
        ) {
          openInlineCopyEditor('template', completedDrag.anchorKey);
        }
      });

      anchorCanvas.addEventListener('click', event => {
        const box = event.target.closest('.anchor-box');
        const key = box?.dataset.anchor;
        if (
          !['title', 'subtitle', 'cta'].includes(key)
          || event.shiftKey
          || event.metaKey
          || event.ctrlKey
          || event.target.closest('.anchor-handle, .font-size-toolbar')
        ) return;
        event.preventDefault();
        event.stopPropagation();
        activeAnchor = key;
        selectedAnchorKeys = new Set([key]);
        renderAnchorEditor();
        openInlineCopyEditor('template', key);
      });

      anchorCanvas.addEventListener('dblclick', event => {
        const box = event.target.closest('.anchor-box');
        const key = box?.dataset.anchor;
        if (!['title', 'subtitle', 'cta'].includes(key)) return;
        event.preventDefault();
        event.stopPropagation();
        activeAnchor = key;
        selectedAnchorKeys = new Set([key]);
        renderAnchorEditor();
        openInlineCopyEditor('template', key);
      });

      resetAnchorsButton.addEventListener('click', () => {
        draftTemplateAnchors = cloneAnchors(defaultTemplateAnchors);
        activeAnchor = null;
        selectedAnchorKeys = new Set();
        gradientControlActive = false;
        renderAnchorEditor();
        showToast('模板锚点草稿已恢复默认，请提交模板映射');
      });

      document.querySelectorAll('[data-align-action]').forEach(button => {
        button.addEventListener('click', () => alignSelectedAnchors(button.dataset.alignAction));
      });

      document.querySelectorAll('[data-poster-align-action]').forEach(button => {
        button.addEventListener('click', () => alignSelectedPosterAnchors(button.dataset.posterAlignAction));
      });

      [
        [backgroundModeSelect, 'backgroundMode'],
        [gradientAngleInput, 'gradientAngle']
      ].forEach(([control, key]) => {
        control?.addEventListener('input', () => updateDraftTemplateStyle(key, control.value));
        control?.addEventListener('change', () => updateDraftTemplateStyle(key, control.value));
      });

      [
        [backgroundColorInput, backgroundColorHexInput, 'backgroundColor'],
        [gradientStartInput, gradientStartHexInput, 'gradientStart'],
        [gradientEndInput, gradientEndHexInput, 'gradientEnd'],
        [textColorInput, textColorHexInput, 'textColor'],
        [buttonColorInput, buttonColorHexInput, 'buttonColor'],
        [buttonTextColorInput, buttonTextColorHexInput, 'buttonTextColor']
      ].forEach(([colorInput, hexInput, key]) => bindColorStyleControl(colorInput, hexInput, key));

      document.querySelectorAll('.logo-tone-card').forEach(button => {
        button.addEventListener('click', () => updateDraftTemplateStyle('logoVariant', button.dataset.logoVariant || 'black'));
      });

      commitAnchorsButton.addEventListener('click', commitTemplateMapping);
      addStyleButton?.addEventListener('click', addStyle);
      deleteStyleButton?.addEventListener('click', deleteStyle);
      addTemplateButton?.addEventListener('click', addTemplate);
      deleteTemplateButton?.addEventListener('click', deleteTemplate);
    }

    function initPosterEditInteractions() {
      if (!posterEditOverlay) return;
      let dragState = null;
      document.addEventListener('pointerdown', event => {
        if (!generated || dragState) return;
        if (event.target.closest('.poster-anchor-box, .poster-edit-panel, .poster-context-menu')) return;
        hidePosterContextMenu();
        clearPosterAnchorSelection();
      });
      materialCard?.addEventListener('pointerdown', event => {
        if (!generated || event.target.closest('.poster-anchor-box')) return;
        hidePosterContextMenu();
        clearPosterAnchorSelection();
      });
      posterEditOverlay.addEventListener('pointerdown', event => {
        if (!generated) return;
        if (event.button === 2) return;
        hidePosterContextMenu();
        const fontButton = event.target.closest('[data-font-size-action]');
        if (fontButton) {
          adjustCopyFontFromToolbar(fontButton);
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        if (event.target.closest('.font-size-toolbar')) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        const box = event.target.closest('.poster-anchor-box');
        if (!box) {
          clearPosterAnchorSelection();
          return;
        }
        activePosterAnchor = box.dataset.posterAnchor;
        selectProductFrame(activePosterAnchor === 'image');
        if (activePosterAnchor === 'image' && !hasImage) {
          selectedPosterAnchorKeys = new Set(['image']);
          renderPosterEditOverlay();
          updateUploadState();
          openUploadPicker();
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        const isMultiSelect = event.shiftKey || event.metaKey || event.ctrlKey;
        if (isMultiSelect) {
          if (selectedPosterAnchorKeys.has(activePosterAnchor) && selectedPosterAnchorKeys.size > 1) {
            selectedPosterAnchorKeys.delete(activePosterAnchor);
          } else {
            selectedPosterAnchorKeys.add(activePosterAnchor);
          }
        } else if (!selectedPosterAnchorKeys.has(activePosterAnchor)) {
          selectedPosterAnchorKeys = new Set([activePosterAnchor]);
        }
        const resizeHandle = event.target.closest('.poster-anchor-handle');
        const anchors = effectivePosterAnchorsForSize();
        const rect = materialCard.getBoundingClientRect();
        const imageRect = productFrame?.getBoundingClientRect();
        if (activePosterAnchor === 'image') {
          const geometry = productImageGeometry(undefined, imageRect);
          const adjustment = currentProductAdjustment();
          dragState = {
            anchorKey: activePosterAnchor,
            mode: 'image-pan',
            startX: event.clientX,
            startY: event.clientY,
            visualW: geometry?.visualW || imageRect?.width || rect.width,
            visualH: geometry?.visualH || imageRect?.height || rect.height,
            x: adjustment.x,
            y: adjustment.y,
            historyCaptured: false,
            moved: false
          };
        } else {
          const anchorKeys = resizeHandle
            ? [activePosterAnchor]
            : [...selectedPosterAnchorKeys].filter(key => posterEditableAnchorKeys.includes(key));
          dragState = {
            anchorKey: activePosterAnchor,
            anchorKeys,
            mode: resizeHandle ? 'resize' : 'move',
            resizeSide: resizeHandle?.dataset.resizeSide || 'se',
            startX: event.clientX,
            startY: event.clientY,
            rect,
            allAnchors: anchors,
            anchors: Object.fromEntries(anchorKeys.map(key => [key, { ...anchors[key] }])),
            historyCaptured: false,
            moved: false
          };
        }
        box.setPointerCapture?.(event.pointerId);
        renderPosterEditOverlay(anchors);
        event.preventDefault();
      });

      posterEditOverlay.addEventListener('contextmenu', event => {
        if (!generated) return;
        const box = event.target.closest('.poster-anchor-box');
        if (!box) {
          hidePosterContextMenu();
          return;
        }
        event.preventDefault();
        event.stopPropagation();
        activePosterAnchor = box.dataset.posterAnchor;
        selectProductFrame(activePosterAnchor === 'image');
        if (!selectedPosterAnchorKeys.has(activePosterAnchor)) {
          selectedPosterAnchorKeys = new Set([activePosterAnchor]);
        }
        renderPosterEditOverlay();
        if (activePosterAnchor === 'image') {
          hidePosterContextMenu();
          return;
        }
        showPosterContextMenu(event);
      });

      posterEditOverlay.addEventListener('pointermove', event => {
        if (!dragState) return;
        if (dragState.mode === 'image-pan') {
          const delta = axisLockedDelta(
            event.clientX - dragState.startX,
            event.clientY - dragState.startY,
            dragState,
            event.shiftKey,
            2
          );
          dragState.moved = dragState.moved || Math.abs(event.clientX - dragState.startX) > 3 || Math.abs(event.clientY - dragState.startY) > 3;
          panProductImageFromDrag(dragState, delta);
          return;
        }
        const dx = ((event.clientX - dragState.startX) / dragState.rect.width) * 100;
        const dy = ((event.clientY - dragState.startY) / dragState.rect.height) * 100;
        const delta = dragState.mode === 'move'
          ? axisLockedDelta(dx, dy, dragState, event.shiftKey, 0.25)
          : { dx, dy };
        dragState.moved = dragState.moved || Math.abs(event.clientX - dragState.startX) > 3 || Math.abs(event.clientY - dragState.startY) > 3;
        if (!dragState.historyCaptured) {
          pushPosterEditHistory();
          dragState.historyCaptured = true;
        }
        if (dragState.mode === 'resize') {
          const base = dragState.anchors[dragState.anchorKey];
          const nextAnchor = resizeAnchorForInteraction(base, delta, dragState.resizeSide, dragState.anchorKey);
          setPosterOverride(
            dragState.anchorKey,
            nextAnchor
          );
          showAlignmentGuides(
            materialCard,
            getAlignmentForBounds(materialCard, nextAnchor, dragState.allAnchors, dragState.anchorKeys).guides
          );
        } else {
          const nextAnchors = Object.fromEntries(dragState.anchorKeys.map(anchorKey => {
            const base = dragState.anchors[anchorKey];
            return [anchorKey, { ...base, x: base.x + delta.dx, y: base.y + delta.dy }];
          }));
          const movingBounds = anchorBounds(nextAnchors, dragState.anchorKeys);
          const alignment = getAlignmentForBounds(materialCard, movingBounds, dragState.allAnchors, dragState.anchorKeys);
          setPosterOverrides(dragState.anchorKeys, anchorKey => {
            const next = nextAnchors[anchorKey];
            return { ...next, x: next.x + alignment.dx, y: next.y + alignment.dy };
          });
          showAlignmentGuides(materialCard, alignment.guides);
        }
      });

      window.addEventListener('pointerup', event => {
        if (!dragState) return;
        const completedDrag = dragState;
        dragState = null;
        if (completedDrag.mode === 'image-pan') {
          if (completedDrag.moved) showToast('主图已在框内移动，超出部分会被裁切');
          return;
        }
        clearAlignmentGuides(materialCard);
        if (
          completedDrag.mode === 'move'
          && !completedDrag.moved
          && ['logo', 'title', 'subtitle', 'cta'].includes(completedDrag.anchorKey)
        ) {
          // Single click only selects the element; right click opens the Canva-style menu.
          return;
        }
        showToast('当前尺寸手动编辑已应用到预览和下载');
      });

      posterEditOverlay.addEventListener('wheel', event => {
        const box = event.target.closest('.poster-anchor-box[data-poster-anchor="image"]');
        if (!generated || !box || !hasImage || isGenerating) return;
        activePosterAnchor = 'image';
        selectedPosterAnchorKeys = new Set(['image']);
        selectProductFrame(true);
        renderPosterEditOverlay();
        event.preventDefault();
        beginProductWheelUndo();
        zoomProductImage(event.deltaY < 0 ? 1.08 : 0.925, event);
        finishProductWheelUndoSoon();
      }, { passive: false });

      posterEditOverlay.addEventListener('click', event => {
        if (!generated) return;
        const box = event.target.closest('.poster-anchor-box');
        const key = box?.dataset.posterAnchor;
        if (key === 'image') {
          activePosterAnchor = 'image';
          selectedPosterAnchorKeys = new Set(['image']);
          selectProductFrame(hasImage);
          renderPosterEditOverlay();
          updateUploadState();
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        if (!['title', 'subtitle', 'cta'].includes(key) || event.target.closest('.poster-anchor-handle, .font-size-toolbar')) return;
        // Single click only keeps the current selection; double click opens inline edit.
        event.preventDefault();
        event.stopPropagation();
      });

      posterEditOverlay.addEventListener('dblclick', event => {
        if (!generated) return;
        const box = event.target.closest('.poster-anchor-box');
        const key = box?.dataset.posterAnchor;
        if (!['title', 'subtitle', 'cta'].includes(key)) return;
        event.preventDefault();
        event.stopPropagation();
        activePosterAnchor = key;
        selectedPosterAnchorKeys = new Set([key]);
        renderPosterEditOverlay();
        openInlineCopyEditor('poster', key);
      });
    }

