    document.addEventListener('dragstart', event => {
      const templateCard = event.target.closest('.template-card[data-template-scope="manager"]');
      if (templateCard && !isGenerating) {
        templateDragState = { from: Number(templateCard.dataset.templateIndex) };
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', `template:${templateDragState.from}`);
        return;
      }
      const handle = event.target.closest('.drag-handle');
      if (!handle || isGenerating) return;
      settingsDragState = {
        type: handle.dataset.dragType,
        from: Number(handle.dataset.dragIndex)
      };
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', `${settingsDragState.type}:${settingsDragState.from}`);
    });

    document.addEventListener('dragover', event => {
      if (templateDragState) {
        const card = event.target.closest('.template-card[data-template-scope="manager"]');
        if (!card) return;
        event.preventDefault();
        event.dataTransfer.dropEffect = 'move';
        document.querySelectorAll('#managerTemplateGrid .template-card.template-drag-over').forEach(item => item.classList.remove('template-drag-over'));
        card.classList.add('template-drag-over');
        return;
      }
      if (!settingsDragState) return;
      const row = event.target.closest('[data-settings-row]');
      if (!row || row.dataset.settingsRow !== settingsDragState.type) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = 'move';
      document.querySelectorAll('.settings-table tr.drag-over').forEach(item => item.classList.remove('drag-over'));
      row.classList.add('drag-over');
    });

    document.addEventListener('drop', event => {
      if (templateDragState) {
        const card = event.target.closest('.template-card[data-template-scope="manager"]');
        document.querySelectorAll('#managerTemplateGrid .template-card.template-drag-over').forEach(item => item.classList.remove('template-drag-over'));
        if (!card) {
          templateDragState = null;
          return;
        }
        event.preventDefault();
        const from = templateDragState.from;
        const to = Number(card.dataset.templateIndex);
        templateDragState = null;
        reorderTemplate(from, to);
        return;
      }
      if (!settingsDragState) return;
      const row = event.target.closest('[data-settings-row]');
      document.querySelectorAll('.settings-table tr.drag-over').forEach(item => item.classList.remove('drag-over'));
      if (!row || row.dataset.settingsRow !== settingsDragState.type) {
        settingsDragState = null;
        return;
      }
      event.preventDefault();
      const to = Number(row.dataset[settingsDragState.type === 'size' ? 'sizeSettingIndex' : 'languageSettingIndex']);
      const { type, from } = settingsDragState;
      settingsDragState = null;
      if (type === 'size') reorderSizeSetting(from, to);
      if (type === 'language') reorderLanguageSetting(from, to);
    });

    document.addEventListener('dragend', () => {
      settingsDragState = null;
      templateDragState = null;
      document.querySelectorAll('.settings-table tr.drag-over').forEach(item => item.classList.remove('drag-over'));
      document.querySelectorAll('#managerTemplateGrid .template-card.template-drag-over').forEach(item => item.classList.remove('template-drag-over'));
    });

